window.__D("text/maamarim-melukatim/c001",{"p":[[1500360011,"<h3>בס\"ד. ש\"פ האזינו, שבת תשובה ה'תשכ\"ג<sup data-n=\"702\">*</sup></h3>\n<b>וכל</b> אדם לא יהי' באוהל מועד בבואו לכפר בקודש גו'<sup data-n=\"703\">1</sup> ואיתא בירושלמי<sup data-n=\"704\">2</sup> אפילו אותן שכתב בהן<sup data-n=\"705\">3</sup> ודמות פניהם פני אדם. ומבאר הצ\"צ במאמרו ד\"ה זה<sup data-n=\"706\">4</sup>, שהגילוי שנמשך כשכהן גדול הי' נכנס לקודש הקדשים הוא גילוי שלמעלה מהשתלשלות. וכדאיתא במדרש<sup data-n=\"707\">5</sup> עה\"פ<sup data-n=\"708\">6</sup> בזאת יבוא אהרן, באיזה זכות הי' אהרן נכנס לבית קדשי הקדשים כו' זכות המילה היתה נכנסת עמו, ומילה ניתנה בשמיני, דשמיני הוא למעלה מהשתלשלות. וכדאיתא במדרש<sup data-n=\"709\">7</sup> עה\"פ<sup data-n=\"710\">8</sup> סוד הוי' ליראיו איזהו סוד הוי' זו מילה. שהגילויים דהשתלשלות הם מבחי' גליא דקוב\"ה, והגילוי שנמשך ע\"י מילה הוא מבחי' סתים דקוב\"ה, ולכן נק' סוד הוי', דסוד הוא מה שהוא סתום ונעלם. ובשעה שהכה\"ג הי' נכנס לקודש הקדשים נמשך הגילוי דסוד הוי'. ולכן לא היו שם אפילו אותן שכתב בהן ודמות פניהם פני אדם, כי לגבי גילוי זה אין מקום לנבראים, אפילו לא להמלאכים שדמות פניהם פני אדם.\n<b>וצריך</b> להבין, דמזה שבכדי שהכהן גדול יוכל ליכנס לקודש הקדשים הוא ע\"י זכות המילה שניתנה בשמיני, מוכח, שהגילוי דלמעלה מהשתלשלות שהי' בקדה\"ק הוא מצד מעלת קדה\"ק עצמו (ולא שע\"י כניסתו של הכהן גדול לקדה\"ק נמשך הגילוי), ואעפ\"כ, זה שוכל אדם לא יהי' גו' אפילו אותן שכתב בהן ודמות פניהם פני אדם הוא דוקא בבואו של הכהן גדול לקדה\"ק לכפר בקודש. דמזה מובן, שהגילוי שנמשך ע\"י העבודה דכהן גדול בקדה\"ק הוא נעלה יותר מהגילוי שהי' בקדה\"ק מצד עצמו.\nב) <b>ויובן</b> זה ע\"פ המבואר בהמאמר<sup data-n=\"711\">9</sup> דתשובה (וכפרה<sup data-n=\"712\">10</sup>) הם בבחינת שמיני שלמעלה מהשתלשלות. דגדולה תשובה שמביאה רפואה לעולם<sup data-n=\"713\">11</sup>, ורפואה קבעוהבשמינית<sup data-n=\"714\">12</sup> דזה שרפואה קבעוה בשמינית הוא ע\"ד<sup data-n=\"715\">13</sup> מילה שניתנה בשמינית. וזהו ששבעה ימים קודם יום הכפורים מפרישין כהן גדול מביתו<sup data-n=\"716\">14</sup> וכל שבעת הימים מרגילין אותו בעבודות<sup data-n=\"717\">15</sup>, כי שבעת הימים הם בחינת השתלשלות, ויום הכפורים, יום השמיני (שלאחרי שבעת הימים) הוא למעלה מהשתלשלות. וזהו גם ענין שמונה ההזיות ביום הכפורים אחת למעלה ושבע למטה<sup data-n=\"718\">16</sup>, שהאחת שלמעלה מהשבע היא בחינת אחת שאלתי<sup data-n=\"719\">17</sup>, אחת היא יונתי<sup data-n=\"720\">18</sup>. ומזה מובן, דבשמיני שלמעלה מהשתלשלות כמה דרגות. שמיני דמילה ועד\"ז<sup data-n=\"721\">19</sup> דקודש הקדשים שהכניסה לקודש הקדשים היא ע\"י זכות המילה. שמיני דתשובה שנעלה יותר משמיני דמילה, (דמילה היא מצוה, ותשובה שמכפרת על הענינים שפגמו בתורה ומצוות היא למעלה מתורה ומצוות (כדלקמן סעיף ח)). שמיני דיום הכפורים, שהתשובה דיום הכפורים היא נעלית יותר מהתשובה דכל השנה (גם מהתשובה דעשרת ימי תשובה<sup data-n=\"722\">20</sup>), שלכן יום הכפורים הוא זמן תשובה לכל<sup data-n=\"723\">21</sup>, וביום הכפורים עצמו – שמונה ההזיות שבקודש הקדשים אחת למעלה ושבע למטה, שהאחת היא לפני השבע<sup data-n=\"724\">22</sup>.\n<b>ויש</b> לומר, דשמיני שלאחרי שבעה הוא גילוי שלמעלה מהשתלשלות שנמשך לאחרי וע\"י הענינים דהשתלשלות, ומזה שהמשכת גילוי זה הוא ע\"י הענינים דהשתלשלות מוכח שגילוי זה שייך להשתלשלות, ואחת שלפני השבע הוא גילוי שלמעלה מהשתלשלות שלמעלה משייכות להשתלשלות<sup data-n=\"725\">23</sup>, [אלא <i>שלאח\"ז</i> נמשך הגילוי בהשתלשלות, שבע שלאחרי האחת, כדלקמן סעיף ז]. ועפ\"ז יובן הטעם על זה שוכל אדם לא יהי' גו' הוא דוקא בבואו לכפר בקודש, כי לגבי הגילוי שהי' בקדה\"ק מצד עצמו [שהוא ע\"ד שמיני דמילה, שמיני שאחרי שבעה], למעלה מהשתלשלות ששייך להשתלשלות, יש נתינת מקום למציאות. וע\"י העבודה דכהן גדול ביום הכפורים בקודש הקדשים נמשך הגילוי דלמעלה מהשתלשלות שלמעלה משייכות להשתלשלות, ולגבי גילוי זה כל אדם לא יהי', אפילו אותן שדמות פניהם פני אדם.ג) <b>ויובן</b> זה בהקדים מ\"ש<sup data-n=\"726\">24</sup> כי המצוה הזאת אשר אנכי מצוך, ומבואר בלקו\"ת<sup data-n=\"727\">25</sup> דכל המצוות נקראים מצוות הוי', והמצוה הזאת שהיא מצות התשובה, אנכי מצוך, אנכי מי שאנכי (שלמעלה מהוי'). והענין הוא<sup data-n=\"728\">26</sup>, דענין המצוות הוא להמשיך גילוי שם הוי' בעולם. דבריאת העולם היא משם אלקים, אלקים בגימטריא הטבע<sup data-n=\"729\">27</sup>, וע\"י המצוות נמשך בעולם גילוי שם הוי' שלמעלה מהטבע. ועיקר הגילוי דהוי' שע\"י קיום המצוות הוא בהאדם שמקיים את המצוות (ועי\"ז נמשך הגילוי גם בעולם). וזהו שהדבור הראשון דמתן תורה הוא אנכי<sup data-n=\"730\">28</sup> הוי' אלקיך, שענין המצוות שניתנו במ\"ת הוא שהוי' יהי' אלקיך.\n<b>והנה</b> זה שע\"י המצוות אפשר להמשיך בעולם גילוי שם הוי', הגם שהתהוות העולם היא ע\"י שם אלקים שמעלים ומסתיר על שם הוי', הוא, לפי שכוונת ההעלם דשם אלקים (מלכתחילה) היא בכדי שע\"י התומ\"צ יומשך הגילוי דהוי'. וכמ\"ש<sup data-n=\"731\">29</sup> אשר עשה האלקים את האדם ישר, שהכוונה בההתהוות שמשם אלקים (האלקים עשה) היא שהאדם ע\"י קיום המצוות ימשיך להיות ישר יחזו פנימו<sup data-n=\"732\">30</sup>, שלמטה יהי' הגילוי כמו למעלה. וכאשר המה בקשו חשבונות רבים<sup data-n=\"733\">31</sup> (היפך כוונת הבריאה), הנה בכדי שיומשך הגילוי דשם הוי' באדם ועל ידו בעולם, צריכה להיות ההמשכה מאנכי שלמעלה מהוי', דהמשכה זו היא ע\"י התשובה שלמעלה מהמצוות. וכמ\"ש<sup data-n=\"734\">32</sup> שובה ישראל עד הוי' אלקיך כי כשלת בעוניך, שבכדי שיהי' הוי' אלקיך לאחרי שכשלת בעוניך אין מספיק קיום המצוות שמכאן ולהבא וצריך להיות שובה ישראל.\nד) <b>וביאור</b> הענין בפרטיות יותר יובן בהקדים מה שאמרו רז\"ל<sup data-n=\"735\">33</sup> שאלו לחכמה הנפש החוטאת במה תתכפר<sup data-n=\"736\">34</sup> ואמרה הנפש<sup data-n=\"737\">35</sup> החוטאת היא תמות<sup data-n=\"738\">36</sup>, שאלו לנבואה ואמרה חטאים<sup data-n=\"739\">37</sup> תרדף רעה<sup data-n=\"738\">36</sup>, שאלו לתורה ואמרה יביא אשם ויתכפר לו, שאלו להקב\"ה ואמר יעשה תשובה ויתכפר לו. הדא הוא דכתיב<sup data-n=\"740\">38</sup> טוב וישר הוי'על כן יורה חטאים בדרך. ויש לומר, דזה שהחכמה אמרה שע\"י מיתה תהי' כפרה לנפש החוטאת הוא לפי שגם החכמה היא למעלה מהאור שמתלבש בעולם. שמצד האור שמתלבש בעולם, מכיון שהחטא הוא היפך כוונת בריאת העולם, א\"א להיות כפרה על זה, וזה שמצד החכמה ישנה כפרה לנפש החוטאת הוא כי החכמה היא למעלה מעולם. [דהגם שהכוונה בחכמה כאן היא לחכמה תתאה<sup data-n=\"741\">39</sup>, חכמה שבמלכות, הרי גם החכמה שבמלכות היא למעלה מהמלכות עצמה]. אלא שמצד החכמה, הכפרה היא ע\"י מיתה, פירוד הנפש מהגוף. [ויש לומר, שהוא מדה כנגד מדה. דענין המצוות הוא להמשיך הוי' באלקים, דאלקים הוא שרש הכלים שהם דוגמת הגוף והאור דהוי' שנמשך בהם הוא דוגמת חיות הנפש שמחי' את הגוף<sup data-n=\"742\">40</sup>. וכיון שע\"י החטאים גרם שלא יומשך הגילוי דהוי' באלקים, לכן ענשו (שעי\"ז הוא כפרתו) הוא פירוד הנפש מהגוף, מדה כנגד מדה]. ומצד הנבואה שהיא בנו\"ה<sup data-n=\"743\">41</sup> (למעלה מחכמה תתאה)<sup data-n=\"741\">39</sup>, נפש החוטאת מתכפרת גם ע\"י יסורים. והחידוש במענה התורה ומכ\"ש במענה הקב\"ה, שהכפרה היא ע\"י קרבן ותשובה, ואין צריך ליסורים. והחילוק שבין מענה התורה למענה הקב\"ה, אף שגם מענה התורה יביא אשם ויתכפר לו הו\"ע התשובה (שאז דוקא מכפר הקרבן), מבאר הצ\"צ במאמר הנ\"ל<sup data-n=\"744\">42</sup>, שמצד התורה, חכמתו של הקב\"ה, ע\"י התשובה נעשים הזדונות (רק) כשגגות (וע\"י הקרבן מתכפר שוגג זה), ומצד הקב\"ה שלמעלה מתורה, ע\"י התשובה <i>מתכפרים</i> הזדונות, ויתירה מזו, שנהפכים לזכיות.\n<b>וע\"פ</b> המובא לעיל (סעיף ג) דתשובה היא באור אין סוף שלמעלה מהשתלשלות, יש לומר, דהטעם על זה שגם מצד התורה מועלת תשובה (שהזדונות יהיו כשגגות), אף שתורה היא בחכמה (השתלשלות), הוא, כי בחכמה שורה אוא\"ס שלמעלה מהחכמה<sup data-n=\"745\">43</sup>, ועד\"ז הוא בנוגע לתורה כמו שנמשכה בהמדות חג\"ת, שהתורה היא בתפארת<sup data-n=\"746\">44</sup>, קו האמצעי, ות\"ת עולה עד הכתר. אלא שהאור שלמעלה מהשתלשלות שבתורה, כיון שהוא נמשך בהשתלשלות (בחכמה ובת\"ת) הוא במדידה והגבלה. ולכן הכח שבתשובה מצד אוא\"ס שבתורה הוא רק שיהיו כשגגות. ומענה הקב\"ה הוא המשכת אוא\"ס שלמעלה מהשתלשלות כמו שהוא בעצמותו (שלמעלה מהמשכה בהשתלשלות), דהמשכה זו היא למעלה ממדידה והגבלה. ולכן ע\"י התשובה שמצד מענה הקב\"ה <i>מתכפרים</i> הזדונות (ולא רק נעשים כשגגות), ויתירה מזו שנהפכים לזכיות.\nה) <b>ויש</b> לומר, דזה שגם מענה הקב\"ה שלמעלה מהתורה נתגלה ע\"י התורה הוא, כי זה שהתורה היא בקו האמצעי הוא לפי ששרשה הוא בעצמות אוא\"סשלמעלה מקוין, אלא שאח\"כ נמשכה בקו האמצעי. ולכן, נוסף על שיש בה האור שלמעלה מהשתלשלות כמו שנמשך בקו האמצעי (שלכן גם מצד מענה התורה מועלת תשובה שזדונות יהיו כשגגות), מתגלה על ידה גם עצמות אוא\"ס שלמעלה מקוין, מענה הקב\"ה יעשה תשובה ויתכפר לו. היינו, דזה שאמרה תורה יביא אשם ויתכפר לו (שע\"י תשובה נעשים זדונות רק כשגגות) הוא בדרגת התורה כמו שנמשכה בקו האמצעי, וזה שגם מענה הקב\"ה יעשה תשובה ויתכפר לו הוא חלק בתורה (שבעל פה) הוא מצד שרש התורה בעצמות אוא\"ס שלמעלה מקוין<sup data-n=\"747\">45</sup>.\n<b>ועפ\"ז</b> יש לבאר מה שאמרו רז\"ל<sup data-n=\"748\">46</sup> יבוא טוב זה משה כו' ויקבל טוב זה תורה כו' מטוב זה הקב\"ה דכתיב<sup data-n=\"749\">47</sup> טוב הוי' לכל, לטובים אלו ישראל דכתיב<sup data-n=\"750\">48</sup> הטיבה ה' לטובים. וצריך להבין, דאיתא בגמ' סנהדרין<sup data-n=\"751\">49</sup> כתיב<sup data-n=\"749\">47</sup> טוב ה' לכל וכתיב<sup data-n=\"752\">50</sup> טוב ה' לקוויו משל לאדם יש לו פרדס כשהוא משקה משקה את כולו כשהוא עודר אינו עודר אלא טובים שבהם. וכיון שנתינת התורה היא (רק) לטובים אלו ישראל, הי' צריך לכאורה להביא הפסוק טוב הוי' לקוויו. [וע\"פ הידוע<sup data-n=\"753\">51</sup> דטוב הוי' לכל הוא השפעה חיצונית וטוב הוי' לקוויו הוא השפעה פנימית, צריך ביאור עוד יותר מה שמביא בענין נתינת התורה שהוא השפעה פנימית את הפסוק טוב הוי' לכל ולא טוב הוי' לקוויו]. ויש לומר הביאור בזה<sup data-n=\"754\">52</sup>, דזה שבתשובה כתיב טוב וישר הוי', הכוונה היא לבחי' טוב הוי' לכל<sup data-n=\"755\">53</sup>, שהרי תשובה מכפרת גם על הזדונות. ולכן אומר ויקבל טוב זו תורה כו' מטוב זה הקב\"ה דכתיב טוב הוי' לכל, כי הטוב דתורה מצד שרשה הוא בחי' טוב וישר הוי'<sup data-n=\"756\">54</sup>, טוב הוי' לכל.\nו) <b>והנה</b> הגם דזה שתשובה מכפרת הוא לפי שהמענה שע\"י התשובה הוא מלמעלה מהשתלשלות, הכפרה שע\"י תשובה היא (לא באופן של ויתור, שמוותרים על החטאים, אלא) פעולה פנימית בהאדם השב, שמתתקנים הפגמים שלו. וזהו טוב וישר הוי' על כן יורה חטאים בדרך, דטוב הוא שמשפיע לכל. וכמבואר במק\"א<sup data-n=\"757\">55</sup>החילוק בין טוב לחסד, דחסד שייך להמקבל ולכן השפעת החסד היא דוקא למי שראוי [אלא שמצד מדת החסד אינו מדקדק, וכשיש להמקבל איזו מעלה הוא כבר ראוי שישפיעו לו], וטוב הוא מצד המשפיע ולכן ההשפעה היא לכולם (גם לשאינם ראויים). וישר הוא שלמטה הוא כמו למעלה<sup data-n=\"758\">56</sup>. וזהו שההמשכה שע\"י התשובה היא מבחינת טוב וישר, דזה שתשובה מכפרת על הזדונות הוא לא מפני שהאדם ראוי לזה אלא מפני הטוב דהקב\"ה, המשכת אוא\"ס שלמעלה מהשתלשלות. וזה שע\"י המשכה זו מתתקנים הפגמים שלו, והתיקון הוא בפנימיות, הוא לפי שהמשכת הטוב היא באופן דחסד, שהאדם השב הוא כמו כלי לההמשכה.\nז) <b>והנה</b> זה שע\"י תשובה מתכפרים הזדונות ועד שנהפכים לזכיות הוא גם בכל השנה. ועאכו\"כ בעשרת ימי תשובה, שאז התשובה היא נעלית יותר<sup data-n=\"759\">57</sup>. ומעלת התשובה דיום הכפורים היא שהכפרה דיום הכפורים היא מצד עיצומו של יום<sup data-n=\"760\">58</sup>, שכפרה זו היא נעלית יותר מהכפרה שע\"י התשובה. וזה שיום הכפורים אין מכפר אלא לשבים הוא, שהמשכת הענין דעיצומו של יום <i>להאדם</i> היא ע\"י התשובה. והענין הוא<sup data-n=\"761\">59</sup>, דזה שע\"י התשובה מתכפרים הענינים שעשו היפך הרצון הוא לפי שע\"י התשובה נמשך מעצמות אוא\"ס בעל הרצון שאינו מוכרח בהרצון. דזה שבעל הרצון אינו מוכרח בהרצון הו\"ע ההפלאה דאוא\"ס ולא עצמות אוא\"ס ממש<sup data-n=\"762\">60</sup>. וכיון שענין ההפלאה דבעל הרצון הוא שהוא מופלא <i>מהרצון</i>, הרי זה מוכיח שיש להרצון שייכות אליו [וכדמוכח גם מזה שנקרא בשם בעל <i>הרצון</i>], לכן צריכה להיות סליחה וכפרה על זה שעשו היפך הרצון. משא\"כ לגבי עצמות אוא\"ס שלמעלה גם מבעל הרצון, אין שייך פגם מלכתחילה. וזהו\"ע עיצומו של יום מכפר, שהכפרה מצד עיצומו של יום היא (לא באופן של פעולה, אלא) שביום זה מתגלה ההתקשרות של עצם הנשמה עם העצמות (שלמעלה מבעל הרצון), שלגבי דרגא זו אין פגם מלכתחילה. והטעם שהמשכת הענין דעיצומו של יום היא ע\"י התשובה, הוא, כי תיקון הפגמים ע\"י הגילוי דעצם הנשמה (שמצד עצם הנשמה אין שייך פגם מלכתחילה), אין שייך (כ\"כ) לענינם של כחות הגלויים עצמם<sup data-n=\"763\">61</sup>, ובכדי שהכפרה שע\"י גילוי עצם הנשמה תהי' בפנימיות, הוא ע\"י התשובה.\n[<b>ויש</b> להוסיף, שהמשכת הכפרה דעיצומו של יום בכחות הגלויים ע\"י התשובה, כיון שענין התשובה הוא שהאדם <i>יוצא</i> מההגבלות שלו, לכן ההמשכה שע\"י התשובה היא בהכחות כמו שהם בתנועה דהעלאה. ובכדי שהכפרה דעיצומו של יום תומשך גם בכחות הגלויים כמו שהם בהציור שלהם, הוא ע\"י <i>מצות</i> התשובה, דביוםהכפורים חייבים הכל לעשות תשובה<sup data-n=\"764\">62</sup>. ולהעיר, דג' ענינים אלה שביום הכפורים הם דוגמת ג' הענינים שבתק\"ש. המצוה דתק\"ש, ענין התשובה המרומז בתק\"ש, והביטול פנימי שמצד עצם הנשמה<sup data-n=\"765\">63</sup>]. ויש לומר, שזהו\"ע שמונה ההזיות שהיו בקודש הקדשים, אחת למעלה ושבע למטה, אחת למעלה היא גילוי היחידה<sup data-n=\"766\">64</sup>, שהיא מיוחדת עם העצמות, ושבע למטה (<i>שלאחרי</i> האחת) הוא שגילוי היחידה (למעלה מהשתלשלות שבאדם) יומשך בכחות הגלויים, השתלשלות שבאדם<sup data-n=\"767\">65</sup>.\nח) <b>ועפ\"ז</b> יש לבאר החילוק שבין ג' הענינים דשמיני, שמיני דמילה ושמיני דתשובה ושמיני דיום הכפורים, דמילה היא מצוה, וכיון שכוונת הבריאה מלכתחילה היא שישראל יקיימו את כל המצוות וימשיכו הגילויים שנמשכים על ידם, לכן הגילויים שנמשכים ע\"י המצוות (כולל גם מצות מילה) אינם אור חדש ממש<sup data-n=\"768\">66</sup>, מכיון שכוונת הבריאה מלכתחילה היא שישראל ימשיכו גילויים אלו. ואף שהגילוי שנמשך ע\"י כל המצוות הוא הגילוי דהוי' והגילוי שנמשך ע\"י המילה הוא למעלה מהוי', וכמבואר בתו\"א<sup data-n=\"769\">67</sup> דמי יעלה לנו השמימה<sup data-n=\"770\">68</sup> הוא ר\"ת מילה וס\"ת הוי'<sup data-n=\"771\">69</sup> שזה מורה שמילה היא למעלה מהוי', מ\"מ, כיון שבריאת העולמות מלכתחילה היא שע\"י מצות מילה ימשיכו אור זה, הוא אור שיש לו שייכות לעולמות. [ויש לומר, שבכללות, גם אור זה נכלל בהוי'. כי בהוי' לשון מהווה<sup data-n=\"772\">70</sup> שתי דרגות. המקור שממנו נעשה התהוות העולם, והרצון להוות את העולם<sup data-n=\"773\">71</sup>. וכיון שהרצון להוות הוא שיומשך גם הגילוי שע\"י המילה, הרי גילוי זה נכלל בהוי'. וזה שהגילוי שע\"י המילה הוא למעלה מהוי' הוא שגילוי זה הוא למעלה ממקור ההתהוות]. ושמיני דתשובה הוא גילוי אור חדש. דע\"י שחטא ופגם והעביר את הדרך (היפך הכוונה דבריאת האדם שהי' באופן דעשה האלקים את האדם ישר) ואח\"כ מתקן זה ע\"י התשובה, עי\"ז נמשך אור חדש שלא הי' (כביכול) גם בכוונת הבריאה. אלא שאור זה הוא מבעל הרצון, שיש לו שייכות להרצון והכוונה דהבריאה. ושמיני דיום הכפורים, שעיצומושל יום מכפר, הוא גילוי עצמות אוא\"ס שלמעלה גם מבעל הרצון. אלא שגילוי ענין זה הוא בעיקר בעת כניסת הכה\"ג לקודש הקדשים. ולכן, גם השמיני דיום הכפורים הוא שמיני שלאחרי שבעת הימים שלפני יום הכפורים, כי בכללות, גם השמיני דיום הכפורים הוא למעלה מהשתלשלות ששייך להשתלשלות (בעל הרצון), משא\"כ הסדר בשמונה ההזיות שבקודש הקדשים, הוא שהאחת היא לפני השבעה.\nט) <b>וזהו</b> וכל אדם לא יהי' באוהל מועד בבואו לכפר בקודש, דזה שכל אדם לא יהי' גו' אפילו אותן שדמות פניהם פני אדם הוא דוקא בבואו של הכה\"ג בקודש הקדשים לכפר בקודש, כי הגילוי דלמעלה מהשתלשלות שהי' בקודש הקדשים מצד עצמו, יש לו שייכות להשתלשלות, ולגבי גילוי זה יש מקום למלאכים. אבל בבואו (של הכה\"ג לקודש הקדשים) לכפר בקודש, דזה שע\"י עבודתו של הכה\"ג בקודש הקדשים נמשכה כפרה לכל ישראל הוא לפי שע\"י עבודתו מתגלה ההתקשרות דעצם הנשמה עם העצמות, דבעצמות אוא\"ס אין שום נתינת מקום למלאכים, ישראל ומלכא בלחודוהי<sup data-n=\"774\">72</sup>, לכן אז כל אדם לא יהי' אפילו אותן שדמות פניהם פני אדם.\n<b>ולהוסיף</b><sup data-n=\"775\">73</sup><b>,</b> שבתפלת נעילה מאיר גילוי זה עוד יותר מאשר במוסף דיום הכפורים שבה אומרים סדר העבודה דכהן גדול ביום הכפורים. כי החמשה תפלות דיום הכפורים הם כנגד חמשה דרגות שבנשמה, נפש רוח נשמה חי' ויחידה. דג' תפלות הראשונות הם בנר\"נ, ותפלת מוסף דיום הכפורים היא בחי', והגילוי דיחידה הוא (בעיקר) בתפלת נעילה. ולכן נקראת בשם נעילה, כי אז ננעלים כל השערים וגם נבראים הכי עליונים (ואפילו נאצלים וכו') אין יכולים ליכנס, ישראל ומלכא בלחודוהי.\n<b>וזהו</b> גם מ\"ש בזהר<sup data-n=\"776\">74</sup> עה\"פ<sup data-n=\"777\">75</sup> ולא עמד איש אתו בהתוודע יוסף אל אחיו, בזמנא דקוב\"ה הוה מתחבר בהו ישראל כו' בגין כך ביום<sup data-n=\"778\">76</sup> השמיני עצרת תהי' לכם, דיש לומר שענין קוב\"ה מתחבר בהו בישראל הוא גילוי היחידה וההתקשרות העצמית דהעצמות עם עצם הנשמה. [ויש לומר שהשייכות דענין זה ליוסף, דשם יוסף הוא על שם יוסף הוי' לי בן אחר<sup data-n=\"779\">77</sup>, שגם אחר נעשה בן<sup data-n=\"780\">78</sup>, כי ע\"י גילוי התקשרות העצמית דהעצמות בישראל (בהתוודע יוסף אל אחיו) מתגלה שגם אחר הוא בן]. וגילוי זה הוא בשמיני עצרת, וכידוע שבשמיני עצרת ישנם כל העניניםשבראש השנה ויום הכפורים, אלא שבשמיני עצרת הם בקו השמחה, ולכן ביום השמיני עצרת תהי' <i>לכם</i>, יהיו<sup data-n=\"781\">79</sup> לך לבדך ואין לזרים אתך.\n**********",[["702","*","יצא לאור ב<b>קונטרס וא\"ו תשרי – תנש\"א</b>, \"לקראת ו' תשרי, יום היאָרצייט של הרבנית הצדקנית מרת חנה תנצב\"ה (אמו של – יבלח\"ט – כ\"ק אדמו\"ר שליט\"א), נסתלקה שבת תשובה בעת עלות המנחה שנת תשכ\"ה . . <i>וא\"ו תשרי</i>,<i> שנת ה'תנש\"א</i>\".\nהמאמר הוא המשך למאמר שלפניו ד\"ה יבחר לנו גו' דראש השנה שנה זו (תשכ\"ג) – לעיל ע' א ואילך."],["703","1","אחרי טז, יז."],["704","2","יומא פ\"א ה\"ה."],["705","3","יחזקאל א, יו\"ד."],["706","4","נדפס באוה\"ת דרושי יוהכ\"פ ע' א'תקנה ואילך. וראה שם ע' א'תקנח."],["707","5","שמו\"ר פל\"ח, ח."],["708","6","אחרי טז, ג."],["709","7","ב\"ר פמ\"ט, ב."],["710","8","תהלים כה, יד."],["711","9","ע' א'תקנו."],["712","10","הרפואה הבאה ע\"י התשובה. משא\"כ תשובה עצמה היא ברכה החמישית."],["713","11","יומא פו, סע\"א."],["714","12","מגילה יז, ב."],["715","13","כ\"ה הלשון באוה\"ת שם. וראה מגילה שם."],["716","14","ריש מס' יומא. רמב\"ם הל' עבודת יוהכ\"פ פ\"א ה\"ג."],["717","15","יומא יד, א במשנה. רמב\"ם שם ה\"ה."],["718","16","יומא נג, ב במשנה. רמב\"ם שם פ\"ג ה\"ה."],["719","17","תהלים כז, ד."],["720","18","שה\"ש ו, ט. וראה לקמן הערה 23."],["721","19","אבל למעלה יותר. כמובן מזה שהמילה היא הקדמה שבזכותה הי' נכנס לקדה\"ק."],["722","20","אף שהתשובה דעשי\"ת \"היא יפה ביותר ומתקבלת היא מיד\" (רמב\"ם הל' תשובה פ\"ב ה\"ו) לפי שבעשי\"ת הוא גילוי שלמעלה מהשתלשלות, מ\"מ התשובה דיוהכ\"פ נעלית יותר. ולכן, בעשי\"ת עצמם, ז' הימים שקודם יוהכ\"פ הם בחי' השתלשלות, ויוהכ\"פ (השמיני) הוא למעלה מהשתלשלות, כנ\"ל בפנים."],["723","21","רמב\"ם שם ה\"ז."],["724","22","להעיר, דשבע ההזיות מפורשים בתושב\"כ, והזי' הראשונה למדו מפי השמועה (רמב\"ם שבהערה 16). ואולי יש לומר, שהוא ע\"ד המעלה דניסוך המים על ניסוך היין (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381045\" data-slug=\"likkutei-torah\" data-id=\"4001381045\">לקו\"ת סוכות פ, ב</a>. ובכ\"מ)."],["725","23","להעיר מהמובא לעיל (מהמאמר דהצ\"צ) ש\"אחת למעלה\" היא בחי' \"אחת היא יונתי\". וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381288\" data-slug=\"likkutei-torah\" data-id=\"4001381288\">לקו\"ת שה\"ש מ, א</a>: ולפיכך קרויין אחת שהיא בחינת מקבל מאחד. וראה תוספות ד\"ה עד אחת – מנחות יח, א."],["726","24","נצבים ל, יא."],["727","25","ד\"ה כי המצוה – נצבים מה, ב."],["728","26","ראה לקו\"ת שם מה, ג-ד. וראה גם אוה\"ת שם ע' א'תקנה-ו."],["729","27","פרדס שער יב פרק ב. ראשית חכמה שער התשובה פ\"ו ד\"ה והמרגיל (קכא, ב). של\"ה פט, א. קפט, א. שח, ב. שו\"ת חכם צבי סי\"ח. שער היחוד והאמונה רפ\"ו."],["730","28","יתרו כ, ב."],["731","29","קהלת ז, כט. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380474\" data-slug=\"likkutei-torah\" data-id=\"4001380474\">לקו\"ת שלח מ, ג</a>."],["732","30","תהלים יא, ז. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380811\" data-slug=\"likkutei-torah\" data-id=\"4001380811\">לקו\"ת ראה כג, ד</a> ואילך – הובא בלקו\"ת שלח שם."],["733","31","לשון הכתוב קהלת שם."],["734","32","הושע יד, ב."],["735","33","ירושלמי מכות פ\"ב ה\"ו. יל\"ש יחזקאל רמז שנח. יל\"ש תהלים רמז תשב."],["736","34","כ\"ה הלשון בלקו\"ת דרושי שבת שובה סז, ד."],["737","35","יחזקאל יח, ד. שם, כ."],["738","36","כ\"ה הגירסא בס' ווי העמודים (לבן השל\"ה) פכ\"א. וראה גם לקו\"ת שבת שובה שם. ולהעיר, שע\"פ גירסא זו מובן הסדר דד' התשובות, שכל אחד מקיל על הקודמו."],["739","37","משלי יג, כא."],["740","38","תהלים כה, ח."],["741","39","ראה סה\"מ קונטרסים ח\"א קלג, ב, דחכמה היא חכמה תתאה ונבואה היא נו\"ה."],["742","40","ראה הקדמת תקו\"ז פתח אלי' \"וכמה גופין תקינת לון כו' וההוא נביעו איהו כנשמתא לגופא דאיהי חיים לגופא\"."],["743","41","תניא – אגה\"ק סי\"ט. ובכ\"מ."],["744","42","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010190\" data-slug=\"or-hatorah-hb\" data-id=\"8159010190\">אוה\"ת יוהכ\"פ ס\"ע א'תקנז</a> ואילך. וראה גם המשך תער\"ב ח\"ג ע' א'רנב."],["745","43","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380527\" data-slug=\"likkutei-torah\" data-id=\"4001380527\">לקו\"ת קרח נג, ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל\"ה</a> בהגהה. ובכ\"מ."],["746","44","דג' העמודים שעליהם העולם עומד הם בחג\"ת: גמ\"ח – חסד, עבודה – גבורה ותורה – ת\"ת."],["747","45","ראה סה\"מ תער\"ב ע' לב \"ומאחר שבתורה נאמרה מצות התשובה בהכרח שהתורה ג\"כ שרשה בבחי' העצמות . . ומ\"ש בילקוט אמרה תורה יביא קרבן כו' זהו כמו שהתורה היא בבחי' חכמה\"."],["748","46","מנחות נג, ב."],["749","47","תהלים קמה, ט."],["750","48","שם קכה, ד."],["751","49","לט, ב."],["752","50","איכה ג, כה."],["753","51","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450586\" data-slug=\"or-hatorah-hb\" data-id=\"8316450586\">אוה\"ת יוהכ\"פ ע' א'תקנז</a>. וראה בארוכה סה\"ל דא\"ח צ\"צ ערך טוב ע' א'נו ואילך."],["754","52","ובאוה\"ת יוהכ\"פ שם – באו\"א."],["755","53","הכוונה <i>להמעלה</i> שבטוב ה' לכל, שנמשכת גם לאלו שחטאו. אבל היא השפעה <i>פנימית</i>, ולכן היא נמשכת דוקא לשבים* – ראה אוה\"ת יוהכ\"פ שם. סה\"מ עת\"ר ע' צד. ובכ\"מ."],["756","54","ראה סה\"מ תער\"ב שבהערה 45 – לאחרי שמבאר דזה שבתורה נאמרה מצות התשובה הוא לפי ששורש התורה הוא בהעצמות, מוסיף, דזה שהתורה נק' טוב הו\"ע טוב וישר הוי'."],["757","55","סה\"מ עת\"ר ע' צח ואילך.\n*) <i>אלא שאין זה </i><b>שהם</b><i> ראויים לזה כי אם מצד הטוב דלמעלה</i>,<i> טוב הוי' לכל – ראה לקמן ס\"ו</i>."],["758","56","כנ\"ל סעיף ג."],["759","57","כנ\"ל הערה 20."],["760","58","ראה רמב\"ם הל' תשובה פ\"א ה\"ג \"ועצמו של יוהכ\"פ מכפר <i>לשבים</i>\". ומזה מוכח, דזה שעיצומו של יום מכפר הוא גם לדעת רבנן שיוהכ\"פ אין מכפר אלא על השבים (שבועות יג, א)."],["761","59","בהבא לקמן ראה גם ד\"ה שובה ישראל (הב') תשל\"ז (לקמן ע' צח ואילך) ס\"ד. <i>וש\"נ</i>."],["762","60","ראה עד\"ז בהמאמר שלפנ\"ז (ד\"ה יבחר לנו שנה זו (תשכ\"ג)) – ס\"ה וס\"ט (לעיל ע' ה; ע' ח)."],["763","61","ראה עד\"ז ד\"ה השקיפה ממעון קדשך תשכ\"ז סוף סעיף ט (לקמן ח\"ג ע' רנג)."],["764","62","רמב\"ם הל' תשובה פ\"ב ה\"ז. והיינו דנוסף למצות התשובה שישנה בכל השנה – גם התשובה <i>דיוהכ\"פ</i> היא (מצוה ו)חיוב."],["765","63","ראה ד\"ה יבחר לנו הנ\"ל (הערה 60) סעיף ט (ע' ח)."],["766","64","ראה לעיל הערה 23."],["767","65","ראה עד\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381296\" data-slug=\"likkutei-torah\" data-id=\"4001381296\">לקו\"ת שה\"ש מב, א</a>. אוה\"ת (יהל אור) לתהלים ע' קב."],["768","66","ראה עד\"ז לקמן ס\"ע ריח ואילך. לקמן ח\"ד ס\"ע קעב ואילך."],["769","67","לך לך יג, סע\"ב. וראה גם אוה\"ת יוהכ\"פ ע' א'תקנה. א'תקנו.\nבתו\"א שם (ועד\"ז באוה\"ת שם) \"למול את ערלת הלב והו\"ע התשובה\". ויש לומר, שזהו בכללות. אבל בפרטיות, כיון דזה שיש לאדם ערלת הלב הוא <i>שנברא</i> באופן זה, והכוונה בזה שנברא כן הוא בכדי שיהי' ומלתם את ערלת לבבכם – לכן זה שמל את ערלת לבבו אינו חידוש אמיתי, כי כן היא כוונת הבריאה מלכתחילה. משא\"כ כשחטא ופגם (היפך כוונת הבריאה) ואח\"כ מתקן זה ע\"י התשובה, הוא <i>חידוש</i>, כדלקמן בפנים."],["770","68","נצבים ל, יב."],["771","69","תקו\"ז תיקון כב (סה, ב. סו, א). תיקון ע (קלא, רע\"א)."],["772","70","שעהיוה\"א רפ\"ד. וראה זח\"ג רנז, סע\"ב (ברע\"מ). פרדס שער א (שער עשר ולא תשע) פ\"ט."],["773","71","להעיר מהמבואר בכ\"מ בענין ב' שמות הוי', דהוי' הראשון הוא שעלה ברצונו ית' להוות העולמות (סה\"מ תרנ\"ו ע' שסה ואילך. ובכ\"מ)."],["774","72","ראה זח\"ג לב, א."],["775","73","בהבא לקמן ראה בפרטיות יותר שיחת שמחת בית השואבה תשכ\"ג – נדפס בלקו\"ש ח\"ד ע' 1154."],["776","74","ח\"א רח, ב. הובא באוה\"ת יוהכ\"פ ע' א'תקנט. ריש וסוף ד\"ה ביום השמיני עצרת: באוה\"ת שמע\"צ (כרך ה ע' ב'קמט. שם ע' ב'קנג); תרפ\"ז (סה\"מ תרפ\"ז ע' לו. שם ע' נא); ה'תש\"מ (לקמן ע' רטו ואילך)."],["777","75","ויגש מה, א."],["778","76","פינחס כט, לה."],["779","77","ויצא ל, כד."],["780","78","אוה\"ת ויצא כרך ו תתשכג, א."],["781","79","משלי ה, יז. שמו\"ר פט\"ו, כג. הובא בריש וסוף ד\"ה ביוהשמע\"צ: עת\"ר (סה\"מ עת\"ר ע' לה. שם ע' מד); ה'תש\"ד (סה\"מ ה'תש\"ד ע' 43. שם ע' 47); ה'תש\"ט (סה\"מ ה'תש\"ט ע' 69. שם ע' 73); ה'שי\"ת (סה\"מ ה'שי\"ת ע' 71. שם ע' 82); ה'תש\"מ (לקמן ע' רטו. ע' רכה). ועוד."]]],[1500360012,"(הנחה)\n<b>שובה</b> ישראל עד הוי' אלקיך כי כשלת בעונך, קחו עמכם דברים גו' אמרו אליו כל תשא עון גו' ונשלמה פרים שפתינו<sup data-n=\"782\">1</sup>. וידוע הדיוק בדרושי רבותינו נשיאינו מ\"ש שובה ישראל, דלכאורה, מכיון שמדבר בענין התשובה הול\"ל שובה יעקב ולא שובה ישראל שהוא שם המעלה. דישראל הוא לשון כי שרית עם אלקים ועם אנשים ותוכל<sup data-n=\"783\">2</sup> וגם הטעם על קריאת שם ישראל הוא כי שרית, משא\"כ יעקב הוא מלשון עקב וגם הטעם על קריאת שם יעקב הוא לפי שוידו גו' בעקב<sup data-n=\"784\">3</sup>, ולא רק בעקב סתם אלא בעקב עשו, וא\"כ הול\"ל שובה יעקב ולמה אומר שובה ישראל. ובפרט ע\"פ האמור ולא ראה גו' בישראל<sup data-n=\"785\">4</sup> (משא\"כ ביעקב). וביותר א\"מ מה שממשיך בכתוב כי כשלת בעונך, דעון הו\"ע הזדונות, והרי אפילו בנוגע לשגגות איתא באגה\"ק<sup data-n=\"786\">5</sup> מלקו\"ת מהאריז\"ל<sup data-n=\"787\">6</sup> ששגגות הוא מצד התגברות נה\"ב [שזהו הטעם על מ\"ש רש\"י במסכת שבועות<sup data-n=\"788\">7</sup> שגם שוגג צריך כפרה], וא\"כ הרי אפילו ענין השגגות אינו שייך בבחינת ישראל, ומכש\"כ הענין דכשלת בעונך, זדונות, ולמה אומר שובה ישראל ולא שובה יעקב. וגם צריך להבין מ\"ש קחו עמכם דברים גו', דלכאורה כשאומר שובה ישראל הרי הכוונה היא לתשובה כדבעי, ומכיון שמ\"ע להתוודות (כשעושה תשובה)<sup data-n=\"789\">8</sup> הרי דשובה ישראל כולל גם ענין הוידוי, דהגם שעיקר התשובה הוא בלב<sup data-n=\"790\">9</sup> מ\"מ גם הוידוי הוא מעיקרי התשובה, א\"כ מה מוסיף קחו עמכם דברים. וגם צריך להבין מ\"ש אמרו אליו כל תשא עון, דלכאורה מאחר שעשה כבר תשובה (שובה ישראל) הרי ודאי שמחלו לו על עוונותיו, ולמה צריך לומר ולבקש כל תשא עון. וגם צריך להבין מ\"ש לאח\"ז ונשלמה פרים שפתינו שמונה כאן דרגות נעלות (בתחילה שובה ישראל גו', ואח\"כ קחו עמכם דברים גו', ואח\"כ אמרו אליו גו', עד שבא לונשלמה פרים שפתינו), שלאחרי כל הענינים שלפנ\"ז בא רק לונשלמה פרים שפתינו שהוא רק במקום הקרבנות ולא קרבנות גופא.<b>והענין</b> הוא, הנה כללות ענין התשובה הוא ענין דילוג<sup data-n=\"791\">10</sup> כמו שנת\"ל (בהשיחות), למעלה מסדר והדרגה והשתלשלות. דזהו מה שהתשובה היא בשעתא חדא וברגעא חדא<sup data-n=\"792\">11</sup>, דענינים שבהדרגה צריך לזה זמן, וכל שהענינים הם נעלים יותר צריך יותר זמן, וכמו לא קאי אינש אדעתא דרבי' עד ארבעין שנין<sup data-n=\"793\">12</sup>, שמצד גודל עילוי הענין (של דעתא דרבי') צריך לזה זמן מופלג. אמנם ענין התשובה (עם היותו ענין נעלה) הוא בשעתא חדא וברגעא חדא, לפי שעבודת התשובה היא בחילא יתיר<sup data-n=\"794\">13</sup>, באופן של דילוג שלא בהדרגה. והדילוג שבענין התשובה הוא מה שמדלג מענין הפכי, והיינו דלא רק שהיא באופן דאין ערוך כהעליות דאין ערוך שבקדושה גופא, כי אם, שמדלג מענין הפכי. דזהו גם בתשובה סתם, שבתחילה הי' בצד ההיפך וברגעא חדא נעשה לבעל תשובה. ובפרט בתשובה מאה\"ר שזדונות נעשים לו כזכיות<sup data-n=\"795\">14</sup>, שהיא דילוג מקצה היותר תחתון לקצה היותר עליון, שהרי בתחילה היו לו לא רק עבירות סתם כ\"א זדונות, קצה הכי תחתון, וע\"י התשובה נעשים כזכיות, שזכיות אלו (הנעשים מזדונות) הם נעלים יותר גם מזכיות הצדיקים, קצה הכי עליון.\n<b>והנה</b> ידוע פירוש אדמו\"ר הזקן<sup data-n=\"796\">15</sup> במרז\"ל<sup data-n=\"797\">16</sup> תכלית חכמה תשובה ומעשים טובים, שהטעם מה שמקדים תשובה למעשים טובים הוא לפי שע\"י קדימת התשובה המעשים הם מעשים טובים ומאירים. כי עבודת התשובה פועלת גם בהעבודה דתומ\"צ. ולכן, מכיון שעבודת התשובה היא בדרך דילוג שלא בהדרגה, הנה זה פועל שעד\"ז יהי' גם בהעבודה דתומ\"צ ועד בהעבודה דוכל מעשיך יהיו לשם שמים<sup data-n=\"798\">17</sup>, שגם עבודה זו יהי' באופן שלמעלה מסדר והדרגה, דוגמת ענין הדילוג שבתשובה. וכמבואר בארוכה בהמשך תרס\"ו בהמאמר שלפני ד\"ה שובה ישראל<sup data-n=\"799\">18</sup> ונתבאר גם במאמר הקודם (ד\"ה זה היום<sup data-n=\"800\">19</sup>) שלימוד התורה צ\"ל ע\"י קדימת הביטול, כמ\"ש ונפשי כעפר לכל תהי' (ועי\"ז דוקא) פתח לבי בתורתך<sup data-n=\"801\">20</sup>. ועד שגם בהדרגות דלימוד התורה גופא (כאשר הדרגות הם באין ערוך), צריך להיות תחילה ביטול השגת דרגא הקודמת, וכמו ר\"ז צם מאה תעניתא לשכוח תלמוד בבלי בכדי להשיג תלמוד ירושלמי<sup data-n=\"802\">21</sup>. ועד\"ז הוא גם בקיום המצוות, שצ\"ל בזה גם העבודה שלמעלה ממדידה והגבלה, וכמ\"ש<sup data-n=\"803\">22</sup> ואהבת את ה\"א בכל לבבךובכל נפשך ובכל מאדך, שאינו מספיק שקיום המצוות תהי' בהאהבה דבכל לבבך ובכל נפשך שהיא אהבה שבהגבלה כ\"א צריך שיהי' גם האהבה דבכל מאדך שהיא למעלה ממדידה והגבלה<sup data-n=\"804\">23</sup>. וענין זה הוא למעלה באין ערוך מקיום המצוות סתם, כי העבודה דבכל מאדך הו\"ע עושין רצונו של מקום<sup data-n=\"805\">24</sup> כידוע תורת הרב המגיד<sup data-n=\"806\">25</sup> (היינו שהוא עושה את הרצון), ומזה מובן שהוא למעלה באין ערוך מקיום המצוות (סתם), דקיום המצוות (סתם) הוא שכבר ישנו הרצון והאדם הוא רק מקיים את הרצון, משא\"כ בהאהבה דבכל מאדך הוא עושה רצונו של מקום. וענין זה (דבכל מאדך) צריך להיות לא רק בהענין דקיום המצוות אלא גם בהעבודה דוכל מעשיך יהיו לשם שמים, שהרי יש עוד פירוש בבכל מאדך, כמרז\"ל<sup data-n=\"807\">26</sup> בכל מאדך בכל ממונך, שהו\"ע בכל מעשיך, וגם פירוש זה בבכל מאדך שייך לפירוש הנ\"ל בבכל מאדך, היינו שגם בכל ממונך, כל מעשיך, צ\"ל ואהבת את ה\"א לא רק בכל לבבך ולא רק בכל נפשך אלא גם בכל מאדך, למעלה ממדידה והגבלה. אלא שענין הדילוג שלא בהדרגה שבתומ\"צ וכל מעשיך לש\"ש (הנפעל מענין הדילוג שבתשובה) הוא מה שבקדושה גופא העלי' היא באופן דאין ערוך, משא\"כ בתשובה הוא הדילוג מצד ההיפך. ועד שהדילוג הוא מקצה הכי תחתון לקצה הכי עליון, כנ\"ל.\n<b>והנה</b> הכח לעבודת התשובה שהיא בדרך דילוג לגמרי כנ\"ל הוא מצד בחינת ישראל. והגם שישראל הוא אותיות (לי) ראש<sup data-n=\"808\">27</sup>, וענין הראש הוא שיש לו שייכות להגוף והרגל<sup data-n=\"809\">28</sup>, מ\"מ הרי ישראל הוא אותיות לי ראש (דראש הוא <i>לי</i> – בטל <i>אליו</i> (וכפשטות הלשון והענין דשרית – שררה ונצחון דמלחמה)), ומצד בחינה זו יכול להיות ענין הדילוג שלמעלה ממדידה. וזהו שובה ישראל, כי הכח לשובה הוא מצד בחינת ישראל דוקא. ומכיון שבחינה זו ישנה בכאו\"א מישראל, גם בזה שכשלת בעונך, כמרז\"ל<sup data-n=\"810\">29</sup> ישראל אע\"פ שחטא ישראל הוא, ועד שישנה אפילו גם בזה שהוא דוגמת מי שממנו לומדים ישראל אע\"פ שחטא ישראל הוא, לכן יש לכאו\"א הכח לתשובה. ומצד בחינה זו יכול להיות ענין התשובה גם בבחינת יעקב, כי שמו העיקרי והעצמי של כאו\"א מישראל הוא ישראל, היינו שבחינה זו היא העיקר והעצם שבו, לכן היא פועלת גם על בחינת יעקב. וזהו גם מה שממשיך כי כשלת בעונך, דהנה ידוע מאמר רבותינו נשיאינו<sup data-n=\"811\">30</sup>, שכשם שצריך לידע חסרונות עצמו כן צריך לדעת מעלות עצמו, ולכן אומר כי כשלת גו' שהוא רק ענין שלכשלון בלבד, שע\"י שרגלו נתקל בעץ או באבן זה פועל הכשלון בהראש, ובחינת ישראל היא בשלימות. ובכ\"ז צ\"ל ענין התשובה בכל תוקפה כי מכיון שהוא בחינת ישראל, הרי לגבי מדריגתו צריך לתשובה גם על ענין זה. ואדרבה, מצד מדריגתו הנעלית, הנה גם ענין קל נוגע יותר מפגם גדול בבחינת יעקב, וע\"ד שאמרו בתניא<sup data-n=\"812\">31</sup> ובשבת<sup data-n=\"813\">32</sup> בנוגע לרבב על בגד ת\"ח הנק' בנאים, וע\"ד המבואר בתניא<sup data-n=\"814\">33</sup> בנוגע להרהור שבמחשבה שזה נוגע הרבה יותר מענין הדיבור כו'.\n<b>וממשיך</b> בכתוב קחו עמכם דברים גו', כי בכדי לתקן כדבעי את המכשול (מה שנתקל ברגלו) אינו מספיק ענין התשובה דביטול המציאות שנעשה עי\"ז – שזה פועל ע\"י וידוי דברים, ענין האותיות כמבואר בסהמ\"צ להצ\"צ<sup data-n=\"815\">34</sup>, כי תכלית התשובה הוא העבודה דתומ\"צ (וכנ\"ל בענין תשובה ומעשים טובים), ולזה מוסיף קחו עמכם דברים דתומ\"צ כמבואר בלקו\"ת עה\"פ<sup data-n=\"816\">35</sup>. ודברים אלו הם במדידה דוקא. דלא מיבעי בתושבע\"פ דמכיון שלימוד תושבע\"פ צ\"ל בהבנה והשגה דוקא<sup data-n=\"817\">36</sup> הרי מוכרח שיהי' במדידה, אלא גם תושב\"כ הגם שבתושב\"כ אינו נוגע כ\"כ ענין ההשגה<sup data-n=\"817\">36</sup>, מ\"מ גם בתושב\"כ צריך להיות מדידה, ואדרבה, המדידה דתושב\"כ היא יותר מהמדידה דתושבע\"פ, שהרי בתושב\"כ האותיות והתגין והטעמים צ\"ל בתכלית הדיוק.\n<b>וממשיך</b> בכתוב אמרו אליו כל תשא עון. והענין הוא, כי תכלית ענין התשובה הוא לא רק שימחלו העונות אלא שהזדונות גופא יהפכו לזכיות, וזהו מה שגם לאחרי שובה ישראל צ\"ל אמרו אליו כל תשא עון, תשא עון הו\"ע נושא עון<sup data-n=\"818\">37</sup>, דלא רק שהוא יכבוש עונותינו ותשליך במצולות ים כל חטאתם<sup data-n=\"819\">38</sup>, אלא שהוא גם נושא עון, שנושא ומגבי' את העון, שהעונות נעשים לזכיות כמבואר בארוכה באוה\"ת<sup data-n=\"820\">39</sup>. וענין זה (תשא עון) נעשה ע\"י אמרו אליו כל, כל הוא מה שהוא ית' הוא כל וכולל את הכל, ולכן תשא עון, שנושא גם את העון ומהפכו לזכיות.\n<b>וממשיך</b> בכתוב ונשלמה פרים שפתינו, היינו שע\"י שלימות התשובה דשובה ישראל וגו' פועלים שלימות בענין הקרבנות שלאחרי כשלת בעונך, דפירוש ונשלמה פרים שפתינו הוא לא רק ששפתינו הוא תשלומין לפרים כ\"א ששפתינו פועל שלימות בה\"פרים\", דשפתינו הו\"ע התפלה, ענין הקרבנות ברוחניות,שהוא למעלה מענין הקרבנת בגשמיות<sup data-n=\"821\">40</sup>, וע\"ד שגם בזמן הבית שהי' אז הקרבת הקרבנות כפשוטה הנה גם אז הוצרך להיות הענין דישראל במעמדם לויים בדוכנם וכהנים בעבודתם ובפרט עבודת הכהנים ה\"ה \"בחשאי וברעותא דלבא\"<sup data-n=\"822\">41</sup>. וזהו מ\"ש ונשלמה פרים שפתינו לאחרי שובה ישראל וגו', כי ענין זה (ונשלמה פרים שפתינו) הוא העילוי שנעשה ע\"י התשובה, מה שמגיע בעילוי אחר עילוי, למעלה גם מענין הקרבנות, עד שמגיע לבחינת פני הוי'. וכמ\"ש<sup data-n=\"823\">42</sup> בקשו פני את פניך הוי' אבקש, שע\"י בקשו פני הו\"ע התשובה, עי\"ז את פניך הוי' אבקש. דבאופן דהמשכה מלמעלה למטה כתיב<sup data-n=\"824\">43</sup> וראית את אחורי ופני לא יראו, משא\"כ באופן דהעלאה, מגיעים לבחינת פניך הוי'<sup data-n=\"825\">44</sup>.\n<b>והנה</b> כמו שהוא בנוגע לעבודה, דהגם שהעבודה דתומ\"צ (מצד עצמם) היא בהגבלה יש בה גם הענין דשלא בהדרגה (שנפעל ע\"י עבודת התשובה), ויש גם ענין הדילוג דתשובה שהוא למעלה גם מהענין דשלא בהדרגה שבהעבודה דתומ\"צ, עד\"ז הוא גם בהשכר, שנוסף לג' הבחינות (בי\"ע) בג\"ע שהם בחינות השתלשלות, השכר דילכו מחיל אל חיל<sup data-n=\"826\">45</sup> שהוא עליות שבאין ערוך. אבל גם עליות אלו הם רק הארה וגילוי, ואח\"כ יהי' המשכת העצם שהוא למעלה מענין העליות והירידות, ועד שאין שייך לומר על זה שהוא למעלה מענין העליות כי אינו בגדר דעלי' וירידה<sup data-n=\"827\">46</sup> כ\"א יום שכולו שבת<sup data-n=\"828\">47</sup>.\n<b>וזהו</b> שובה ישראל גו' שאומרים בההפטורה דשבת תשובה, שהעבודה דשבת תשובה מתקנת את כל השבתות דשנה העברה וגם פועלת בכל השבתות שבשנה הבאה. וכמבואר בכתבי האריז\"ל<sup data-n=\"829\">48</sup> שיום הראשון (לשבוע) שבז' הימים שבין ראש השנה ליום הכיפורים מתקן את כל הימים דיום ראשון שבשנה העברה, ועד\"ז בנוגע ליום שני וכו' עד ליום השבת. וכמו שהוא בנוגע לתיקון שנה העברה, עד\"ז הוא גם בנוגע לשנה הבאה<sup data-n=\"830\">49</sup>, דמצות התשובה מה\"ת הוא לבל ישוב עוד לכסלה כו' ולא יעבור עוד כו'<sup data-n=\"831\">50</sup>, היינו קבלה טובה על להבא, עד אשר [בלשון הרמב\"ם<sup data-n=\"832\">51</sup>] יעיד עליו יודע תעלומות שלא ישוב לזה החטא לעולם (חסר קצת). וכמו שבענין היראה ידוע שהגם שיש בזה ריבוי דרגות, יראת העונש, יראת אלקים, יראת הרוממות כו' עד לבחינת היראה כמו שהיא בבחינת קוצו של יו\"ד,מ\"מ כל הבחינות שביראה שייכים וקשורים זל\"ז<sup data-n=\"833\">52</sup>, עד\"ז הוא גם בתשובה, שגם תשובה באופן הכי תחתון הוא שייך וקשור עם בחינה הכי עליונה שבתשו\"ע, עד לבחינת התשובה דוהרוח תשוב אל האלקים אשר נתנה<sup data-n=\"834\">53</sup> שמבואר בלקו\"ת פרשה זו<sup data-n=\"835\">54</sup>. וזהו מה שבשבת תשובה אומרים שובה ישראל וגו' ונשלמה פרים שפתינו, שע\"י התשובה דשבת תשובה שפועלת בכל שבתות השנה באים עד לבחינת ונשלמה פרים שפתינו שהיא בחינה נעלית ביותר כנ\"ל, ובלשון הרמב\"ם<sup data-n=\"836\">55</sup> <i>ישראל</i> עושין תשובה <i>ומיד</i> הן נגאלין ויבנה ביהמ\"ק השלישי ושם \"נעשה<sup data-n=\"837\">56</sup> לפניך את קרבנות חובותינו כמצות <i>רצוניך</i>\"<sup data-n=\"838\">57</sup> בקרוב ממש.\n**********",[["782","1","הושע יד, ב-ג."],["783","2","וישלח לב, כט."],["784","3","תולדות כה, כו."],["785","4","בלק כג, כא."],["786","5","סו\"ס כח."],["787","6","פ' ויקרא."],["788","7","ב, א."],["789","8","רמב\"ם הל' תשובה פ\"א ה\"א."],["790","9","<a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא פכ\"ט (לו, ב</a>)."],["791","10","לקו\"ת ד\"ה שובה ישראל (הא') פ\"ד (סה, א)."],["792","11","זח\"א קכט, סע\"א."],["793","12","ע\"ז ה, ב."],["794","13","ראה זח\"א שם, ב."],["795","14","יומא פו, ב."],["796","15","לקו\"ת סד\"ה יונתי וסוף הבי'. וראה ג\"כ שערי אורה לח, ב."],["797","16","ברכות יז, א."],["798","17","אבות פ\"ב מי\"ב."],["799","18","ע' יג ואילך."],["800","19","סה\"מ תשל\"ו ע' 7 ואילך."],["801","20","ברכות יז, א: אלקי נצור כו'."],["802","21","ב\"מ פה, א."],["803","22","ואתחנן ו, ה."],["804","23","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370179\" data-slug=\"torah-or\" data-id=\"3901370179\">תו\"א מקץ לט, סע\"ג</a> ואילך. ובכ\"מ."],["805","24","ראה ברכות לה, ב ובחדא\"ג מהרש\"א שם."],["806","25","או\"ת עקב נג, ד."],["807","26","ברכות נד, א במשנה."],["808","27","שער הפסוקים להאריז\"ל וישלח לב, כט. ספר הליקוטים להאריז\"ל ויחי מז, כח. שם מח, ב. פע\"ח שער הלולב פ\"א. ערכי הכינויים (לבמח\"ס סדה\"ד) מערכת ראש. סהמ\"צ להצ\"צ טו, ב – בשם הזהר."],["809","28","ראה מאמר הקודם ד\"ה זה היום (סה\"מ תשל\"ו ע' 3)."],["810","29","סנהדרין מד, רע\"א."],["811","30","אגרות-קודש אדמו\"ר מוהריי\"צ ח\"ה ע' נא. נעתק ב\"היום יום\" כו חשון. סה\"ש תרפ\"ז ע' 114. וש\"נ."],["812","31","ספ\"ל."],["813","32","קיד, א."],["814","33","אגה\"ק סכ\"ב."],["815","34","מצות וידוי ותשובה."],["816","35","דרושי ש\"ש סה, א."],["817","36","ראה הל' ת\"ת לאדה\"ז ספ\"ב."],["818","37","תשא לד, ז. מיכה ז, יח."],["819","38","מיכה שם, יט."],["820","39","נ\"ך ח\"א ע' תצג."],["821","40","לקו\"ת סד\"ה שובה ישראל השני."],["822","41","זהר ח\"ג לט, א."],["823","42","תהלים כז, ח."],["824","43","תשא לג, כג."],["825","44","לקו\"ת שם."],["826","45","תהלים פד, ח. וראה ברכות ומו\"ק בסופן."],["827","46","המשך תרס\"ו ע' יב."],["828","47","ראה תמיד בסופה."],["829","48","סידור האריז\"ל עשי\"ת (ד\"ה מי שיחזור). ובכ\"מ."],["830","49","ראה גם התוועדויות תשמ\"ז ח\"א ע' 120. וש\"נ."],["831","50","אגה\"ת פ\"א."],["832","51","הל' תשובה פ\"ב ה\"ב."],["833","52","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370512\" data-slug=\"torah-or\" data-id=\"3901370512\">תו\"א קיד, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380840\" data-slug=\"likkutei-torah\" data-id=\"4001380840\">לקו\"ת פ' ראה לא, א</a>. ביאורי הזהר פ' אמור לאדמו\"ר האמצעי (פא, א-ב), ולאדמו\"ר הצ\"צ ח\"א ע' תכג. קונטרס העבודה פ\"ג (ע' 18)."],["834","53","קהלת יב, ז."],["835","54","האזינו עא, ג."],["836","55","שם פ\"ז ה\"ה."],["837","56","נוסח תפלת המוספין."],["838","57","המשך וככה תרל\"ז פי\"ז ואילך."]]],[1500360013,"<h3>בס\"ד. יום ה', וא\"ו תשרי ה'תשל\"ז<sup data-n=\"839\">*</sup></h3>\n<b>שובה</b> ישראל עד הוי' אלקיך<sup data-n=\"840\">1</sup>, וידוע הדיוק בזה שאומר עד הוי' אלקיך, דלכאורה הול\"ל להוי' אלקיך<sup data-n=\"841\">2</sup>. וגם מה שמזכיר כאן ב' השמות הוי' ואלקים<sup data-n=\"842\">3</sup>. גם צלה\"ב מה שממשיך בכתוב כי כשלת בעוניך, הרי זה שתשובה (שובה) היא על חטא ועון מובן מעצמו, ומה מחדש הכתוב בכי כשלת בעוניך<sup data-n=\"843\">4</sup>.\nב) <b>והענין</b> הוא, דבעבודת האדם שני ענינים בכללות. סור מרע ועשה טוב<sup data-n=\"844\">5</sup>. וידוע<sup data-n=\"845\">6</sup> שהעבודה דסור מרע שייכת (בעיקר) לשם אלקים, והעבודה דעשה טוב לשם הוי'. והענין הוא, כדאיתא בשו\"ע<sup data-n=\"846\">7</sup> שכשמזכירים שם הוי' צריך לכוין שהוא הי' הוה ויהי', וכשמזכירים שם אלקים צריך לכוין שהוא תקיף ואמיץ אשר לו היכולת בעליונים ובתחתונים. ומהחילוק שבין שני ענינים אלה הוא, דזה שלו היכולת בעליונים ובתחתונים הוא בהאלקות שבערך העולמות, דבכללות הוא ממלא כל עלמין, וזה שהוא הי' הוה ויהי' כאחד<sup data-n=\"847\">8</sup> הוא בהאלקות שלמעלה מעולמות, סובב כל עלמין. והענין הוא, דגדר העולם הוא מקום וזמן<sup data-n=\"848\">9</sup>, דכמו כן הוא גם בעולמות הרוחניים שהם מוגדרים בגדר דמקום וזמן, אלא שהמקום והזמן שבהם הוא מקום וזמן רוחני<sup data-n=\"849\">10</sup>. וכיון שאור הממלא הוא אור שבערך העולמות, מובן, שגם באור הממלא יש דוגמת מקום וזמן, [וכידוע<sup data-n=\"850\">11</sup> שבאור הקו, שבכללות הוא אור הממלא, ישנם הענינים דמעלה ומטה (מקום) קדימה ואיחור (זמן)], שהוא השרש דמקום וזמן שבעולמות. וזה שהוי' הוא הי' הוה ויהי' כאחד למעלה מהתחלקות הזמן, הוא, כי הוי' הוא האור שלמעלה מעולמות. אלא שאעפ\"כ, מזה שאומרים שהוי' הוא הי' הוה ויהי' כאחד [דהי' הוה ויהי' הו\"ע הזמן, אלא שהוא למעלה מהתחלקות], מובן, שגם הוי'שייך לזמן<sup data-n=\"851\">12</sup> (עולמות), דזהו גם מה שהוי' הוא לשון מהוה<sup data-n=\"852\">13</sup>, דהתהוות כל העולמות היא משם הוי'. אלא שהעולמות כמו שמתהווים משם הוי' אינם מוגבלים כ\"כ, ולכן, העבר ההוה והעתיד הם כאחד. וזהו שהוי' ואלקים הוא סובב כל עלמין וממלא כל עלמין<sup data-n=\"853\">14</sup>, דההתהוות שמאור הממלא, מכיון שהוא בערך העולמות ומקור אליהם, היא בדרך התלבשות. ולכן העולמות שנתהוו ממנו הם מציאות<sup data-n=\"854\">15</sup>, כי ענין ההתלבשות הוא שהוא מתלבש להוות <i>את העולמות</i>, וההתהוות שמאור הסובב, מכיון שאין להעולמות ערך אליו, היא באופן דבדרך ממילא, בדוגמת פעולה הבאה מהרצון<sup data-n=\"855\">16</sup> (דרצון הוא משל על סובב), שהרצון הוא רק סיבה להפעולה ואינו מתלבש בה<sup data-n=\"856\">17</sup>. ולכן העולמות שנתהוו מאור הסובב אינם בבחי' מציאות<sup data-n=\"854\">15</sup>, כי כמו שהרצון עצמו אינו מציאות והוא רק גילוי העצם [וע\"ד הרצון שבנפש האדם שהוא רק הטיית והמשכת הנפש], עד\"ז הוא גם בנוגע לההתהוות שמהרצון<sup data-n=\"857\">18</sup>, שענינה הוא (לא זה שמתהווים עולמות, אלא) זה שע\"י ההתהוות נשלם הרצון. וזוהי השייכות דאור הסובב ואור הממלא להשמות הוי' ואלקים, דאור הממלא נקרא בשם אלקים מלשון כח<sup data-n=\"858\">19</sup>, כי הוא בדוגמת כח שענינו הוא לפעול<sup data-n=\"859\">20</sup>. אלא שמכיון שמציאות העולמות הוא עי\"ז שכח האלקי מהווה אותם בכל רגע ורגע מאין ליש<sup data-n=\"860\">21</sup>, לכן הכוונה בשם אלקים היא אשר לו היכולת בעליונים ותחתונים, שהממשלה והשליטה שלו (אלקים מלשון שררה<sup data-n=\"861\">22</sup>) על העליונים והתחתונים היא גם לאחר שנתהוו, והשליטה עליהם היא גם בנוגע לעצם מציאותם (אם להוות אותם אם לאו). ואור הסובב נקרא בשם הוי', הי' הוה ויהי' כאחד, דמכיון שההתהוות שמאור הסובב ענינה הוא זה שע\"י ההתהוות נשלם הרצון, הרי אין חילוק בזה בין עבר הוה ועתיד<sup data-n=\"862\">23</sup>, הי' הוה ויהי' כאחד.<b>וזהו</b> הקשר דשני העבודות דסור מרע ודועשה טוב לב' השמות אלקים והוי'. דהנה ידוע<sup data-n=\"863\">24</sup> שבסור מרע נכלל גם הזהירות שלא לעבור על מ\"ע (דביטול מ\"ע הוא איסור, רע), אלא שבסור מרע, מכיון שהזהירות שלו בקיום המצוות הוא מפני שירא<sup data-n=\"864\">25</sup> לעבור על ציווי המלך, קיום המצוות שלו הוא רק עד כמה שמחוייב. והחידוש בהעבודה דעשה טוב הוא, שקיום המצוות שלו הוא (לא רק מפני שהוא מוכרח בזה, בכדי שלא לעבור על הציווי, אלא) באופן דעשי', <i>ועשה</i> טוב. וכמ\"ש בלקו\"ת<sup data-n=\"865\">26</sup> דענין ועשה טוב הוא שמייגע את עצמו בתומ\"צ, ועד ליגיעה יותר מטבעו ורגילותו<sup data-n=\"866\">27</sup>. וזהו שהעבודה דסור מרע שייכת לשם אלקים והעבודה דועשה טוב לשם הוי', כי זה שהוא ירא לעבור על מצות המלך, ועד שמפני היראה שלו הוא כובש את יצרו (גם כשיצרו בוער כאש<sup data-n=\"867\">28</sup>) מפני שהוא ירא לעבור על מצות המלך, הוא ע\"י שמרגיש שהוא ית' מושל ושולט עליו, אלקים. והעבודה דועשה טוב, שמייגע עצמו בתומ\"צ יותר מטבעו ורגילותו, הוא ע\"י גילוי אור הסובב שלמעלה מעולמות, הוי' שלמעלה מטבע.\nג) <b>וביאור</b> השייכות של העבודה דועשה טוב לאור הסובב בפרטיות יותר, הנה נתבאר לעיל, שגם אור הסובב יש לו שייכות לעולמות, אלא שענינם של העולמות לגבי אור הסובב הוא (לא המציאות שלהם, רק) זה שעל ידם נשלם הרצון. ועד\"ז הוא בהעבודה דועשה טוב, דמכיון שהעבודה דועשה טוב הוא מפני שהוא אוהב את הוי' וחפץ לדבקה בו<sup data-n=\"868\">29</sup>, הרי עבודתו את ה' קשורה עם מציאותו של האדם, האהבה והרצון שלו. אלא שהאהבה שלו להוי' היא באופן שזה (אהבת ה') נעשה כל ענינו<sup data-n=\"869\">30</sup>, שלכן עבודתו את ה' היא באופן שאינו מתחשב עם הגבלת הטבע שלו. וזוהי המעלה בהעבודה דבקש שלום, שהוא עסק התורה, על העבודה דועשה טוב, כי התורה נקראת משל הקדמוני<sup data-n=\"870\">31</sup>, שהיא משל ולבוש לבחי' קדמונו של עולם, היינו לעצמות אוא\"ס שאינו בגדר עלמין כלל<sup data-n=\"871\">32</sup>, ולכן, הביטול דעסק התורה הואביטול בתכלית<sup data-n=\"872\">33</sup>. וכמבואר בתו\"א<sup data-n=\"873\">34</sup> החילוק בין תורה למצוות, שבקיום המצוות, האדם המקיים את המצוות הוא כמו עבד המקיים מצות המלך, דמציאות העבד אינה מציאות האדון. וגם כשקיום המצוות שלו היא מאהבה בתענוגים, אעפ\"כ יש מי שאוהב<sup data-n=\"874\">35</sup>. משא\"כ בלימוד התורה ה\"ה המלך עצמו. דכאשר עסק התורה הוא בביטול, אזי ואשים דברי בפיך<sup data-n=\"875\">36</sup>, דברי ממש. היינו (שלא האדם הוא המדבר, כי אם) שדבר הוי' זו הלכה<sup data-n=\"876\">37</sup> היא המדברת מתוך גרונו.\nד) <b>והנה</b> עד\"ז הוא בהעבודה דאהבת ה', שיש בה ג' מדריגות. בכל לבבך, בכל נפשך, ובכל מאדך. ומבואר בכ\"מ<sup data-n=\"877\">38</sup>, שהאהבה דבכל לבבך היא ע\"י ההתבוננות באור האלקי המתלבש בנבראים להחיותם, דבכללות הוא אור הממלא. דע\"י שמתבונן שהחיות של כל דבר הוא אלקות, וההתבוננות שלו היא באופן שזה יהי' מובן גם בהשכל דנפש הבהמית, עי\"ז יבוא לאהבה את הוי' בכל לבבך בשני יצריך<sup data-n=\"878\">39</sup>. והאהבה דבכל נפשך היא ע\"י ההתבוננות שהאור המחי' את העולמות הוא הארה בלבד ושהארה זו היא באין ערוך לגבי אוא\"ס, דבכללות הוא אור הסובב, עי\"ז יבוא להאהבה דבכל נפשך, שאהבתו את הוי' היא באופן דמסירת נפש, אפילו נוטל את נפשך<sup data-n=\"878\">39</sup>. והאהבה דבכל מאדך היא ע\"י גילוי עצמות אוא\"ס שאינו בגדר עלמין כלל, שע\"י גילוי זה, האהבה היא למעלה ממדידה והגבלה. והגם שגם האהבה דבכל נפשך היא אפילו נוטל את נפשך וענין המס\"נ הוא למעלה ממדידה והגבלה, הנה המס\"נ<sup data-n=\"879\">40</sup> שבהאהבה דבכל נפשך, שהוא בכללות בבחי' חי'<sup data-n=\"880\">41</sup>, היא באופן שהוא <i>רוצה</i> למסור את נפשו [ויתירה מזו שרצון זה הוא דוגמת<sup data-n=\"881\">42</sup> הרצון שע\"פ טעם, מצד זה שכל הענינים הם באין ערוך לגבי אוא\"ס]. והאהבה דבכל מאדך, שהיא בכללות בבחי' יחידה<sup data-n=\"880\">41</sup>, היא לא מצד הרצון שלו אלא מפני שאינו יכול להפרד ח\"ו מאחדותו ית'<sup data-n=\"882\">43</sup>. דמס\"נ באופן זה הוא אמיתית ענין הביטול, מכיון שהמס\"נ היא לא מצד הרצון (מציאות) שלו אלא מצד האלקות. וע\"ד שנת\"ל (סעיף ג) מעלת העבודה דבקש שלום על העבודה דועשה טוב.\n<b>ויש</b> לומר, דזהו הטעם שבפרשה שני' דק\"ש נאמר רק בכל לבבכם ובכל נפשכם<sup data-n=\"883\">44</sup>, כי האהבה דבכל מאדך, להיותה באה ע\"י הגילוי דאוא\"ס שאינו בגדר עלמיןכלל, אינה לכאו\"א<sup data-n=\"884\">45</sup>. וזה שדורשים מכאו\"א היא האהבה שמצד אור הממלא ואור הסובב. ועד\"ז הוא בנוגע לג' הענינים דסור מרע ועשה טוב ובקש שלום, שבכו\"כ מקומות נזכרו רק שני הענינים דסור מרע ועשה טוב.\nה) <b>והנה</b> ידוע<sup data-n=\"885\">46</sup> דזה שע\"י התשובה נעשה סליחת עוונות, דאמיתית ענין הסליחה הוא שהאדם יהי' מרוצה לפניו ית' כמו קודם החטא, הוא, כי ע\"י התשובה ממשיכים רצון חדש מאוא\"ס בעל הרצון, שלמעלה מהרצון דתומ\"צ. והמשכה זו היא ע\"י שעשיית התשובה שלו היא באופן דבכל מאדך, למעלה ממדידה והגבלה. כידוע<sup data-n=\"886\">47</sup> שע\"י האהבה דבכל מאדך עושין רצונו של מקום, ופירוש עושין רצונו של מקום הוא שעושים את הרצון. כי ע\"י האהבה דבכל מאדך, מגיעים באוא\"ס שלמעלה מרצון, ועי\"ז, ממשיכים משם רצון חדש<sup data-n=\"887\">48</sup>. וע\"פ הידוע<sup data-n=\"888\">49</sup> שעבודת האדם שעל ידה נעשית ההמשכה צריכה להיות מעין ההמשכה, יש לומר, דשני הענינים בעושין רצונו של מקום, שההמשכה היא מאוא\"ס שלמעלה מבחי' רצון ושגם הרצון שנמשך משם הוא למעלה יותר מהרצון כמו שהוא מצד עצמו, נעשים ע\"י דוגמת שני ענינים אלה בהאהבה דבכל מאדך. דע\"י שהאהבה דבכל מאדך היא למעלה מרצון (וכנ\"ל סעיף ד שהמס\"נ דבכל מאדך היא לא שהוא רוצה למסור נפשו אלא שאינו יכול להפרד ח\"ו מאחדותו ית'), לכן היא מגעת בבעל הרצון<sup data-n=\"889\">50</sup>. וזה שע\"י האהבה דבכל מאדך נעשה עילוי גם בהאהבה דבכל לבבך ובכל נפשך, עי\"ז, גם הרצון שנמשך מבעל הרצון הוא נעלה יותר.\nו) <b>וזהו</b> שובה ישראל עד הוי' אלקיך, דזה שנאמרו כאן ב' השמות הוי' ואלקים הוא, כי ענינו ועבודתו של כל אחד מישראל הוא בב' שמות אלה. וכיון שענין התשובה הוא שישוב ויחזור למקומו, לכן נאמר כאן ב' השמות דהוי' ואלקים. וזה שאומר עד הוי' אלקיך (ולא להוי' אלקיך) הוא, כפירוש אדמו\"ר הזקן<sup data-n=\"890\">51</sup>, ששיעור התשובה<sup data-n=\"891\">52</sup> הוא עד שהוי' יהי' אלקיך. והיינו, שהתשובה צריכה להיות באופן דבכל מאדך, למעלה ממדידה והגבלה, שעי\"ז היא ההמשכה מאוא\"ס שלמעלה מהוי', דענין זה (שההמשכה היא מאוא\"ס שלמעלה מהוי') מתגלה בזה שהוי' הוא אלקיך כחך וחיותך. כי בכדי שיהי' החיבור דסובב (הוי') וממלא (אלקים) הוא ע\"ישההמשכה היא מאוא\"ס שלמעלה מהוי'<sup data-n=\"892\">53</sup>. וזהו שממשיך בכתוב כי כשלת בעוניך, שהוא טעם על זה שהתשובה צריכה להיות באופן זה, דמכיון שכשלת בעוניך, לכן אין מספיק העבודה דבכל לבבך ובכל נפשך שמצד השמות אלקים והוי', וצריכה להיות העבודה דבכל מאדך, בכדי שתהי' ההמשכה מאוא\"ס שלמעלה מהוי'.\nז) <b>ועוד</b> פירוש בשובה ישראל עד הוי' אלקיך, שהתשובה צריכה להיות עד שהוי' יהי' רק בחי' אלקים וצמצום לגבי אוא\"ס שלמעלה מהוי'&lt;51&gt;. והחילוק בין שני הפירושים הוא, דלהפירוש בעד הוי' אלקיך שהוי' יהי' אלקיך כחך וחיותך, מה שנמשך בגילוי הוא השמות הוי' ואלקים אלא שהחיבור דב' השמות הוא ע\"י המשכה מאוא\"ס שלמעלה מהוי' ואלקים. ולהפירוש בעד הוי' אלקיך שהוי' יהי' רק בחי' אלקים וצמצום לגבי אוא\"ס שלמעלה מהוי', האור עצמו (שלמעלה מהוי') נמשך בגילוי. דזה שהוי' נעשה בחי' אלקים וצמצום לגבי אוא\"ס שלמעלה מהוי' הוא דוקא כשאור זה מאיר בגילוי.\n<b>ויש</b> לומר, דהחילוק בין שני הפירושים הוא ע\"ד החילוק שבין תקיעת שופר לאמירת פסוקי שופרות. דהנה מבואר בהמשך תרס\"ו<sup data-n=\"893\">54</sup>, שמלכיות וזכרונות הם באור הממלא ואור הסובב, וההמשכה שע\"י שופר היא מאוא\"ס שלמעלה מממלא וסובב, ועד לההמשכה מהעלם העצמי, שע\"י המשכה זו נעשה היחוד דסובב וממלא. וההמשכה<sup data-n=\"894\">55</sup> שע\"י אמירת פסוקי שופרות היא למעלה יותר גם מההמשכה שע\"י תקיעת שופר. דההמשכה שע\"י תקיעת שופר היא רק אור הסובב ואור הממלא, אלא שע\"י שההמשכה היא מאוא\"ס [ולמעלה יותר מהעלם העצמי], הם מתחברים ומתאחדים. וע\"י אמירת פסוקי שופרות נמשך העלם העצמי עצמו, בדוגמת הגילוי שיהי' לעתיד. וזהו<sup data-n=\"895\">56</sup> מה שבפסוקי שופרות אומרים פסוקי שופרות דמ\"ת ומסיימים בענין השופר דלעתיד, כי לע\"ל יהי' הגילוי דהעלם העצמי. ועד\"ז הי' הגילוי דמ\"ת.\nח) <b>והנה</b> השופר דלעתיד הוא נעלה יותר מהשופר דמ\"ת, כדאיתא בפרקי דר\"א<sup data-n=\"896\">57</sup> בענין ב' קרניו של אילו של יצחק, דקרן הימין גדול מהשמאל, בשל שמאל תקע בו הקב\"ה על הר סיני ובשל ימין עתיד לתקוע בו לעתיד לבוא. וגם בשופר דלעתיד עצמו ישנם כמה דרגות, ואד' הוי' בשופר יתקע, ויתקע בשופר גדול<sup data-n=\"897\">58</sup>. דאד' הוי' הם שמות, אלא ששמות אלה (אד' הוי' בניקוד אלקים) הם נעלים ביותר, כמבואר בארוכה בלקו\"ת<sup data-n=\"898\">59</sup>. דגילוי זה יהי' בהתחלת הגאולה. ולאח\"ז יתקעבשופר גדול, יתקע סתם ולא נאמר מי הוא התוקע, כי תקיעה זו היא המשכה וגילוי מבחינת סתימא דכל סתימין<sup data-n=\"899\">60</sup>. ויש לומר, דזה שבפסוקי שופרות דראש השנה אומרים גם הפסוק יתקע בשופר גדול, הוא, כי ע\"י העבודה דר\"ה ממשיכים גם ענין זה. ועפ\"ז יש לומר, דזה שאומרים בההפטורה דשבת תשובה שובה ישראל עד הוי' אלקיך, שבהוי' זה נכלל גם הענין דהוי' אד' בניקוד אלקים שהוא דרגא נעלית ביותר, ואעפ\"כ אומרים שהתשובה צריכה להיות עד שהוי' יהי' רק בחינת אלקים וצמצום לגבי אוא\"ס שלמעלה מהוי', כי ע\"י העבודה דר\"ה ממשיכים גם ענין יתקע בשופר גדול, ולגבי דרגא זו, גם השם הוי' אד' כאלקים יחשב.\nט) <b>והנה</b> ידוע מ\"ש באגרת התשובה<sup data-n=\"900\">61</sup> שתשובה עילאה היא בשמחה רבה. ומזה מובן במכ\"ש בנוגע להתשובה דשבת תשובה, שבתשובה עילאה עצמה היא דרגא נעלית ביותר, ועד שגם הוי' אד' כאלקים יחשב, שצריכה להיות בשמחה רבה ועצומה. וכיון ששמחה פורצת גדר<sup data-n=\"901\">62</sup>, הנה ע\"י השמחה בעשרת ימי תשובה, ובפרט בשבת תשובה, פורצים כל המדידות וההגבלות, ענני במרחב י\"ה<sup data-n=\"902\">63</sup>, וזה נמשך על ובכל השנה, בענינים הרוחניים, שהעבודה בתומ\"צ תהי' בהרחבה ובאופן דופרצת<sup data-n=\"903\">64</sup>, וגם בענינים הגשמיים בבני חיי ומזוני רויחי, ועד להרחבה האמיתית שתהי' בביאת משיח צדקנו, ורחבה גו' למעלה עתידה ירושלים להיות מורחבת כו'<sup data-n=\"904\">65</sup>, עתידה ירושלים שתתפשט בכל ארץ ישראל ועתידה ארץ ישראל שתתפשט בכל הארצות<sup data-n=\"905\">66</sup>, בביאת משיח צדקנו בקרוב ממש.\n**********",[["839","*","יצא לאור ב<b>קונטרס וא\"ו תשרי – תש\"נ</b>, \"לקראת ו' תשרי, יום היאָרצייט של הרבנית הצדקנית מרת חנה תנצב\"ה (אמו של – יבלח\"ט – כ\"ק אדמו\"ר שליט\"א), נסתלקה שבת תשובה בעת עלות המנחה שנת תשכ\"ה, אשר השנה מלאו עשרים וחמש שנים מיום ההסתלקות שלה . . <i>יום ה'</i>,<i> וא\"ו תשרי ה'תש\"נ</i>\"."],["840","1","הושע יד, ב. – התחלת וראשית ההפטורה דשבת שובה. וראה לקמן (ע' צו ואילך) מאמר ד\"ה שובה ישראל מש\"פ האזינו – שהוא המשך למאמר זה."],["841","2","לקו\"ת דרושים לשבת שובה ד\"ה שובה הב' (סו, ריש ע\"ב). רד\"ה זה תרס\"ו (המשך תרס\"ו ע' יז). ובכ\"מ."],["842","3","רד\"ה זה תרנ\"ט (סה\"מ תרנ\"ט ע' יח), תרצ\"ה (סה\"מ קונטרסים ח\"ב שכח, א), תרח\"צ (סה\"מ תרח\"צ ע' לד). ועוד."],["843","4","מקומות שבהערה הקודמת. ד\"ה זה ה'תש\"ד (סה\"מ ה'תש\"ד ע' 15). ועוד."],["844","5","תהלים לד, טו."],["845","6","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380611\" data-slug=\"likkutei-torah\" data-id=\"4001380611\">לקו\"ת בלק</a> ד\"ה מה טובו (עג, ב. שם, ד)."],["846","7","אדה\"ז או\"ח ס\"ה ס\"ב-ג."],["847","8","שעהיוה\"א פ\"ז (פב, א), מרע\"מ פ' פינחס (רנז, סע\"ב). פרדס שער א (שער עשר ולא תשע) פ\"ט. ואפשר שכ\"ה הכוונה גם בשו\"ע שם."],["848","9","שעהיוה\"א שם."],["849","10","ראה בארוכה סה\"מ תרנ\"ד ע' רצא. המשך תער\"ב ח\"ב ע' תתקכ ואילך."],["850","11","ראה המשך תער\"ב שם. סה\"מ ה'תש\"ח ס\"ע 160 ואילך."],["851","12","להעיר מעטרת ראש שער ר\"ה פ\"ד: \"הי' הוה ויהי' כא' שהוא למעלה מבחי' התחלקות הזמן דעבר הוה עתיד\", \"מ\"מ הרי הוא שרש התחלקות הזמן . . ונק' מקור הזמן עכ\"פ\"."],["852","13","שעהיוה\"א רפ\"ד. וראה גם זהר ופרדס שבהערה 8."],["853","14","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380613\" data-slug=\"likkutei-torah\" data-id=\"4001380613\">לקו\"ת בלק שם (עג, ד</a> ואילך). ובכ\"מ. וראה גם ד\"ה לך אמר לבי ה'תש\"כ ס\"ו (לקמן ח\"ד ע' רפו). וש\"נ."],["854","15","ראה ד\"ה הנ\"ל שם, דהנבראים שמתהווים משם אלקים (ממלא), מכיון שהתהוותם היא בדרך התלבשות, הביטול שלהם הוא רק ביטול היש, והנבראים שמתהווים משם הוי' (סובב), מכיון שהתהוותם היא באופן דבדרך ממילא, הביטול שלהם הוא ביטול במציאות."],["855","16","ראה המשך תרס\"ו ע' קצח. ולהעיר גם מסה\"מ קונטרסים ח\"א צט, סע\"ב ואילך \"ההתהוות דשם הוי' היא בדרך ממילא . . כשעלה ברצונו ית' שיהיו עולמות נתהווה מציאות העולמות . . שבזה ההתהוות היא בדרך ממילא\"."],["856","17","המשך תרס\"ו שם."],["857","18","ראה עד\"ז המשך תער\"ב ח\"א פמ\"ט. סה\"מ תרע\"ח ע' שה. ד\"ה בלילה ההוא תש\"כ (סה\"מ תש\"כ ע' 93)."],["858","19","בכ\"מ בדא\"ח, דאלקים הוא לשון כח כמ\"ש (יחזקאל יז, יג) ואת אילי הארץ לקח (מקומות שבהערה הבאה). ובסה\"מ תרפ\"ח ע' סט, מובא גם (בהמשך לפסוק זה) מ\"ש בשו\"ע רבינו ז\"ל (שבהערה 7) וכשמזכיר שם אלקים יכוין שהוא תקיף ואמיץ."],["859","20","ראה סה\"מ עטר\"ת ע' שס. תרפ\"ח שם. קונטרסים ח\"א צז, א. ועוד."],["860","21","שעהיוה\"א פ\"א."],["861","22","פרש\"י סנהדרין ב, סע\"ב. הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316300239\" data-slug=\"or-hatorah-hb\" data-id=\"8316300239\">אוה\"ת יתרו ע' תשנ</a>."],["862","23","וע\"ד חילוקי המדריגות מעלה ומטה שבעולמות, שהם מצד אור הממלא, משא\"כ אור הסובב הוא סובב כל עלמין בשוה (לקו\"ת ר\"פ אמור. ובכ\"מ)."],["863","24","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071195\" data-slug=\"likkutei-sichot\" data-id=\"1300071195\">לקו\"ש ח\"ז ע' 183</a> הערה 39."],["864","25","ראה לקו\"ש שם, דמ\"ש ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא רפמ\"א</a> \"שהיראה היא שרש לסור מרע\" (ולא \"לשס\"ה ל\"ת\" כבפ\"ד) כי היראה היא שרש גם ל\"סור מרע\" <i>שבמ\"ע</i>."],["865","26","בלק שם (עג, ד)."],["866","27","וע\"ד \"ענין עובד אלקים המבואר בסש\"ב פט\"ו\" – לקו\"ת שם."],["867","28","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310035\" data-slug=\"tanya\" data-id=\"3401310035\">תניא פ\"ל (לח, ב</a>)."],["868","29","<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא רפ\"ד</a>."],["869","30","להעיר מסה\"מ ה'תשי\"א ע' 323, דביראה, האדם הירא והדבר שירא ממנו, הם שני ענינים. משא\"כ באהבה, מציאותו של האדם האוהב הוא הדבר שכוסף ומשתוקק אליו. ולכן, \"כשם שאי אפשר שישכנו האש והמים בכלי אחד, כן לא תשכון בלב המאמין אהבת הוי' ואהבת עוה\"ז\".\nועפ\"ז יש לומר, דזה שהיגיעה יותר מטבעו ורגילותו היא בהעבודה דועשה טוב דוקא, הוא, כי ע\"י אהבתו את הוי' (השרש דוע\"ט) הוא יוצא ממציאותו* וכל ענינו הוא אהבת ה'."],["870","31","שמואל-א כד, יד. וראה פרש\"י עה\"פ. פרש\"י משפטים כא, יג (ד\"ה והאלקים אנה לידו הב')."],["871","32","לקו\"ת שם (עד, א).\n*) <i>ואין סתירה לזה ממ\"ש ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא רפ\"ד</a> (נעתק לעיל בפנים) </i>\"<i>והמקיימן באמת הוא האוהב את שם הוי' </i><b>וחפץ לדבקה בו</b>\"<i> – כי </i>\"<i>אין הכוונה שמקיים את המצוות מצד הטוב המגיע </i><b>לו</b><i> מזה</i>,<i> כ\"א שעי\"ז יהי' דבוק </i><b>באלקות</b>\"<i> (סה\"מ ה'תש\"ח ע' 82)</i>."],["872","33","ראה תו\"א וארא שבהערה הבאה, דזה שבעסק התורה ה\"ה המלך עצמו (ראה לקמן בפנים) הוא כי התורה היא מבחינת אנכי שלמעלה מהוי'."],["873","34","וישב כז, ב. וארא נו, א."],["874","35","תו\"א וארא שם."],["875","36","ישעי' נא, טז."],["876","37","שבת קלח, ב."],["877","38","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550190\" data-slug=\"torat-chaim\" data-id=\"2300550190\">תו\"ח שמות תקלט, א</a> [בהוצאה החדשה – תצוה ח\"ב שסד, ב]. סה\"מ תר\"ן ע' שנו ואילך. סה\"מ קונטרסים ח\"ב שפח, ב."],["878","39","ואתחנן ו, ה. ברכות נד, א במשנה. ספרי (הובא בפרש\"י) עה\"פ."],["879","40","בהבא לקמן – ראה גם (עד\"ז) ד\"ה פדה בשלום ה'תשל\"ט סעיף ד (לקמן ח\"ב ע' מא)."],["880","41","שערי תשובה לאדמו\"ר האמצעי ח\"א (שער התפלה) נה, א."],["881","42","אבל לא ממש. כי אהבה זו היא מצד הנשמה, ורק <i>שמתעוררת</i> ע\"י ההתבוננות – קונטרס העבודה פ\"ה (ע' 18 ואילך). ובכ\"מ. וכ\"מ גם בתו\"ח שבהערה 38."],["882","43","המשך תרס\"ו ע' רסז. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a> \"שאי אפשר כלל\"."],["883","44","עקב יא, יג."],["884","45","להעיר מברכות לה, ב \"הרבה עשו כר\"י ועלתה בידן, כרשב\"י ולא עלתה בידן\". דמזה מוכח שענין \"עושין רצונו של מקום\" הוא רק ביחידי סגולה – והרי \"עושין רצונו של מקום\" הוא כשישנה גם האהבה דבכל מאדך, כדלקמן ס\"ה."],["885","46","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380190\" data-slug=\"likkutei-torah\" data-id=\"4001380190\">סהמ\"צ להצ\"צ לט, ב</a>. סה\"מ קונטרסים ח\"א קכו, א ואילך. וראה עד\"ז לקו\"ת אחרי כו, ג."],["886","47","או\"ת להה\"מ (הוצאת קה\"ת) פ' עקב נג, סע\"ג ואילך (בהוצאת קה\"ת ה'תש\"מ ואילך – סי' קסו). וראה גם חדא\"ג מהרש\"א לברכות שם."],["887","48","ראה בכ\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381125\" data-slug=\"likkutei-torah\" data-id=\"4001381125\">לקו\"ת ברכה צט, ג</a>. אמרי בינה שער הק\"ש פפ\"ו. חינוך (שבשערי תשובה לאדמו\"ר האמצעי) פמ\"ט (נו, א ואילך). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450496\" data-slug=\"or-hatorah-hb\" data-id=\"8316450496\">אוה\"ת עקב ע' תצו</a>. ראה ס\"ע תערב ואילך. ועוד."],["888","49","ראה בארוכה ד\"ה באתי לגני ה'תשכ\"ט ס\"ט (לקמן ח\"ב ע' שכה ואילך). וש\"נ."],["889","50","להעיר מלקו\"ת ברכה שם, שבכל מאדך הוא \"ביטול רצון\"."],["890","51","לקו\"ת דרושים לשבת שובה ד\"ה שובה הא' (סה, א)."],["891","52","כ\"ה הלשון ברד\"ה שובה ישראל ה'תש\"ד (סה\"מ ה'תש\"ד ע' 15). וכ\"ה גם ברד\"ה זה תרח\"צ (סה\"מ תרח\"צ ע' לד)."],["892","53","ראה לקמן בפנים (מהמשך תרס\"ו) בענין מלכיות זכרונות ושופרות. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380614\" data-slug=\"likkutei-torah\" data-id=\"4001380614\">לקו\"ת בלק שם (עד, א</a>), שע\"י עסק התורה (בקש שלום), שהיא משל ולבוש לקדמונו של עולם שלמעלה מסובב, נעשה השלום והחיבור דסובב וממלא."],["893","54","ע' תקלז ואילך."],["894","55","שם ע' תקמא ואילך."],["895","56","שם ע' תקמג."],["896","57","פל\"א."],["897","58","זכרי' ט, יד. ישעי' כז, יג. והם מפסוקי שופרות דר\"ה."],["898","59","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380957\" data-slug=\"likkutei-torah\" data-id=\"4001380957\">נצבים מז, ד</a> ואילך. ושם הוא בנוגע להשמות הוי' אד' שבפסוק כי כארץ תוציא צמחה גו' כן אד'הוי' יצמיח גו'. ובלקו\"ת דרושים לר\"ה (נט, ג) מדבר בהפסוק ואד' הוי' בשופר יתקע ומציין ללקו\"ת נצבים שם."],["899","60","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380958\" data-slug=\"likkutei-torah\" data-id=\"4001380958\">לקו\"ת</a> דרושים לר\"ה שם נט, סע\"ד. לעיל ע' י."],["900","61","פי\"א (קא, רע\"א)."],["901","62","ראה בארוכה ד\"ה שמח תשמח תרנ\"ז ס\"ע 49 ואילך (סה\"מ תרנ\"ז ע' רכג ואילך)."],["902","63","תהלים קיח, ה."],["903","64","ויצא כח, יד."],["904","65","יחזקאל מא, ז. שהש\"ר פ\"ז, ד."],["905","66","ראה ספרי דברים בתחלתו. פס\"ר פ' שבת ור\"ח. יל\"ש ישעי' רמז תקג."]]],[1500360014,"<h3>בס\"ד. ש\"פ האזינו, שבת תשובה, ה'תשל\"ז<sup data-n=\"906\">*</sup></h3>\n<b>שובה</b> ישראל עד הוי' אלקיך גו' קחו עמכם דברים ושובו אל הוי'<sup data-n=\"907\">1</sup>, וצריך להבין, דכשאומר שובה ישראל הרי הכוונה היא לתשובה כדבעי, ומכיון שמ\"ע להתוודות (כשעושה תשובה)<sup data-n=\"908\">2</sup>, ועד שהוידוי הוא מעיקרי התשובה<sup data-n=\"909\">3</sup>, הרי בשובה ישראל נכלל גם וידוי דברים, ומה מוסיף בקחו עמכם דברים<sup data-n=\"910\">4</sup>. כן צ\"ל ההמשך מה שאומר ושובו אל הוי', דמזה משמע שלאחרי התשובה דשובה ישראל גו', צריכה להיות עוד תשובה.\nב) <b>ויובן</b> זה בהקדים מה שנתבאר לעיל<sup data-n=\"911\">5</sup>, דמ\"ש שובה ישראל עד הוי' אלקיך (אף שלכאורה הול\"ל להוי' אלקיך), הוא, כפירוש אדמו\"ר הזקן<sup data-n=\"912\">6</sup>, שהתשובה צריכה להיות עד שהוי' יהי' אלקיך. ועוד פירוש<sup data-n=\"913\">7</sup> בשובה ישראל עד, שעד קאי על בחינה שלמעלה שנק' בשם עד<sup data-n=\"914\">8</sup>. וגם בזה שתי דרגות, עד ועד בכלל ועד ולא עד בכלל. עד ועד בכלל הוא (בד\"כ) בהמדריגות שבסדר השתלשלות, שכל המדריגות שבהשתלשלות הם בערך זל\"ז, ולכן, גם כשנמצא במדריגה תחתונה יש לו כבר שייכות להמדריגות שלמעלה ממנה, ועד למדריגה הכי עליונה, עד ועד בכלל. ועד ולא עד בכלל הוא בלמעלה מהשתלשלות, שגם כשהוא נמצא בדרגא הכי עליונה שבהשתלשלות, לא יגיע עי\"ז להדרגא שלמעלה מהשתלשלות, עד ולא עד בכלל.\n<b>ועפ\"ז</b> יש לבאר השייכות דתשובה לבחינת עד (שובה ישראל עד), כי בתשובה שני ענינים. זה שע\"י התשובה הוא מתקן וממלא את זה שהי' צריך לעשות, דזה הוא (בעיקר) בהבחינות דהשתלשלות (כי אדם הוא ציור מוחין ומדות), עד ועד בכלל. וזה שבכדי שיוכל לתקן ולמלאות ענינים אלו, צריך להגיע לבחי' שלמעלהמהשתלשלות (לא אדם שבאדם<sup data-n=\"915\">9</sup>), עד ולא עד בכלל. ויש לומר, שזהו גם מה שממשיך בכתוב (לאחרי אמרו שובה ישראל עד) הוי' אלקיך, כי הוי' ואלקים הם סובב וממלא, וע\"י שובה ישראל עד, שהתשובה שלו היא באופן שמעורר בחינת לא אדם שבו (עד ולא עד בכלל) וממשיך זה בגילוי בציור אדם שבו, עי\"ז יהי' הוי' אלקיך כחך וחיותך, שאור הסובב שלמעלה מהשתלשלות יאיר בו בגילוי בפנימיות.\nג) <b>והנה</b> נתבאר לעיל<sup data-n=\"916\">10</sup>, דבפירוש שובה ישראל עד הוי' אלקיך, שהתשובה צריכה להיות עד שהוי' יהי' אלקיך, שני ענינים, שהוי' יהי' אלקיך כחך וחיותך, ושהוי' יהי' רק בחי' אלקים וצמצום לגבי אוא\"ס שלמעלה מהוי'. ויש לומר, דשני הענינים שב(שובה ישראל) עד, עד ועד בכלל ועד ולא עד בכלל, הם בהתאם לשני הפירושים (ענינים) בהוי' אלקיך. והענין הוא, דזה שנתבאר לעיל ששני הענינים שבעד הם השתלשלות ולמעלה מהשתלשלות, הוא בכללות, אבל בפרטיות, גם בלמעלה מהשתלשלות ישנם שני הענינים שבעד. כמ\"ש בלקו\"ת<sup data-n=\"917\">11</sup>, דשני הענינים שבעד הם בכתר [דכתר, בכלל, הוא למעלה מהשתלשלות]. עד ועד בכלל הוא באריך, שרש הנאצלים. ועד ולא עד בכלל הוא בעתיק, בחינה תחתונה שבמאציל.\n<b>ויובן</b> זה ע\"פ הידוע<sup data-n=\"918\">12</sup>, שע\"י ההשגה באור הממלא שמתלבש בעולמות, שהוא הארה בלבד (כדמוכח מזה גופא שהוא בהתלבשות), באים לידי ידיעה שישנו אור שהוא מופלא מעולמות, שממנו נמשכת ההארה שבהתלבשות, ומכיון שע\"י ההשגה בההארה המתלבשת בעולמות באים להידיעה דאור המופלא מעולמות, אף שהידיעה באור זה היא רק ידיעת השלילה, שיודע שאור זה הוא מופלא מהעולמות ומההארה המתלבשת בהם, מ\"מ, מכיון שגם ידיעת השלילה היא ידיעה והשגה<sup data-n=\"919\">13</sup>, לכן גם האור המופלא מעולמות הוא בכלל עד ועד בכלל. [ועד\"ז הוא בעבודת האדם, דמכיון שהשכל עצמו מכריח אַז מיט שכל אַליין קען מען ניט דורכגיין, ובכדי שתהי' העבודה כדבעי, הוא דוקא ע\"י קבלת עול שלמעלה מהשכל, לכן, גם הקבלת עול (הבאה מזה שהשכל מכריח) היא בכלל עד ועד בכלל]. וענין עד ולא עד בכלל הוא בהאור שאין שייך בו גם ידיעת השלילה<sup data-n=\"920\">14</sup> [ובעבודת האדם – בהקבלת עול שמצד הנשמה].\n<b>ועפ\"ז</b> יש לבאר הקשר דשני הפירושים בשובה ישראל עד (שזה קאי על עד ועד בכלל, או שזה קאי על עד ולא עד בכלל) עם שני הפירושים בשובה ישראל עד הוי' אלקיך, עד שהוי' יהי' אלקיך כחך וחיותך ועד שהוי' יהי' רק בחי' אלקיםוצמצום לגבי אוא\"ס שלמעלה מהוי', דהפירוש שובה ישראל עד שהוא עד ועד בכלל, האור ששייך בו ידיעת השלילה, דבכללות הוא אור הסובב, הוא בהתאם להפירוש עד שהוי' יהי' אלקיך כחך וחיותך, שהאור שמתגלה ע\"י התשובה הוא אור הסובב (הוי'). והפירוש בשובה ישראל עד שהוא עד ולא עד בכלל, האור שאין שייך בו גם ידיעת השלילה, הוא בהתאם להפירוש עד שהוי' יהי' רק בחי' אלקים וצמצום לגבי אוא\"ס שלמעלה מהוי', שהאור שמתגלה ע\"י התשובה הוא האור שלמעלה גם מאור הסובב.\nד) <b>ובעומק</b> יותר יש לומר, דזה שהכתוב מוסיף הוי' אלקיך לאחרי שאומר כבר שובה ישראל עד, כי ענין הוי' אלקיך, שהוי' הוא רק בחי' אלקים וצמצום לגבי אוא\"ס שלמעלה מהוי', הוא למעלה יותר גם מעד ולא עד בכלל. ויובן זה ע\"פ מה שנתבאר לעיל<sup data-n=\"921\">15</sup> דבהוי' שבפסוק שובה ישראל עד הוי' אלקיך נכלל גם הוי' בניקוד אלקים, שהיא דרגא נעלית ביותר, כמבואר בלקו\"ת<sup data-n=\"922\">16</sup> (עה\"פ<sup data-n=\"923\">17</sup> כן אד' הוי' יצמיח צדקה גו') גודל העילוי של ב' השמות אד' והוי' (בניקוד אלקים). ואעפ\"כ כתיב עד הוי' אלקיך, שגם הוי' זה הוא רק בחי' אלקים וצמצום לגבי אוא\"ס שלמעלה מהוי', כי גם הוי' (בניקוד אלקים) הוא שם בלבד. וכמבואר בלקו\"ת<sup data-n=\"924\">18</sup> בענין ב' הדרגות דשופר שיהי' לע\"ל, ואד' הוי' בשופר יתקע גו' ויתקע בשופר גדול<sup data-n=\"925\">19</sup>, שהשופר דאד' הוי' בשופר יתקע, כיון שגם אד' הוי' (בניקוד אלקים) הם רק שמות, הוא שופר סתם, משא\"כ גבי שופר גדול כתיב יתקע בשופר גדול, יתקע סתם ולא נאמר מי הוא התוקע, כי תקיעה זו היא המשכה וגילוי מבחי' סתימא דכל סתימין. ומבואר בלקו\"ת שם, שעד\"ז הוא החילוק בין ראש השנה ליום הכפורים, שהשופר דראש השנה הוא ע\"ד ואד' הוי' בשופר יתקע, וביום הכפורים כתיב<sup data-n=\"926\">20</sup> <i>לפני</i> הוי' תטהרו, למעלה מהוי'<sup data-n=\"927\">21</sup>, ויתירה מזו<sup data-n=\"928\">22</sup>, כי ביום הזה יכפר עליכם<sup data-n=\"926\">20</sup>, יכפר סתם ולא נאמר מי הוא המכפר<sup data-n=\"927\">21</sup>, ע\"ד יתקע בשופר גדול, יתקע סתם. וזהו שאומרים בההפטורה דשבת תשובה, שובה ישראל עד הוי' אלקיך, שהוי' זה קאי גם על הוי' בניקוד אלקים, כי בשבת תשובה ישנו כבר מעין העילוי דיום הכפורים<sup data-n=\"929\">23</sup>, ולגבי עילוי זה גם הוי' בניקוד אלקים הוא רק בחי' אלקים וצמצום.<b>ועפ\"ז</b> יש לבאר זה שלאחרי שאומר שובה ישראל עד, שבזה נכלל גם עד ולא עד בכלל, מוסיף הוי' אלקיך, כי גם ענין עד ולא עד בכלל, אף שאין שייך בו גם ידיעת השלילה (כנ\"ל סעיף ג), מ\"מ מזה שצריך לשלול ולומר עד ולא עד בכלל, מובן<sup data-n=\"930\">24</sup>, שיש לו איזו שייכות. וע\"ד הענין דבעל הרצון שממנו נמשך הסליחה (כמבואר לעיל<sup data-n=\"931\">25</sup>), דבכללות הוא ענין השמות אד' הוי' בניקוד אלקים שעל ידם מתמלאים כל הפגמים<sup data-n=\"932\">26</sup>, דהגם שזה שנמשכת ממנו הסליחה על זה שעשו היפך הרצון הוא מפני שאינו מוכרח בהרצון<sup data-n=\"933\">27</sup>, מ\"מ יש להרצון שייכות אליו (כדמוכח מזה שנקרא בשם בעל <i>הרצון</i>), ולכן צריכה להיות הסליחה על זה שעשו היפך הרצון<sup data-n=\"934\">28</sup>. משא\"כ לגבי עצמות אוא\"ס שלמעלה גם מבעל הרצון, אין שייך פגם מלכתחילה. וכמבואר במ\"א<sup data-n=\"935\">29</sup> בענין עיצומו של יום מכפר<sup data-n=\"936\">30</sup>, שהכפרה הבאה מצד עיצומו של יום היא (לא באופן של פעולה, אלא) שביום זה מתגלה ההתקשרות של עצם הנשמה עם העצמות (שלמעלה גם מבעל הרצון), שלגבי דרגא זו אין שייך פגם מלכתחילה. וזהו שלאחרי שאומר שובה ישראל עד מוסיף הוי' אלקיך, דמכיון ששבת תשובה הוא הקדמה ליום הכפורים, לכן התשובה דשבת תשובה צריכה להיות לא רק עד, עד ולא עד בכלל, שעי\"ז <i>יתבטלו</i> כל הפגמים, אלא שצריך גם לעורר ולגלות את נקודת היהדות, ההתקשרות דעצם הנשמה עם העצמות (שלמעלה גם מבעל הרצון), שלגבי' גם הוי' בניקוד אלקים הוא רק בחי' אלקים וצמצום, ועי\"ז מתגלה שהענינים הבלתי רצויים הם רק בחיצוניות, אבל בפנימיות<sup data-n=\"937\">31</sup> (מצד ההתקשרות דישראל וקוב\"ה), מלכתחילה לא היו דברים בלתי רצויים.ה) <b>ויש</b> לומר, שגם ביום הכיפורים ישנם שני הענינים, הגילוי דעצם הנשמה שמקושרת עם העצמות, וזה שענין זה מתגלה בדרגות הפרטיות דהנשמה, עד לדרגת נפש שבה, שעי\"ז מתגלית הכפרה (שבאופן הנ\"ל) גם בהדרגות דהנשמה ששייך בהם פגם. וזהו שיום הכפורים הוא יום שנתחייב בה' תפלות<sup data-n=\"938\">32</sup>, ה' תפלות הם כנגד חמשה השמות דהנשמה, נפש רוח נשמה חי' ויחידה<sup data-n=\"939\">33</sup>, וענין יום שנתחייב בה' תפלות הוא שהגילוי דעצם הנשמה, שמצד עיצומו של יום, מתגלה בדרגות הפרטיות שלה. ויש לומר, שהחילוק בין ה' התפלות הוא לא רק בהמקום (הדרגא) שבו מתגלה עצם הנשמה, אלא גם בהגילוי. דבתפלת נעילה, בחינת יחידה, הגילוי הוא יותר מבד' התפלות שלפנ\"ז. ועד\"ז הוא בנוגע לד' התפלות עצמם, שהחילוק הוא גם באופן הגילוי. ועד\"ז הוא בהבחינות שלמעלה, דזה שיום הכפורים הוא יום שנתחייב בה' תפלות הוא לפי שביום הכפורים הוא עליית המלכות בעתיק (כמבואר בסידור<sup data-n=\"940\">34</sup>), דענין זה הוא בכל היום, ואעפ\"כ, יש בזה כו\"כ דרגות, ועיקר העלי' הוא בנעילה (כמבואר בסידור<sup data-n=\"941\">35</sup>).\n<b>והנה</b> הדרגות דיום הכפורים נחלקות לב' דרגות כלליות. שבת שבתון היא<sup data-n=\"942\">36</sup> (לשון נקבה) ושבת שבתון הוא<sup data-n=\"943\">37</sup> (לשון זכר). דב' הדרגות הם בעתיק, אלא שבעתיק שני פירושים. שבכללות, בחינה העליונה שבכתר (ובפרט התלת רישין שבה) נקראת בשם עתיק, אבל עיקר ענין דעתיקא הוא אוא\"ס שבהתלת רישין<sup data-n=\"944\">38</sup>. והחילוק בין שתי דרגות הנ\"ל הוא, דשבת שבתון היא (לשון נקבה) הוא בעתיק, בתלת רישין שבו (שבהם נכלל גם רדל\"א), ושבת שבתון הוא (לשון זכר) הוא באוא\"ס שברדל\"א<sup data-n=\"945\">39</sup>. ועפ\"ז יש לומר תוספת ביאור בזה שלאחרי שאומר שובה ישראל עד מוסיף הוי' אלקיך, כי עד ולא עד בכלל הוא בעתיק (כמובא לעיל ס\"ג מלקו\"ת), וזה שהוי' כאלקים יחשב לגבי אוא\"ס שלמעלה מהוי' יש לומר שזהו לגבי אוא\"ס שברדל\"א.\nו) <b>ויש</b> לומר, דזה שאומרים שמעלתו של יום הכפורים הוא, שהוא יום שנתחייב בה' תפלות, אף שהיום עצמו (גילוי התקשרות העצמות דעצם הנשמה עם העצמות) הוא נעלה יותר מזה שנתחייב בה' תפלות (הגילוי בדרגות הפרטיות דהנשמה), הוא, כי זה שעצם הנשמה מתגלית בדרגות הפרטיות שלה, שעי\"ז הכפרה בהמקום שבו הי' תחילה הפגם, יש בזה יתרון לגבי הדרגא דעצם הנשמה. דהגם שבהבחינות נר\"נ ובפרט בחי' נפש (כמו שהם מצד עצמם) שייך פגמים אעפ\"כ הם מתכפרים. [ויתירה מזו, שהכפרה שמצד עיצומו של יום היא באופן שמתגלה שבפנימיות לא הי' בהם פגם מלכתחילה, כנ\"ל]. ועד\"ז הוא גם בענין הכפרה עצמו,שעיקר החידוש שבכפרה הוא בכפרה על חטאים כפשוטם. דהכפרה על החטאים שבצדיקים, הענין דיש מי שאוהב וכיו\"ב שלגבי מדריגתם הוא כמו פריקת עול<sup data-n=\"946\">40</sup>, כיון שעל חטאים אלה אין שייך לומר שהם היפך רצון הקב\"ה [שהרי ישות זו היא מפני הטבע שהטביע הקב\"ה<sup data-n=\"947\">41</sup>], לכן, הכפרה שעל זה אינה חידוש כ\"כ. ועיקר החידוש ו(במילא) המעלה היא בכפרה על חטאים כפשוטם, שבזה מתגלה תוקף הבלתי מוגבל של ההתקשרות דישראל וקוב\"ה, שגם כשעשו היפך רצונו מ\"מ (ע\"י התשובה והכפרה) הם מרוצים לפניו ית' כמו שלא חטאו מעולם<sup data-n=\"948\">42</sup>. וזהו שארז\"ל<sup data-n=\"949\">43</sup> במקום שבעלי תשובה עומדין אין צדיקים גמורין יכולים לעמוד בו, דיש לומר שאין מרז\"ל זה יוצא מידי פשוטו<sup data-n=\"950\">44</sup> ועיקר המעלה דבעלי תשובה הוא בבעלי תשובה כפשוטם. ועפ\"ז יובן מה שמביא הצ\"צ<sup data-n=\"951\">45</sup> (מספר טעמי המצוות להרח\"ו<sup data-n=\"952\">46</sup>), דזה שהאריז\"ל הי' נוהג לומר פרטי הוידויים הוא, כי כל ישראל הם גוף אחד, דלכאורה הי' אפשר לומר שהוידויים של האריז\"ל היו על ענינים שבתכלית הדקות ששייכים גם אצלו<sup data-n=\"953\">47</sup> [וע\"ד שנת\"ל בענין הישות דיש מי שאוהב], וזה שמבארים דהוידויים של האריז\"ל היו (גם) על חטאים כפשוטם מפני שכל ישראל הם גוף אחד, יש לומר, כי ע\"פ ביאור זה דוקא מובן שאצל האריז\"ל היתה גם המעלה דבעלי תשובה כפשוטם<sup data-n=\"954\">48</sup>.\nז) <b>ויש</b> להוסיף, שעיקר החידוש והמעלה שבבעלי תשובה הוא בהעבודה דתומ\"צ שלאחרי התשובה, כי עבודת התשובה היא לדלג שור<sup data-n=\"955\">49</sup> שלא כסדר ודרך השתלשלות. ולכן, גילוי התקשרות העצמית דעצם הנשמה עם העצמות שע\"י התשובהוהכפרה, עם היות שהגילוי הוא בדרגות אלו שבהם הי' הפגם, שבכללות הוא הבחינות נר\"נ, הרי זה כמו שהנר\"נ הם באופן של העלאה למעלה (להדרגות חי' יחידה, ועד לעצם הנשמה). ועיקר החידוש והמעלה דתשובה הוא בזה שע\"י התשובה, גם העבודה דתומ\"צ היא בחילא יתיר<sup data-n=\"956\">50</sup>. שהעבודה בתומ\"צ היא בסדר מסודר [ד(רוב) המצוות יש להן שיעור מצומצם כמבואר בתניא<sup data-n=\"957\">51</sup>, ועאכו\"כ לימוד התורה שהוא בהבנה והשגה], וע\"י שהעבודה דתומ\"צ שלאחרי התשובה היא בחילא יתיר, הגילוי דחי' יחידה (וי\"ל גם דעצם הנשמה) בנר\"נ הוא כמו שהנר\"נ הם למטה. ויתירה מזו, שע\"י העבודה דתומ\"צ נעשה גם העולם דירה לו ית', ועי\"ז נשלמת הכוונה דדירה בתחתונים, וכידוע בענין במי נמלך בנשמותיהן של צדיקים<sup data-n=\"958\">52</sup>, דזה שאמרו בנשמותיהן של צדיקים (אף שבמקום שבעלי תשובה עומדין אין צדיקים גמורין יכולין לעמוד בו), כי תכלית כוונת הבריאה היא שיהי' דירה לו ית' בתחתונים, וזה נעשה ע\"י עבודת הצדיקים, עבודה דתומ\"צ. אלא שהשלימות בהעבודה דתומ\"צ הוא כשהיא באה לאחרי קדימת התשובה שאז העבודה דתומ\"צ היא בחילא יתיר, ועי\"ז מיתוסף בהגילוי אלקות (שבאדם, ועי\"ז) גם בעולם, ועי\"ז נשלמת יותר הכוונה דדירה בתחתונים.\nח) <b>וזהו</b> שובה ישראל עד הוי' אלקיך גו' קחו עמכם דברים גו', דזה שמוסיף קחו עמכם דברים לאחרי שאומר שובה ישראל עד הוי' אלקיך, הוא, כי מצד גודל העילוי שבעבודת התשובה, ובפרט בהתשובה דשובה גו' עד הוי' אלקיך, שהתשובה היא בבחינת עד ולא עד בכלל, ויתירה מזו – הוי' אלקיך, שעי\"ז מתגלית עצם הנשמה שקשורה עם העצמות (שלמעלה גם מבעל הרצון), ואע\"פ שהוא נמצא בדרגא נעלית ביותר, ולכאורה אינו שייך לתיקון הפגמים [ובפרט שבכדי לתקן זה צריך לירד ממדריגתו], בכל זה אומר קחו עמכם דברים, שצריך להיות וידוי דברים, בכדי למחות את גוף הקליפות<sup data-n=\"959\">53</sup>.\n<b>ועוד</b> פירוש בקחו עמכם דברים, שדברים הם תורה ומצוות<sup data-n=\"960\">54</sup>. שגם בענין דתיקון החטאים, אף שיש בזה היתרון שעי\"ז נמשך הגילוי דעצם הנשמה (גם) בהדרגות התחתונות ששייך בהם פגם, מ\"מ, גם זה אינו מספיק, וצ\"ל קחו עמכם דברים, תורה ומצוות, שעי\"ז יהי' העילוי גם בהדרגות דהנשמה כמו שהם למטה (ולא באופן דהעלאה), ויתירה מזו, שעי\"ז נעשה גם בירור וזיכוך בהעולם, ונעשה דירה לו ית' בתחתונים.\n<b>וזהו</b> גם מה שממשיך בכתוב ושובו אל הוי', שלאחרי התשובה דשובה ישראל עד הוי' אלקיך שהיא העלאה מלמטה למעלה, צ\"ל ושובו אל הוי', להמשיך האורמלמעלה למטה ע\"י תומ\"צ שהם דרך הוי'<sup data-n=\"961\">55</sup>. ועי\"ז, ממשיכים כל ההשפעות לא רק בענינים רוחניים אלא גם בענינים גשמיים, בבני חיי ומזוני רויחי, וכמאמר אדמו\"ר הזקן<sup data-n=\"962\">56</sup> אַז דער אויבערשטער גיט אידן גשמיות און אידן מאַכן פון די גשמיות רוחניות, ועושים דירה לו ית' בתחתונים, ועי\"ז – והיתה להוי' המלוכה<sup data-n=\"963\">57</sup>.\n**********",[["906","*","יצא לאור ב<b>קונטרס שבת תשובה-מוצאי יום הכפורים – תש\"נ</b>, \"לקראת שבת תשובה, ולקראת יום הכפורים . . <i>עש\"ק שובה שנת ה'תש\"נ</i>\".\nמאמר זה הוא המשך למאמר שלפניו (ד\"ה זה דוא\"ו תשרי) לעיל ע' פט ואילך. ולכן לא נכפלו כאן (רוב) הציונים והמ\"מ שכבר נסמנו שם."],["907","1","הושע יד, ב-ג. – התחלת וראשית ההפטורה דשבת תשובה."],["908","2","סמ\"ג מ\"ע טז. סהמ\"צ להרמב\"ם מ\"ע עג. הל' תשובה פ\"א ה\"א. \"מנין המצוות על סדר הלכות הרמב\"ם זצ\"ל\" הלכות תשובה. ועוד."],["909","3","סהמ\"צ להצ\"צ מצות וידוי ותשובה בתחלתה (לח, א)."],["910","4","ראה במפרשים להושע שם, שקחו עמכם דברים הוא וידוי. וכ\"ה באוה\"ת דרושים לשבת שובה ד\"ה זה ס\"ע א'תצו."],["911","5","בד\"ה שובה ישראל דוא\"ו תשרי הנ\"ל ס\"ו (לעיל ע' צג)."],["912","6","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380621\" data-slug=\"likkutei-torah\" data-id=\"4001380621\">לקו\"ת פינחס עה, ב</a>. דרושים לשבת שובה ד\"ה שובה הא' ס\"ד (סה, א)."],["913","7","ראה בארוכה בכ\"ז ד\"ה שובה תרס\"ו."],["914","8","ראה גם לקו\"ת דרושים לשבת שובה ד\"ה שובה הב' ס\"ה (סז, ג), דפירוש שובה ישראל עד הוא \"להשיב בחי' עד\". אלא שהביאור שם הוא באופן אחר."],["915","9","ראה סה\"מ תרכ\"ח ע' נד ואילך, שעיקר פרצוף האדם הוא מן החוטם ולמטה, והפדחת שלמעלה מהחוטם \"הוא למעלה מבחי' אדם\", בחינת לא אדם."],["916","10","בד\"ה שובה ישראל הנ\"ל (שבהערה 5) ס\"ו-ז (לעיל ע' צג ואילך)."],["917","11","פקודי ז, ג."],["918","12","ראה לקמן ח\"ד ע' טז ואילך. <i>וש\"נ</i>."],["919","13","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380066\" data-slug=\"likkutei-torah\" data-id=\"4001380066\">לקו\"ת פקודי ו, ג</a>."],["920","14","ראה סה\"מ עת\"ר ע' יו\"ד, דידיעת השלילה היא באריך משא\"כ בעתיק. ועפ\"ז יומתק זה שעד ועד בכלל הוא באריך ועד ולא עד בכלל הוא בעתיק."],["921","15","בד\"ה שובה הנ\"ל ס\"ח (לעיל ע' צה)."],["922","16","נצבים נא, א ואילך."],["923","17","ישעי' סא, יא."],["924","18","דרושים לר\"ה נט, ג-ד."],["925","19","זכרי' ט, יד. ישעי' כז, יג."],["926","20","אחרי טז, ל."],["927","21","וכ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380190\" data-slug=\"likkutei-torah\" data-id=\"4001380190\">לקו\"ת אחרי כו, ג</a> – נסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380958\" data-slug=\"likkutei-torah\" data-id=\"4001380958\">לקו\"ת</a> דרושים לר\"ה שם נט, סע\"ד."],["928","22","בלקו\"ת שם, יכפר סתם ולפני הוי', באים בהמשך אחד. ויש לומר, שזהו בכללות. אבל בפרטיות הם שני ענינים."],["929","23","שהרי מיני' מתברכין כל ימי השבוע שלאחריו (זח\"ב סג, ב. פח, א). ולהעיר, שבכללות, גם בר\"ה ישנה המשכה זו דיתקע בשופר גדול, כמבואר בד\"ה שובה שבהערה 15.\nועפ\"ז יומתק יותר זה שבשבת תשובה אומרים שובה גו' הוי' אלקיך, מכיון ששבת תשובה הוא <i>לאחרי</i> ר\"ה, והענין דיתקע בשופר גדול נמשך כבר <i>בפועל</i>."],["930","24","להעיר משעהיוה\"א פ\"ט (פו, ב) \"כאומר על איזו חכמה רמה ועמוקה שאי אפשר למששה בידים מפני עומק המושג, שכל השומע יצחק לו, לפי שחוש המישוש אינו מתייחס ונופל אלא על עשי' גשמיית הנתפסת בידים\". דיש לומר, דזה שא\"א לומר על חכמה רמה ועמוקה שא\"א למששה בידים הוא לא רק מפני שזה שא\"א למששה בידים אינו מורה כלל על העומק (וההפלאה) של החכמה* – כי אי משום הא, לא הי' זה מעורר \"צחוק אצל כל השומע\" – כי אם, שהשכל והמישוש הם שני ענינים נבדלים לגמרי שאין יחס ביניהם, ובלשון התניא \"שחוש המישוש <i>אינו מתייחס</i> ונופל אלא על עשי' גשמיית\". וענין השלילה, שאומרים על איזה דבר שהוא מושלל מהשני, שייך דוקא בדברים שיש יחס ביניהם, ולכן \"כל השומע יצחק לו\"."],["931","25","בד\"ה שובה הנ\"ל ס\"ה (לעיל ע' צג). <i>וש\"נ</i>."],["932","26","לקו\"ת נצבים ור\"ה שבהערה 16 והערה 18."],["933","27","ראה סה\"מ אעת\"ר ע' יח שהוא כמו מלך המצוה דבר ע\"י שליח, שהשליח אינו יכול לשנות מציווי המלך ומרצונו, משא\"כ המלך אינו מוכרח בהרצון וביכלתו לשנות.\nויש לומר, דמזה שבעל הרצון אינו מוכרח בהרצון וביכלתו לשנות, מוכח, שהוא מובדל מהרצון ואינו בגדר מקור אליו (ולא כאריך שהוא שרש הנאצלים), שלכן, ע\"י הרצון א\"א לידע את בעל הרצון, גם לא באופן דידיעת השלילה. ואעפ\"כ, יש להרצון שייכות אליו, כבפנים."],["934","28","להעיר מלקו\"ת דרושים לר\"ה שם (נט, ג) שהשמות אד' הוי' הם \"למלאות כל הפגמים\"."],["935","29","לקו\"ש ח\"ד ע' 1151 ואילך."],["936","30","ראה רמב\"ם הל' תשובה פ\"א ה\"ג \"ועצמו של יוהכ\"פ מכפר <i>לשבים</i>\". ומזה מוכח, דזה שעיצומו של יום מכפר הוא גם לדעת רבנן שיוהכ\"פ אין מכפר אלא על השבים (שבועות יג, א). וצורך התשובה הוא רק בכדי שהענין דעיצומו של יום יומשך בגילוי להאדם, כמבואר בארוכה בלקו\"ש שם ע' 1150."],["937","31","גם בהדרגות שבחיצוניות היו בהם ענינים בלתי רצויים.\n*) <i>וע\"ד מ\"ש בהמשך תרס\"ו ע' נח ובכ\"מ</i>,<i> שאין שייך לשלול ענינים שבאין ערוך</i>,<i> כי ע\"י שלילה זו אין משיגים הפלאתו של הדבר שממנו שוללים אותו</i>."],["938","32","ראה לקו\"ת ס\"פ פנחס."],["939","33","ב\"ר פי\"ד, ט. דב\"ר פ\"ב, לז."],["940","34","עם דא\"ח שער יוהכ\"פ רנ, סע\"ד ואילך."],["941","35","שם רנ, סע\"א ואילך."],["942","36","אחרי טז, לא."],["943","37","אמור כג, לב."],["944","38","לקו\"ת דרושים ליוה\"כ עא, ג, מביאור האד\"ז להרח\"ו."],["945","39","לקו\"ת שם עא, ד."],["946","40","ראה ד\"ה שובה ה'תשמ\"א ס\"ו (לקמן ס\"ע קיד ואילך). וש\"נ."],["947","41","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380942\" data-slug=\"likkutei-torah\" data-id=\"4001380942\">לקו\"ת</a> דרושים לר\"ה נה, ד, \"שהבכי' (בר\"ה ויוהכ\"פ) היא לנשמתו כו' שירדה ממקום כבודה ונתגשמה\", ד\"הגשמה\" זו (שע\"י ירידתה בגוף) היא טבע שהטביע הקב\"ה.\nולהוסיף, שאין לומר שהכוונה בזה שהטביע הקב\"ה טבע זה הוא בכדי שהאדם <i>ישנה</i> את הטבע (ויבטל את ההגשמה) – כי לפי זה, הצ\"ג הי' בודאי מתקן זה מכבר (לפני ר\"ה ויוהכ\"פ), ומזה שלא תיקן זה מקודם, מוכח שעד עכשיו לא הי' זה ביכלתו. וביטול \"הגשמה\" זו היא רק ע\"י הבכי' בר\"ה ויוהכ\"פ (ובכל שנה, הוא יוצא מ\"הגשמה\" דקה יותר). וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091209\" data-slug=\"likkutei-sichot\" data-id=\"1300091209\">לקו\"ש ח\"ט ע' 209</a> ואילך. ואכ\"מ."],["948","42","ראה רמב\"ם הלכות תשובה פ\"ז ה\"ד."],["949","43","רמב\"ם שם, מברכות לד, ב."],["950","44","ובפרט שהרמב\"ם מביא זה בספרו שכותב \"בלשון <i>ברורה</i> . . עד שיהיו כל הדינין גלויין (גם) לקטן\" (הקדמת הרמב\"ם)."],["951","45","בסהמ\"צ שלו מצות אהבת ישראל בתחלתה (דרמ\"צ כח, א)."],["952","46","פ' קדושים. וכ\"ה גם בפרע\"ח שער יב (שער הסליחות) פ\"ח. סידור האריז\"ל (להר\"ש) לפני נפ\"א. עט\"ז לשו\"ע או\"ח בתחלתו, מכתבי האריז\"ל."],["953","47","וע\"ד המבואר בסה\"מ תרנ\"ט ע' סד: שלפי עוצם גדולת ורוממות הא\"ס כו' הרי גם עבודת הצדיקים היותר גדולים אינו בערך עוצם גדולתו כלל. וזהו שכאו\"א אומר הוידוים בעשי\"ת אשמנו כו' <i>גם צדיק גמור כמו משה רבינו ע\"ה הי' צ\"ל וידוים בעשי\"ת</i> והיינו מפני שלפי אמיתות גדולתו ורוממותו גם העבודה האמיתית לחטא יחשב כו'. וראה עד\"ז בסה\"מ תרנ\"א ע' עה ואילך. שם ע' ריב. שם ע' ריד ואילך."],["954","48","וי\"ל דשני ענינים בזה: (א) דמכיון שכל ישראל הם גוף אחד, \"מגיע הכאב (של זה החטא) גם לאבר העליון שמושרש נפש האריז\"ל\" (סהמ\"צ שם כח, ב), וע\"י הוידוי דהאריז\"ל תיקן הכאב אצלו שנעשה ע\"י חטא כפשוטו. (ב) יתירה מזו, דע\"י שכל ישראל הם גוף אחד, פעל ע\"י הוידוי שלו (בבחינת מקיף) תיקון החטא עצמו כמו שהוא בזה שחטא."],["955","49","לקו\"ת דרושים לשבת שובה ד\"ה שובה ישראל הא' ס\"ד (סה, א). וראה בארוכה ד\"ה זה ה'תשל\"ו (לעיל ע' פג ואילך)."],["956","50","ל' הזהר ח\"א קכט, ב."],["957","51","אגה\"ק ס\"י."],["958","52","ב\"ר פ\"ח, ז. רות רבה פ\"ב, א (ג). וראה לקו\"ת שם. המשך תרס\"ו ע' תקלג. וראה גם לקמן ח\"ב ע' כח, ובהנסמן שם הערה 127."],["959","53","ראה סהמ\"צ להצ\"צ מצות וידוי ותשובה (לח, ב)."],["960","54","לקו\"ת דרושים לשבת שובה ד\"ה שובה הב' ס\"ד (סה, א). המשך תרס\"ו ע' תקלג."],["961","55","כידוע שהמצוות נק' דרכי הוי' – הושע בסופו. נזיר כג, א. הוריות יו\"ד, ב. זוהר וביאוה\"ז ר\"פ וישלח. ועוד."],["962","56","ראה \"היום יום\" כז טבת (אגרות-קודש כ\"ק אדמו\"ר מוהריי\"צ ח\"ב ע' רסה). סה\"מ ה'ש\"ת (הוצאת קה\"ת תשמ\"ו) ע' עח. אגרות-קודש הנ\"ל חי\"א ע' לד."],["963","57","עובדי' א, כא."]]],[1500360015,"<h3>בס\"ד. ש\"פ האזינו, שבת שובה ה'תש\"מ<sup data-n=\"964\">*</sup></h3>\n<b>שובה</b> ישראל עד ה' אלקיך<sup data-n=\"965\">1</sup>, וידוע בזה דיוק רבותינו נשיאינו מהו אומרו עד הוי' אלקיך דלכאורה הול\"ל להוי' אלקיך<sup data-n=\"966\">2</sup>. וגם מה שנקט ב' השמות הוי' ואלקיך<sup data-n=\"967\">3</sup>. ובפרט שאומר כאן שובה ישראל, דשם ישראל מתאר מדריגה הנעלית שבישראל, דבני ישראל נחלקים בכלל לב' מדריגות יעקב וישראל, ושם ישראל הוא ע\"ש כי שרית עם אלקים ועם אנשים ותוכל<sup data-n=\"968\">4</sup>, שמזה מובן שמדבר כאן בענין שלימות התשובה<sup data-n=\"969\">5</sup>. וכמובן גם ממה שההפטורה דשבת תשובה היא שובה ישראל, שהתשובה דשבת תשובה היא דרגא נעלית בתשובה עילאה. דהנה שבת אותיות תשב היא בחי' תשובה עילאה<sup data-n=\"970\">6</sup>, ובתשובה עילאה גופא [שיש בה כמה דרגות] היא תשובה נעלית שהרי צ\"ל כל ימיו (גם בימי החול) בתשובה עילאה<sup data-n=\"971\">7</sup>, שמזה מובן, ששבת היא דרגא נעלית בתשובה עילאה גופא. ובפרט בשבת תשובה שמתקן ומעלה את כל שבתות השנה [כמבואר בכתבי האריז\"ל<sup data-n=\"972\">8</sup> בענין ז' הימים שבין ראש השנה ליום הכפורים שיש בהם כל ז' ימי השבוע, שביום הראשון בשבוע שבימים אלו מתקנים ומעלים את ימי ראשון דכל השנה, ועד\"ז ביום ב' וכו', ובשבת תשובה מתקנים ומעלים את השבתות דכל השנה], כי התשובה דשבת תשובה היא נעלית גם מהתשובה דכל שבתות השנה, ותשובה זו היא בדוגמת יום הכפורים<sup data-n=\"973\">9</sup> דכתיב בי'<sup data-n=\"974\">10</sup> כי ביום הזה יכפר עליכם גו' לפני הוי' תטהרו, לפני הוי' דוקא למעלה משם הוי'<sup data-n=\"975\">11</sup>, ועוד יותר מזה אומר יכפר עליכם סתם מאן דלית לי' שם ידיעא ולא אתפס בשם כו'<sup data-n=\"976\">12</sup>, ולמה אומר כאן עד הוי' אלקיך.\nב) <b>וידוע</b> הביאור בזה<sup data-n=\"977\">13</sup>, דמ\"ש שובה ישראל עד הוי' אלקיך הוא ענין יחוד הוי' ואלקים כמ\"ש<sup data-n=\"978\">14</sup> וידעת גו' הוי' הוא האלקים, שהיא ידיעה נעלית ביותר,כמבואר בזהר<sup data-n=\"979\">15</sup>. ולכן אומר שובה ישראל עד הוי' אלקיך כי ענין התשובה שייך לידיעה זו כמ\"ש<sup data-n=\"980\">16</sup> (גבי ענין התשובה שהי' בהר הכרמל) ויאמרו הוי' הוא האלקים הוי' הוא האלקים. וכפל הוי' הוא האלקים הוי' הוא האלקים ב' פעמים לפי שע\"י עבודת התשובה, שהיא למעלה מעבודת הצדיקים, נמשך ענין הוי' הוא האלקים ב' פעמים. וכדאיתא במדרש<sup data-n=\"981\">17</sup> נאמר בסיני<sup data-n=\"982\">18</sup> אנכי ה' אלקיך בכרמל יאמר כפול ה' הוא האלקים ה' הוא האלקים, ומבואר בלקו\"ת<sup data-n=\"983\">19</sup> שבסיני היו ישראל בדרגת צדיקים, וע\"י עבודת הצדיקים (תומ\"צ) נמשך ענין הוי' הוא האלקים פעם אחת, משא\"כ בהר הכרמל ע\"י התשובה המשיכו הוי' הוא האלקים ב' פעמים. והוא ע\"ד מה שבמ\"ת כתיב אנכי ה' אלקיך, אנכי פעם אחת, משא\"כ גבי תשובה כתיב<sup data-n=\"984\">20</sup> אנכי אנכי הוא גו' למעני גו', אנכי ב' פעמים, לפי שע\"י העבודה דתומ\"צ נמשך בחי' אנכי פעם אחת, משא\"כ ההמשכה שע\"י עבודת התשובה היא למעלה יותר מההמשכה שע\"י העבודה דתומ\"צ<sup data-n=\"985\">21</sup>. דזהו ג\"כ מ\"ש אנכי אנכי הוא גו' למעני ותרגם בדיל שמי, עד בחי' שמו הגדול<sup data-n=\"986\">22</sup>, ולמעלה יותר בחי' הי' הוא ושמו בלבד, לפני הצמצום.\nג) <b>והענין</b> הוא, הנה בהוי' הוא האלקים יש ב' פירושים וענינים<sup data-n=\"987\">23</sup>. הא' שגם הצמצום דאלקים הוא הוי'. דהנה הוי' הוא לשון מהוה<sup data-n=\"988\">24</sup>, דכל ההתהוות היא משם הוי', אלא שבכדי שתהי' ההתהוות בפועל בבחי' יש ודבר נפרד, הנה זהו ע\"י שם אלקים שהוא מעלים ומסתיר על שם הוי', כמ\"ש<sup data-n=\"989\">25</sup> כי שמש ומגן הוי' אלקים. וזהו הוי' הוא האלקים, דהגם שההתהוות בפועל ובגילוי היא משם אלקים כמ\"ש<sup data-n=\"990\">26</sup> בראשית ברא אלקים את השמים ואת הארץ, ול\"ב פעמים אלקים נאמר במעשה בראשית<sup data-n=\"991\">27</sup>, שמצד זה נעשה העולם ליש ודבר נפרד, הנה ע\"ז בא הציווי וידעת גו' כי הוי' הוא האלקים, שגם שם אלקים המצמצם ומעלים הוא הוי', דהוי' ואלקים כולא חד, ולכן באמת (כמו שהוא לגבי הקב\"ה) אינו מסתיר כלל<sup data-n=\"992\">28</sup>, וע\"י העבודה דתומ\"צ ממשיכים גילוי שם הוי' בעולם. דזהו מ\"ש אשר ברא אלקים לעשות<sup data-n=\"993\">29</sup>, לעשות לתקן<sup data-n=\"994\">30</sup>, שצריך לתקן את ההסתר דשם אלקים ולהמשיך גילוי שם הוי'בעולם, כמ\"ש (לאח\"ז<sup data-n=\"995\">31</sup>) ביום עשות הוי' אלקים ארץ ושמים, שנזכר כאן גם שם הוי'. כי ע\"י עבודת האדם, לעבדה ולשמרה (תורה ומצוות<sup data-n=\"996\">32</sup>) נמשך גילוי שם הוי' בעולם, ונעשה אלה תולדות השמים והארץ גו'<sup data-n=\"995\">31</sup>, תולדות מלא<sup data-n=\"997\">33</sup>, ועד לאלה תולדות פרץ, תולדות מלא<sup data-n=\"998\">34</sup>, שהוא למעלה יותר גם מאלה תולדות השמים והארץ, כי ע\"י העבודה דתומ\"צ פורצים את כל ההעלמות וההסתרים דשם אלקים, ועושים דירה לו ית' בתחתונים. וענין הב' בהוי' הוא האלקים הוא, שגם שם הוי' (כמו שהוא למעלה מהתלבשות בשם אלקים) הוא רק בחי' אלקים וצמצום לגבי עצמותו ומהותו ית' כביכול, וכמ\"ש<sup data-n=\"999\">35</sup> אני הוי' הוא שמי שבחינת הוי' אינו אלא שם, זיו והארה בלבד, שהוא צמצום רב ועצום לגבי אור א\"ס ב\"ה עצמו כביכול.\nד) <b>והנה</b> שני ענינים אלו נמשכים ע\"י ב' העבודות דצדיקים ובעלי תשובה. דכאשר האדם הוא באופן דהאלקים עשה את האדם ישר<sup data-n=\"1000\">36</sup> הנה ע\"י עבודתו בתורה ומצוות הוא ממשיך הגילוי דשם הוי' בשם אלקים (ענין הא' בהוי' הוא האלקים), כנ\"ל (ס\"ג). אבל כשחטא ופגם והעביר את הדרך א\"א לו להמשיך מבחי' הוי' (מאחר שפגם בשם הוי'), וצריך להמשיך מבחי' שלמעלה משם הוי'<sup data-n=\"1001\">37</sup>. והמשכה זו היא ע\"י עבודת התשובה. כי כל הענינים שלמעלה נמשכים ע\"י עבודה דוקא. וגם המשכת אוא\"ס שלמעלה מהשתלשלות שאין אתערותא דלתתא מגעת שם, אינה שורה ומתגלה (בבחי' פנימיות) אלא כשיש שלימות במעשה התחתונים<sup data-n=\"1002\">38</sup>, דקוב\"ה לא שריא אלא באתר שלים<sup data-n=\"1003\">39</sup>. והמשכה זו (דאוא\"ס שלמעלה מהשתלשלות) היא ע\"י העבודה דלמעלה מהשתלשלות (שבאדם), עבודת התשובה. דכאשר עושה תשובה ובפרט כזו שזדונות נעשו לו כזכיות<sup data-n=\"1004\">40</sup>, שהיא תשובה מאהבה מעומקא דלבא באהבה רבה כמבואר בתניא<sup data-n=\"1005\">41</sup>, הנה עי\"ז הוא מעורר מבחי' שלמעלה משם הוי', שלגבי' גם הוי' כאלקים יחשב, ענין הב' בהוי' הוא האלקים. [וזוהי המעלה שבתשובה כפשוטה על התשובה דשבת אותיות תשב, כי התשובה (והעלי') דשבת אותיות תשב היא רק ענין ויכל אלקים<sup data-n=\"1006\">42</sup>, שכלתה מדת הצמצום וההסתר דשם אלקים ונמשך התגלות שם הוי'<sup data-n=\"1007\">43</sup>, אבל בכדי לעורר מבחי' שלמעלה משם הוי', הנה זה נעשה ע\"י תשובה כפשוטה, ובפרט ע\"י תשובה כזו שזדונות נעשו לו כזכיות, כי ע\"י בירור והפיכתהזדונות נעשה יתרון האור. ובמכ\"ש ממה דאיתא בזהר<sup data-n=\"1008\">44</sup> שענין מ\"ת נעשה דוקא ע\"י הודאת יתרו עתה ידעתי כי גדול הוי' מכל האלקים<sup data-n=\"1009\">45</sup>, אף שבמ\"ת נאמר אנכי (רק) פעם אחת, עאכו\"כ ענין אנכי אנכי ב' פעמים, שהמשכתו היא ע\"י בירור והפיכת החושך דוקא. וע\"ד המבואר בתניא<sup data-n=\"1010\">46</sup> שתכלית השלימות שיהי' בימות המשיח, דירה לו ית' בתחתונים, תלוי (בעיקר) במעשינו ועבודתינו במשך זמן הגלות דוקא]. ולאחרי ההתעוררות שלמעלה מהוי' (ע\"י התשובה) צריך להמשיך<sup data-n=\"1011\">47</sup> מלמעלה למטה בבחי' הוי' לשון מהוה, ועד לבחי' הוי' כמו שהוא מתלבש בשם אלקים, ענין הא' בהוי' הוא האלקים. וזהו מה שבתשובה נאמר ב' פעמים הוי' הוא האלקים, שבתחלה הוא ענין העלי' מלמטה למעלה עד שלגבי' הוי' כאלקים יחשב (פירוש הב' בהוי' הוא האלקים), ואח\"כ ההמשכה מלמעלה למטה בהוי' לשון מהוה, וכמו שמתלבש בשם אלקים (פירוש הא' בהוי' הוא האלקים) שמזה נעשה ההתהוות בפועל, בראשית ברא אלקים את השמים ואת הארץ&lt;26&gt;, ולא רק ההמשכה בע\"ס (כפירוש הזהר<sup data-n=\"1012\">48</sup> שבראשית גו' קאי על הע\"ס), אלא גם בהשמים והארץ וכל צבאיהם כפשוטם.\nה) <b>וזהו</b> ג\"כ ב' הענינים<sup data-n=\"1013\">49</sup> שבתקיעת שופר (שרומז לענין התשובה<sup data-n=\"1014\">50</sup>), מה שקול השופר הוא קלא פנימאה (בחי' פנימיות הלב) וביחד עם זה צריך לתקוע בשופר גשמי דוקא, כי בראש השנה חוזרים כל הדברים לקדמותם, וע\"י השופר מעוררים המשכה חדשה מהעצמות. ששופר הוא בחינת בינה שהיא למעלה מהשתלשלות, בחינת רצון שלמעלה גם מבחינת בינה, ולמעלה יותר המשכה חדשה מפנימיות ועצמות ב\"ה, ומשם נמשך בבחי' פנימיות הרצון, בפנימיות בינה וכו' עד בבחי' פנימיות העולמות, ומזה נמשך אח\"כ גם בחיצוניות העולמות, כמבואר בסידור<sup data-n=\"1015\">51</sup> בד\"ה להבין ענין תק\"ש ע\"פ כוונת הבעש\"ט ז\"ל. ולכן יש בשופר ב' ענינים הנ\"ל, ע\"י קלא פנימאה שבשופר, בחי' פנימיות הלב, מעוררים בעצמות, וע\"י התקיעה בשופר גשמי, ובשופר של בהמה דוקא, ויתירה מזו שקרן השופר צריך להיות תלוש (ולא מחובר להבהמה), בחי' דומם, עי\"ז ממשיכים למטה בעשי' עד לבחי' דומם. וכמו שאומרים בתפלת ראש השנה וידע כל פעול כי אתה פעלתו, שגם בעשי' (כדאיתא בכתבי האריז\"ל<sup data-n=\"1016\">52</sup> שכל פעול קאי על עולם העשי'), וגם הדומם שבעשי', ידע כי אתה פעלתו.\nו) <b>וזהו</b> שובה ישראל עד הוי' אלקיך, עד לשון נצחיות<sup data-n=\"1017\">53</sup>, שענין הנצחיות שייך בגדר הזמן דוקא (דמה שלמעלה מגדר הזמן הוא למעלה אפילו מהי' הוהויהי' כאחד<sup data-n=\"1018\">54</sup>), אלא שבגדר הזמן הוא בבחי' נצחיות. ולכן עד היא בבחי' מלכות, שהיא<sup data-n=\"1019\">55</sup> בבחי' וגדר הזמן&lt;53&gt;. וישראל הוא בחי' ז\"א. ופירוש שובה ישראל עד הוי' אלקיך, שצריך להשיב ישראל עד שתהי' המלכות באופן דעד ובחינות ישראל ובחי' עד (ז\"א ומלכות, בחינות ההשתלשלות) להוי' אלקיך, היינו לעצמות אוא\"ס שלגבי' הוי' כאלקים יחשב<sup data-n=\"1020\">56</sup>, ומשם צריך להמשיך בבחי' הוי' אלקיך, הוי' לשון מהוה ובזה גופא כמו שמתלבש בשם אלקים, ונעשה אלקיך כחך וחיותך. וזהו ג\"כ מה שאומרים בנעילת יום הכפורים ז' פעמים הוי' הוא האלקים, כי בעשרת ימי תשובה גופא [שאז התשובה היא יפה ביותר ומתקבלת היא מיד<sup data-n=\"1021\">57</sup>] עיקר התשובה הוא ביום הכפורים, כמ\"ש הרמב\"ם<sup data-n=\"1022\">58</sup> יום הכפורים הוא זמן התשובה לכל כו' והוא קץ מחילה וסליחה לישראל כו', וביום הכפורים גופא עיקר התשובה הוא בתפלת נעילה (גמר היום) שאז הוא נעילת שערים ונמצאים ישראל ומלכא בלחודוהי<sup data-n=\"1023\">59</sup>, לכן אומרים אז ז' פעמים הוי' הוא האלקים, שיש בזה ב' ענינים הנ\"ל. ענין העלי' (מלמטלמ\"ע) בעצמות אוא\"ס, וכידוע דענין הוי' הוא האלקים (שאומרים בנעילת יום הכפורים) הוא מה שז\"א (הוי') בעלותו לעתיקא כאלקים יחשב<sup data-n=\"1024\">60</sup>, וענין ההמשכה מלמעלה למטה (בהוי' לשון מהוה ועד כמו שמתלבש בשם אלקים), דזהו מה שאומרים זה ז' פעמים בכדי להמשיך בבחי' ז\"ת. וי\"ל דזהו ג\"כ מה שאומרים אז שמע ישראל הוי' אלקינו הוי' אחד פעם אחת ובשכמל\"ו ג' פעמים והוי' הוא האלקים ז' פעמים, שמע ישראל גו' פעם אחת הו\"ע העלי' מלמטה למעלה<sup data-n=\"1025\">61</sup> ובשכמל\"ו<sup data-n=\"1026\">62</sup> ג' פעמים והוי' הוא האלקים ז\"פ הו\"ע ההמשכה מלמעלה למטה בכל הע\"ס (ג' מוחין וז' מדות).\nז) <b>ויש</b> לקשר זה עם הכתוב וביום שמחתכם גו' ותקעתם בחצוצרות גו'<sup data-n=\"1027\">63</sup>, וידועה תורת הרב המגיד<sup data-n=\"1028\">64</sup> שתי חצוצרות שתי חצאי צורות, ומבואר בהמאמר<sup data-n=\"1029\">65</sup> דענין שתי חצאי צורות הוא בבחי' הגילויים (צורה מורה על גילוי), ששם שייך לומר שהקב\"ה וכנסת ישראל הם שתי חצאי צורות שמשלימות זא\"ז. משא\"כ בעצמות,ישראל וקוב\"ה הם חד ממש (ואין שייך לומר שהם ב' חצאים). וכמו\"כ הוא גם בענין שתי חצאי צורות שבנשמה<sup data-n=\"1030\">66</sup>, חלק הנשמה שלמעלה ראש שבנשמה וחלק הנשמה שבגוף (בחי' נר\"נ) רגל שבנשמה, שזהו דוקא בבחי' הגילויים שבנשמה, דגם ראש שבנשמה הוא עד בחי' חי' שיש לה שייכות לבחי' רגל שבנשמה (נשמה שבגוף), שלכן נקראת בשם מזל לפי שהיא מזלת ומטפת להארת הנשמה המלובשת בגוף. משא\"כ בחי' יחידה ובפרט עצם הנשמה, עם היותה כוללת את כל הכחות ולמעלה יותר נושאת את כל הכחות, היא למעלה מבחי' מקור ושייכות לבחי' הגילויים, והיא (דוקא<sup data-n=\"1031\">67</sup>) נמצאת בכל הבחינות דנשמה<sup data-n=\"1032\">68</sup>, עד בבחי' עקב שבה, וגם בבחי' עקב שבגוף, וגם בד' אמות (שמחוץ לגוף האדם)<sup data-n=\"1033\">69</sup>, שלכן ד' אמותיו של אדם קונות לו<sup data-n=\"1034\">70</sup>, כמבואר בכ\"מ<sup data-n=\"1035\">71</sup>, וזוהי המעלה דשופר על חצוצרות, כמרז\"ל<sup data-n=\"1036\">72</sup> שופר מאריך וחצוצרות מקצרות שמצות היום בשופר, כי העבודה דשופר היא בעצם הנשמה שהיא חד ממש עם העצמות, למעלה<sup data-n=\"1037\">73</sup> מענין שתי חצאי צורות.\nח) <b>וזהו</b> ג\"כ שופר מאריך, דענין האריכות הוא הן למעלה והן למטה, כי העבודה דשופר מגעת בהעצם (בעצם הנשמה ובעצמותו ית') שלמעלה מכל הגילויים (אריכות למעלה), שהוא נמצא כנ\"ל גם בהעקב (אריכות למטה), ועי\"ז נשלמה הכוונה דדירה לו ית' בתחתונים, בב' הענינים, לו לעצמותו ובתחתונים. אלא שצריך גם לבחי' הגילויים, וכמו בדירת מלך בו\"ד שצ\"ל (נוסף על העיקר, דירה לעצמות המלך) דירה נאה וכלים נאים, לכן צ\"ל גם חצוצרות, ומצד החביבות שבזה נשמעים ב' הקולות (חצוצרות ושופר)<sup data-n=\"1038\">74</sup>, אבל מצות היום בשופר, לפי שעיקר העבודה בראש השנה הוא העבודה שמצד עצם הנשמה שהיא חד עם העצמות.\nט) <b>וזהו</b> מה שבעשרת ימי תשובה (עשרה ימים שבין ראש השנה ליום הכפורים) מפטירים שובה ישראל עד הוי' אלקיך, כי ימים אלו שבין ראש השנה ליום הכפורים הם בדוגמת ראש השנה ויום הכפורים. ולכן כמו שראש השנה הוא בחי' ראש שממנו נמשך החיות לכל ימי השנה וגם אח\"כ ההנהגה בכל ימי השנה היא כפי אופן ההנהגה וההחלטה דראש השנה (כמבואר בארוכה בעטרת ראש בראשו), ועד\"ז הוא גם יום הכפורים שנקרא ג\"כ בשם ראש השנה<sup data-n=\"1039\">75</sup> ולא עוד אלאשיום הכפורים הוא בחי' נשמה ופנימיות<sup data-n=\"1040\">76</sup>, עד\"ז גם בהז' ימים שבין ראש השנה ליום הכפורים שהם בחי' ראש שמהם נמשך על כל ימי השנה. וע\"ד דאיתא בכתבי האריז\"ל (כנ\"ל ס\"א), י\"ל עד\"ז<sup data-n=\"1041\">77</sup> שמיום הראשון דשבוע שבז' ימים אלו נמשך על כל יום ראשון שבמשך השנה, ומיום שני דז' ימים אלו על כל יום שני וכו', ומשבת תשובה על כל שבתות השנה. ולכן בדוגמת שני הענינים דהעלאה והמשכה בשופר דראש השנה ובאמירת ז\"פ הוי' הוא האלקים בנעילת יוכ\"פ, עד\"ז הוא בהתשובה בימי התשובה שביניהם [ובפרט בשבת תשובה, הראש דכל שבתות השנה, שבת אותיות תשב], שיש בה ב' ענינים אלו. ולכן אומרים אז שובה ישראל עד הוי' אלקיך, שכולל ב' הענינים, העלי' דבחי' ישראל (ז\"א) ובחי' עד (מלכות) לבחי' הוי' אלקיך היינו לעצמות אוא\"ס שלגבי' הוי' כאלקים יחשב, ואח\"כ ההמשכה מעצמות אוא\"ס לבחי' הוי' אלקיך היינו לבחי' הוי' כמו שנעשה אלקיך כחך וחיותך. וכל זה נעשה ע\"י שובה סתם, התשובה שמצד עצם הנשמה, און דער קער פון יחידה [ומזה נמשך תשובה בבחי' ישראל ראש שבנשמה ועד רגל שבנשמה], ועי\"ז נעשה הפדי' מהגלות, גאולה הפרטית<sup data-n=\"1042\">78</sup> ואח\"כ גם גאולה הכללית בביאת משיח צדקנו שאתא לאתבא צדיקייא בתיובתא<sup data-n=\"1043\">79</sup>, שגם זה שייך לבחי' יחידה כידוע שמשיח הוא בחי' יחידה<sup data-n=\"1044\">80</sup>, שיהי' פדה בשלום נפשי גו' פדאני לי ולבני מבין האומות<sup data-n=\"1045\">81</sup>, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, בקרוב ממש ובעגלא דידן.\n**********",[["964","*","יצא לאור בשעתו, \"<i>י\"ג תשרי</i>,<i> ה'תש\"מ</i>\"."],["965","1","הושע יד, ב."],["966","2","לקו\"ת ש\"ש סו, ריש ע\"ב. רד\"ה זה תרס\"ו. ובכ\"מ."],["967","3","רד\"ה זה תרנ\"ט. תרצ\"ה. ובכ\"מ."],["968","4","וישלח לב, כט."],["969","5","ראה לקו\"ת שם סה, ג, שענין שובה ישראל הוא ע\"ד מה שבשמו\"ע דוקא אומרים סלח לנו כי חטאנו, כי דוקא לאחרי העבודה דק\"ש (\"שמע <i>ישראל</i>\") \"יבין שיש חטא ופשע ואזי יאמר סלח לנו כו'\"."],["970","6","אגה\"ת ספ\"י."],["971","7","שם פי\"א (ק, סע\"ב)."],["972","8","שעה\"כ דרושי ר\"ה (לפני דרוש הא'). סידור האריז\"ל במקומו. מ\"ח מס' ימי תשובה פ\"א מ\"ג."],["973","9","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381013\" data-slug=\"likkutei-torah\" data-id=\"4001381013\">לקו\"ת האזינו עב, ג</a>: \"יו\"כ נקרא שבת שבתון שהוא השבת של כל שבתות השנה . . שהוא עיקר יום התשובה ובכל השבתות מאיר הארה ממנו\" – שגם התשובה דשבת תשובה פועלת בכל שבתות השנה, ע\"ד הנ\"ל (בפנים) מכתבי האריז\"ל – ראה לקמן ס\"ט ובהערה 77."],["974","10","אחרי טז, ל."],["975","11","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380190\" data-slug=\"likkutei-torah\" data-id=\"4001380190\">לקו\"ת אחרי כו, ג</a>. ש\"ש סה, א."],["976","12","לקו\"ת אחרי שם."],["977","13","ראה לקו\"ת ד\"ה שובה ישראל (הא'). ד\"ה זה תרצ\"ה (בסופו). תש\"ד."],["978","14","ואתחנן ה, לט."],["979","15","ח\"ב כה, א. קסא, א – הובא ונתבאר בסהמ\"צ להצ\"צ מצות אחדות ה' (ס, א ואילך)."],["980","16","מ\"א יח, לט."],["981","17","\"מדרש אגדה\" הובא בפרש\"י (לנביאים) שופטים ה, ג."],["982","18","יתרו כ, ב."],["983","19","ד\"ה שובה הא' (סה, ב)."],["984","20","ישעי' מג, כה. וראה פרש\"י שופטים שם."],["985","21","לקו\"ת שם, רע\"ג. וראה גם ד\"ה אנכי אנכי תרפ\"ז (קרוב לסופו)."],["986","22","ראה ד\"ה אנכי שם: למעני בדיל שמי שהוא בחי' מל' דא\"ס."],["987","23","לקו\"ת שם פ\"ב."],["988","24","שעהיוה\"א רפ\"ד. וראה זח\"ג רנז, ב. פרדס ש\"א פ\"ט. ועוד."],["989","25","תהלים פד, יב. וראה שעהיוה\"א פ\"ד."],["990","26","בראשית א, א."],["991","27","תקו\"ז תי\"ב."],["992","28","שעהיוה\"א פ\"ו (פ, ב)."],["993","29","בראשית ב, ג."],["994","30","ראה ב\"ר פי\"א, ו ובפרש\"י שם."],["995","31","בראשית שם, ד."],["996","32","שם, טו. תיב\"ע עה\"פ."],["997","33","ב\"ר פי\"ב, ו."],["998","34","רות ד, יח. ב\"ר שם."],["999","35","ישעי' מב, ח."],["1000","36","ע\"פ קהלת ז, כט."],["1001","37","לקו\"ת שם פ\"ג."],["1002","38","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381225\" data-slug=\"likkutei-torah\" data-id=\"4001381225\">לקו\"ת שה\"ש כד, סע\"א</a> ואילך."],["1003","39","זח\"ג צ, ב."],["1004","40","יומא פו, ב."],["1005","41","פ\"ז (יב, א)."],["1006","42","בראשית ב, ב."],["1007","43","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380606\" data-slug=\"likkutei-torah\" data-id=\"4001380606\">לקו\"ת בלק עב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381257\" data-slug=\"likkutei-torah\" data-id=\"4001381257\">שה\"ש לב, א</a>. המשך תרס\"ו ע' כב. ובכ\"מ. ובלקו\"ת בלק שם, שזהו\"ע שבת אותיות תשב."],["1008","44","ח\"ב סז, ב. נתבאר באוה\"ת ר\"פ יתרו. ד\"ה ויאמר משה תש\"ט פ\"ו. ובכ\"מ."],["1009","45","יתרו יח, יא."],["1010","46","רפל\"ז."],["1011","47","ראה לקו\"ת ד\"ה שובה הנ\"ל פ\"ד."],["1012","48","ח\"א רנו, ב."],["1013","49","ראה גם ד\"ה וביום שמחתכם שנה זו ספ\"א ורפ\"ב (לעיל ע' כה)."],["1014","50","רמב\"ם הל' תשובה פ\"ג ה\"ד."],["1015","51","רמו, ג."],["1016","52","סידור האריז\"ל במקומו."],["1017","53","לקו\"ת ד\"ה שובה הב' (סז, ג)."],["1018","54","עט\"ר שער ר\"ה פ\"ד: \"הי' הוה ויהי' כא' שהוא למעלה מבחי' התחלקות הזמן דעבר הוה עתיד\", \"מ\"מ הרי הוא שרש התחלקות הזמן . . ונק' מקור הזמן עכ\"פ\". ועוד. ועיין לקו\"ת שם (וכ\"ה גם באוה\"ת ש\"ש ריש ע' א'תקכב)."],["1019","55","ראה גם שעהיוה\"א פ\"ז (פב, א)."],["1020","56","לקו\"ת ד\"ה שובה הא' ספ\"ג."],["1021","57","רמב\"ם שם פ\"ב ה\"ו."],["1022","58","שם ה\"ז."],["1023","59","ראה זח\"ג לב, א."],["1024","60","לקו\"ת שם סה, ריש ע\"ד (ממ\"ח סוף מס' יומא)."],["1025","61","ראה בשל\"ה שצריך לכוון למסנ\"פ."],["1026","62","בכתבי האריז\"ל (סידורו וכו') מבואר באופן אחר לגמרי – אבל ע\"פ משנ\"ת בד\"ה יחיינו תרצ\"ד (תשי\"א) ותש\"ז וז\"ל: \"ובשכמל\"ו . . אומרים ג\"פ, דבעיקרו הוא בהמדות והמדות עיקרם חג\"ת . . והוי' הוא האלקים זהו העבודה בפועל . . לכן אומרים זה ז\"פ להורות דענין זה יהי' קבוע בכל מדה ומדה ממש\", היינו דיש (גם) כוונה שמדובר בעבודה ובהמשכה מלמעלמ\"ט – אולי י\"ל גם כמבואר בפנים."],["1027","63","בהעלותך יו\"ד, יו\"ד."],["1028","64","או\"ת מה, ד ואילך. וראה ד\"ה וביום שמחתכם שנה זו הערה 35 (לעיל ע' כו)."],["1029","65","ד\"ה אנכי אנכי תרפ\"ז. וראה גם המשך תער\"ב פשפ\"ד."],["1030","66","ראה ד\"ה וביום שמחתכם הנ\"ל פ\"ד (לעיל שם)."],["1031","67","משא\"כ בחי' חי' – ראה קונטרס העבודה פ\"ד (ע' 33)."],["1032","68","שהרי היא ה\"עצם\" של כל מדריגות הפרטיות – ראה בארוכה קונטרס ענינה של תורת החסידות פי\"ז."],["1033","69","אמ\"ב שער הק\"ש פמ\"ב. ד\"ה אתה אחד לאדמו\"ר האמצעי (ברוקלין, תשכ\"ה) ע' 10 [מאמרי אדמו\"ר האמצעי קונטרסים ע' יא]."],["1034","70","ב\"מ י, א."],["1035","71","קונטרס הנ\"ל ס\"כ."],["1036","72","ר\"ה כו, ב (במשנה)."],["1037","73","ד\"ה וביום שמחתכם תרפ\"ז (בסופו). ד\"ה אנכי שם (בתחלתו ובסופו)."],["1038","74","ר\"ה כז, א."],["1039","75","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380975\" data-slug=\"likkutei-torah\" data-id=\"4001380975\">יחזקאל מ, א</a>. וראה לקו\"ת ר\"ה סד, א. ובהנסמן שם."],["1040","76","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380951\" data-slug=\"likkutei-torah\" data-id=\"4001380951\">לקו\"ת שם נח, א</a>."],["1041","77","כמו שבשבת ויכולו גו' דהשבוע שעבר ומיני' מתברך השבוע הבא. וראה עט\"ר עד\"ז בנוגע להראש והאברים."],["1042","78","אגה\"ק ס\"ד."],["1043","79","הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">לקו\"ת שמע\"צ צב, ב</a>. שה\"ש נ, סע\"ב. ובכ\"מ. וראה זח\"ג קנג, ב."],["1044","80","סה\"מ תרצ\"ט ע' 207 בשם הרמ\"ז."],["1045","81","תהלים נה, יט. ברכות ח, א."]]],[1500360016,"<h3>בס\"ד. ש\"פ האזינו, שבת שובה ה'תשמ\"א<sup data-n=\"1046\">*</sup></h3>\n<b>שובה</b> ישראל עד הוי' אלקיך כי כשלת בעוניך<sup data-n=\"1047\">1</sup>, ופירש אדמו\"ר הזקן<sup data-n=\"1048\">2</sup>, דמ\"ש שובה גו' עד הוי' אלקיך (אף שלכאורה הול\"ל להוי' אלקיך<sup data-n=\"1049\">3</sup>) הוא, ששיעור התשובה הוא עד שהוי' יהי' אלקיך<sup data-n=\"1050\">4</sup>. וצריך להבין, דמי ששייך (ודורשים ממנו) תשובה נעלית כזו, הרי הוא בעל מדריגה נעלית גם קודם עשיית תשובה זו, וכמובן גם ממ\"ש שובה ישראל, דשם ישראל הוא על שם כי שרית עם אלקים ועם אנשים ותוכל<sup data-n=\"1051\">5</sup>, שהוא שר<sup data-n=\"1052\">6</sup> ושולט על ההעלם דשם אלקים ועל הכחות שמתפשטים ממנו (אנשים)<sup data-n=\"1053\">7</sup>, ואיך שייך בו ענין העון שיהי' צריך לתשובה. והגם שידוע שתשובה היא לא רק על עבירות<sup data-n=\"1054\">8</sup> אלא להשיב נפשו למקורה ושרשה [והרוח תשוב אל האלקים אשר נתנה<sup data-n=\"1055\">9</sup>], דתשובה זו היא גם בצדיקים גמורים<sup data-n=\"1056\">10</sup>, הרי מפורש בכתוב שובה ישראל גו' כי כשלת בעוניך<sup data-n=\"1057\">11</sup>, והיאך שייך ענין העוונות במי שהוא בדרגא זו. גם צריך להבין מה שממשיך בכתוב<sup data-n=\"1058\">12</sup> קחו עמכם דברים ושובו אל הוי', דאחרי שכבר אמר שובה ישראל גו' מה מוסיף ב(קחו עמכם דברים) ושובו אל הוי'<sup data-n=\"1059\">13</sup>. גם צריך להבין מה שאומר אח\"כ<sup data-n=\"1058\">12</sup> אמרו אליו כל תשא עון גו', שגם האמירה והבקשה תשא עון קשורה עם ענין התשובה<sup data-n=\"1060\">14</sup>, ומזה משמע שלאחרי התשובה דשובה ישראל גו' ודשובו אל הוי', צריך להיות עוד תשובה<sup data-n=\"1059\">13</sup>. גם צ\"ל מה שבתשובה הא' ובתשובה הג' מזכיר ענין העון (כי כשלת בעוניך, תשא עון), משא\"כ בתשובה הב'.ב) <b>ונקודת</b> הביאור בזה ע\"פ המבואר בלקו\"ת<sup data-n=\"1061\">15</sup>, דבתשובה יש ג' בחינות. תשובה דסור מרע, תשובה דועשה טוב, ותשובה דבקש שלום דקאי על התורה דכל העוסק בתורה משים שלום בפמליא של מעלה ובפמליא של מטה<sup data-n=\"1062\">16</sup>, וכל התורה ניתנה לעשות שלום בעולם<sup data-n=\"1063\">17</sup>. וג' התשובות שבפסוקים אלו [שובה ישראל גו', ושובו אל הוי', אמרו אליו כל תשא עון] הם ג' התשובות דסור מרע ודועשה טוב ודבקש שלום<sup data-n=\"1064\">18</sup>. וזהו גם מה שפסוקים אלו הם התחלת ההפטרה דשבת תשובה, כי בשבת תשובה צ\"ל כל ג' הבחינות. וכמו שסיפר כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1065\">19</sup>, שאצל הצמח צדק היו בשבת תשובה ג' נרות של תשובה, ואמר הצמח צדק \"עס איז פאַראַן דריי תשובות\", וביאר כ\"ק מו\"ח אדמו\"ר שהם ג' התשובות המבוארים בלקו\"ת<sup data-n=\"1061\">15</sup>. וזהו מה שבתשובה הראשונה כתיב שובה גו' כי כשלת בעוניך, משא\"כ בתשובה השני' (ושובו אל הוי') לא נזכר ענין העון, כי תשובה הראשונה היא תשובה דסור מרע (כשלת בעוניך), משא\"כ השני' היא תשובה דועשה טוב<sup data-n=\"1066\">20</sup>. וזהו גם מה שבתשובה הראשונה נזכר גם שם אלקים (עד הוי' אלקיך) ובתשובה השני' נזכר רק שם הוי' (ושובו אל הוי') ובתשובה השלישית כתיב אמרו אליו, כי התשובה דסור מרע היא שיהי' הוי' אלקינו<sup data-n=\"1067\">21</sup>, והתשובה דועשה טוב היא להתקשר ולהדבק בשם הוי' כמו שהוא למעלה משם אלקים<sup data-n=\"1068\">22</sup>, והתשובה דבקש שלום היא להדבק וליכלל בעצמות אוא\"ס שלמעלה משם הוי'<sup data-n=\"1069\">23</sup>.\nג) <b>והנה</b> החילוק שבין התשובה דסור מרע להתשובה דועשה טוב ודבקש שלום הוא, שהתשובה דסור מרע היא שלא יהיו עוונות שמבדילים ביניכם לבין אלקיכם<sup data-n=\"1070\">24</sup>, והתשובה דועשה טוב ודבקש שלום היא שתהי' העבודה להמשיך אור נעלה יותר. דההמשכה שנמשכת מלמעלה מצד עצמה, מצד זה שהוא ית' הוא עצם הטוב וטבע הטוב להטיב<sup data-n=\"1071\">25</sup>, היא במדידה והגבלה, וע\"י העבודה ההמשכה היא בלי גבול<sup data-n=\"1072\">26</sup>.וכמו שידוע<sup data-n=\"1073\">27</sup> בענין אלה תולדות פרץ<sup data-n=\"1074\">28</sup> תולדות מלא<sup data-n=\"1075\">29</sup>, שהוא למעלה גם מאלה תולדות השמים והארץ בהבראם<sup data-n=\"1076\">30</sup> תולדות מלא<sup data-n=\"1075\">29</sup>, עולם על מילואו נברא<sup data-n=\"1077\">31</sup>, דתולדות מלא שנאמר גבי בריאת שמים וארץ (בריאה מצד מלמעלה) רצה הבורא שיהי' במדידה והגבלה, משא\"כ תולדות פרץ מלא שיהי' (בביאת המשיח<sup data-n=\"1078\">32</sup>) ע\"י מעשינו ועבודתינו<sup data-n=\"1079\">33</sup> הוא מה שמשיח (מבני פרץ, ונקרא הפורץ<sup data-n=\"1080\">34</sup>) יפרוץ כל הגדרים. ובזה גופא (ההמשכה שע\"י עבודה), ההמשכה שע\"י עסק התורה (בקש שלום) היא נעלית יותר מההמשכה שע\"י קיום המצוות (ועשה טוב). דנוסף לזה שע\"י המצוות ההמשכה היא בבחי' מקיף וע\"י התורה ההמשכה היא בפנימיות<sup data-n=\"1081\">35</sup>, גם ההמשכה עצמה היא נעלית יותר. דע\"י קיום המצוות נמשך אור הסובב<sup data-n=\"1082\">36</sup>, וע\"י עסק התורה נמשך עצמות אוא\"ס שלמעלה גם מסובב<sup data-n=\"1083\">37</sup>.\nד) <b>וע\"פ</b> הנ\"ל דשובה ישראל כי כשלת בעוניך היא התשובה דסור מרע, מובן, דזה שגם מי שהוא בדרגת ישראל שייך אצלו הענין דכשלת בעוניך, הכוונה בזה היא לא (רק) שיש בו איזה חסרון [שזהו גם בצדיקים], אלא ששייך אצלו גם עוונות המבדילים<sup data-n=\"1084\">38</sup> (אלא שהם בדקות דדקות), ולכן צ\"ל אצלו התשובה דסור מרע. וענין זה [שגם בצדיקים (ישראל) יש גם התשובה דסור מרע] מובן גם מזה שתשובה היא מצוה [וכלשון אדה\"ז באגרת התשובה<sup data-n=\"1085\">39</sup> \"מצות התשובה\"], דמזה מובן, שמצות התשובה היא (ככל המצוות) לכאו\"א מישראל, גם לצדיקים גמורים. ומכיון שמצות התשובה היא (כמ\"ש אדה\"ז באגה\"ת שם) עזיבת החטא (סור מרע), מובן, דנוסף על זה שגם בצדיקים גמורים צ\"ל התשובה דוהרוח תשוב אל האלקים אשר נתנה [וכמבואר בלקו\"ת (פרשתנו) דשרש הנשמה הוא בחי' האלקים (אשר נתנה), שהוא בחי' צור<sup data-n=\"1086\">40</sup> שלמעלה מהוי'<sup data-n=\"1087\">41</sup>, העלם שאינו במציאות<sup data-n=\"1088\">42</sup>, והמשכת הנשמה מבחינהזו היא באופן ד(אשר) נתנה, דכל<sup data-n=\"1089\">43</sup> הנותן בעין יפה הוא נותן<sup data-n=\"1090\">44</sup>, וענין התשובה דוהרוח תשוב אל האלקים אשר נתנה הוא השבת והעלאת הנשמה לשרשה ומקורה, דגם כמו שהנשמה מלובשת בגוף (שהרי מצות התשובה היא, ככל המצוות, לנשמות בגופים דוקא) תהי' בבחי' ביטול לגמרי כמו שהיתה בשרשה, בבחי' האלקים אשר נתנה<sup data-n=\"1091\">45</sup>], צריך להיות אצלם גם תשובה כפשוטה. וצריך להבין, והרי באצילות (אפילו באצילות הפרטית) כתיב לא יגורך רע<sup data-n=\"1092\">46</sup>, ומכיון שהתשובה דצדיקים היא (כנ\"ל מלקו\"ת) אל האלקים אשר נתנה, למעלה מבחי' בראתה יצרתה נפחתה בי (בי\"ע) ולמעלה גם מבחי' שנתת בי (אצילות)<sup data-n=\"1093\">47</sup>, איך יתכן אצלם ענין התשובה דסור מרע.\nה) <b>ולכאורה</b> הי' אפשר לבאר זה ע\"פ מ\"ש בלקו\"ת<sup data-n=\"1094\">48</sup>, דמי שמצד מעלת נשמתו שייך להעבודה דבחי' רוח (ועשה טוב) ומכ\"ש מי ששייך להעבודה דבחי' נשמה (בקש שלום), כשחסר אצלו בעבודה זו הוא פגם. ויתירה מזו, דלהיותו במדריגה נעלית, הפגם שלו (עם היותו בדקות) הוא גדול יותר מהעון ממש דאיש פשוט. וכמו שאמר הרב המגיד שהמ\"ז של צדיקים גמורים פוגמים יותר מעוונות חמורים של ע\"ה. וע\"ד רבב על בגד ת\"ח<sup data-n=\"1095\">49</sup>. ועפ\"ז הי' אפ\"ל לכאורה, דמצות התשובה (שהיא עזיבת החטא) בצדיקים גמורים היא התשובה על זה שהי' אצלם חסרון בהעבודה דועשה טוב או עכ\"פ בהעבודה דבקש שלום, שגם תשובה זו היא עזיבת החטא, מכיון שהפגם שעל ידי זה הוא עוד יותר מהעון (כפשוטו) דאיש פשוט. אמנם, מזה גופא שאומרים שישנם ג' ענינים (סור מרע, עשה טוב ובקש שלום), מוכח, שהעבודה דוע\"ט ודבקש שלום היא הוספה ועלי' בקדושה גופא, וגם כשחסר בעבודה זו, אין זה ענין של רע (גם לא בדקות). ועפ\"ז צריך להבין מהו\"ע מצות התשובה (עזיבת החטא) בצדיקים, שעל זה אומר שובה ישראל גו' כי כשלת בעוניך, דגם מי שהוא בדרגת ישראל צ\"ל אצלו גם התשובה דסור מרע.\nו) <b>ויובן</b> זה ע\"פ מאמר רז\"ל<sup data-n=\"1096\">50</sup> מאן דמחוי במחוג קמי מלכא כו', כי בפני המלך צריך להיות בתכלית הביטול וכשמחוה במחוג קמי מלכא הוא מתראה למציאות בפני המלך<sup data-n=\"1097\">51</sup>. ומזה מובן, שגם כשהוא עובד את הוי' אבל עבודתו היא בבחי' מציאות, הוא דוגמת מחוי במחוג קמי מלכא ח\"ו<sup data-n=\"1098\">52</sup>. ועפ\"ז יובן שגם בצדיקיםגמורים צ\"ל (גם) ענין התשובה דסור מרע, כי מכיון שגם כשהוא צדיק גמור עובד ה' ביראה ואהבה בתענוגים אינו בטל במציאות לגמרי רק הוא דבר בפני עצמו ירא ה' ואוהבו (יש מי שאוהב ויש מי שירא<sup data-n=\"1099\">53</sup>) כמבואר בתניא<sup data-n=\"1100\">54</sup>, הרי נמצא שהקבלת עול מלכות שמים אינה בתכלית השלימות, ולגבי מדריגתו הוא כמו פריקת עול. ולכן גם בצ\"ג צ\"ל התשובה דסור מרע.\n<b>וזהו</b> שובה ישראל עד הוי' אלקיך כי כשלת בעוניך, שהתשובה על הכשלון בעון שבדרגת ישראל (יש מי שאוהב) הוא ע\"י הגילוי דהוי' דוקא. דלגבי שם אלקים, מכיון שההתהוות משם אלקים היא בדרך התלבשות (בראשית ברא אלקים<sup data-n=\"1101\">55</sup>), הנבראים שמתהווים ממנו הם תופסים מקום, והביטול שלהם הוא רק ביטול היש, משא\"כ לגבי שם הוי', שההתהוות ממנו היא באופן דבדרך ממילא (יהללו את שם הוי' כי הוא צוה ונבראו<sup data-n=\"1102\">56</sup>), הנבראים אינם תופסים מקום, ביטול במציאות<sup data-n=\"1103\">57</sup>. וזהו שהתשובה על כשלת בעוניך שבדרגת ישראל, יש מי שאוהב, היא שהוי' יהי' אלקיך, דע\"י שמאיר בו הגילוי דהוי', ועד שזה (הוי') נעשה אלקיך כחך וחיותך, הוא בא לביטול במציאות.\nז) <b>והנה</b> מבואר בלקו\"ת<sup data-n=\"1104\">58</sup> דפירוש שובה ישראל עד הוי' אלקיך הוא שהתשובה צריכה להיות עד שהוי' יהי' רק בחי' אלקים וצמצום לגבי עצמות אוא\"ס שלמעלה מהוי'. וע\"ד הפירוש בהוי' הוא האלקים<sup data-n=\"1105\">59</sup> שאומרים בנעילת יום הכפורים, שז\"א (הוי') בעלותו לעתיקא כאלקים יחשב<sup data-n=\"1106\">60</sup>. ויובן זה ע\"פ הידוע<sup data-n=\"1107\">61</sup> שגם לגבי שם הוי', מכיון שהוא מקור לההתהוות, דהוי' הוא לשון מהוה<sup data-n=\"1108\">62</sup> (אלא שההתהוות היא בדרך ממילא), בהכרח שיש איזה תפיסת מקום להנבראים, ואמיתית הביטול הוא דוקא לגבי עצמות אוא\"ס שלמעלה מהוי' שאינו בגדר מקור לעולמות. וזהו שהתשובה על כשלת בעוניך (יש מי שאוהב) היא עד הוי' אלקיך (כהפירוש בלקו\"ת) שהוי' הוא אלקים וצמצום לגבי עצמות אוא\"ס, שע\"י הגילוי דעצמות אוא\"ס [עתיקא, שנבדל ונעתק ומובדל ממציאות העולמות<sup data-n=\"1109\">63</sup>], מגיעים לתכלית הביטול.\n<b>ויש</b> להוסיף, שענין הישות (דיש מי שאוהב) כפשוטו נתקן כבר ע\"י עבודת התשובה דחודש אלול, ובכתה את אבי' ואת אמה ירח ימים<sup data-n=\"1110\">64</sup> דקאי על חודשאלול (כדאיתא בכתבי האריז\"ל<sup data-n=\"1111\">65</sup>), חודש הרחמים, שאז המלך הוא בשדה<sup data-n=\"1112\">66</sup>, ובפרט בהימים שאחר ח\"י אלול שמכניס חיות בכל הענינים דחודש אלול<sup data-n=\"1113\">67</sup>, ובפרט בימי הסליחות שאומרים לך<sup data-n=\"1114\">68</sup> הוי' הצדקה ולנו בושת הפנים, ביטול דיראת בושת שהיא יראת הרוממות בדרגא הכי עליונה<sup data-n=\"1115\">69</sup>, ובפרט בערב ראש השנה שענינו הוא (כשמו ערב ראש השנה) הכנה לראש השנה, ובפרט בראש השנה גופא שאז היא העבודה דקבלת עול מלכות שמים, שתמליכוני עליכם<sup data-n=\"1116\">70</sup>. והתשובה דשבת תשובה היא על הישות כמו שהוא בתכלית הדקות. ולכן מבאר בלקו\"ת דפירוש שובה ישראל עד הוי' אלקיך [שאומרים בשבת תשובה] הוא שהוי' יהי' רק אלקים וצמצום לגבי עצמות אוא\"ס, כי בכדי לשלול הישות בתכלית הדקות הוא דוקא ע\"י גילוי עצמות אוא\"ס שלמעלה מהוי'.\nח) <b>ולאחרי</b><sup data-n=\"1117\">71</sup> אומרו שובה ישראל גו' כי כשלת בעוניך, שהיא התשובה דסור מרע [כמו שהיא בדרגת ישראל], מוסיף קחו עמכם דברים ושובו אל הוי', אמרו אליו כל תשא עון, שב' תשובות אלו הם התשובה דועשה טוב והתשובה דבקש שלום. ויובן זה בהקדים המבואר בלקו\"ת<sup data-n=\"1118\">72</sup> שג' התשובות דסו\"מ דוע\"ט ודבקש שלום הן בג' הבחינות נר\"נ. התשובה דסור מרע (שהיא על חטא ועון) היא בבחי' נפש. כי ענין החטא ועון שייך רק בבחי' נפש כמ\"ש<sup data-n=\"1119\">73</sup> הנפש החוטאת<sup data-n=\"1120\">74</sup>. וגם <i>התשובה</i> (דסור מרע) היא בבחי' נפש, כי התשובה דסו\"מ היא שמקבל עליו קבלת עול מלכות שמים ועול מצוות [שלא למרוד במלכותו ית' ולא לעבור על מצות המלך ח\"ו<sup data-n=\"1121\">75</sup>], וענין הקב\"ע הוא בבחי' נפש. התשובה דועשה טוב, שהיא על העדר התעוררות אהבה ויראה [דההמשכה שע\"י קיום המצוות (ועשה טוב) היא ע\"י אהבה ויראה שהם הגדפין שעל ידם פרחא לעילא<sup data-n=\"1122\">76</sup>, וגם השלימות דקיום המצוות גופא היא ע\"י האהבה דוקא<sup data-n=\"1123\">77</sup>], היא בבחי' רוח, דמדות שבלב (אהבה ויראה) הם בחי' רוח. והתשובה דבקש שלום, שהיא על העדר עסק התורה בהבנה והשגה, ובפרטיות יותר –התשובה על העדר בהשגת אלקות, ובעיקר על זה שהענין האלקי אינו נרגש במוחו (דגם כשמתבונן בענין אלקי אין הענין נרגש במוחו), היא בבחי' נשמה, נשמת שדי תבינם<sup data-n=\"1124\">78</sup>, וזהו שבהתשובה דועשה טוב כתיב קחו עמכם דברים ובתשובה דבקש שלום כתיב אמרו אליו, כי דיבור (דברים) שייך למדות (דדיבור הוא ההבל היוצא מהלב<sup data-n=\"1125\">79</sup>), ולכן הוא בחי' רוח, רוח ממללא<sup data-n=\"1126\">80</sup>, ואמירה שהיא בלב<sup data-n=\"1127\">81</sup>, מחשבה, היא<sup data-n=\"1128\">82</sup> בחי' נשמה. וזהו גם מ\"ש אמרו אליו כל, כל מלשון התכללות, כי (בקש) שלום הו\"ע ההתכללות.\nט) <b>ומה</b> שאומר בתשובה זו (דבחי' נשמה) תשא עון, יובן על פי מ\"ש בזהר<sup data-n=\"1129\">83</sup> (שאומרים במענה לשון) נפשא דילהון קדישא רוחא דילהון קדישא נשמתא דילהון קדש קדשים, דזה שנשמה נקראת קדש קדשים הוא לפי שכוללת בתוכה גם קדשים דנפש ורוח. ומכיון שנפש ורוח כמו שכלולים בנשמה הם במדריגה נעלית יותר [וע\"ד דצ\"ח שבאדם שהם למעלה מדצ\"ח, וכמו כן הוא בנוגע בי\"ע שבאצילות, ועד\"ז הוא גם בע\"ס דאצילות כמו שהם גנוזות בלמעלה מאצילות], לכן ע\"י התשובה דנשמה נעשה עילוי גם בנפש ורוח, ולא רק כמו שהם כלולים בנשמה אלא גם כמו שהם במקומם. ולכן אומר בהתשובה דבחי' נשמה תשא עון, כי ע\"י תשובה זו, נעשה עילוי גם בהתשובה דסור מרע.\n<b>ומזה</b> מובן, שבכדי שהעבודה דסור מרע (בחי' נפש) ודועשה טוב (בחי' רוח) תהי' כדבעי, הוא ע\"י עסק התורה (בחי' נשמה), ובפרט ע\"י העסק בפנימיות התורה, ברזין דאורייתא וברזין דרזין, דבחי' פנימיות התורה הנק' סתים דאורייתא הוא המקשר ומחבר בחי' סתים דישראל לבחי' סתים דקוב\"ה<sup data-n=\"1130\">84</sup>. והגם דהמשכת העצמות שבתורה הוא בכל חלקי התורה, גם בנגלה דתורה, וגם בקריאת אותיות התורה (אפילו כשלא ידע מאי קאמר) כמבואר בהמשך תער\"ב<sup data-n=\"1131\">85</sup>, הרי מבואר שם שגילוי העצמות הוא דוקא בפנימיות התורה [כי פנימיות אבא פנימיות עתיק<sup data-n=\"1132\">86</sup>, ולכן הגילוי דפנימיות עתיק הוא דוקא בפנימיות אבא]. ובפרט בפנימיות התורה כמו שנתגלתה בתורת החסידות ע\"י הבעש\"ט, ועאכו\"כ כמו שנתגלתה ע\"י אדמו\"ר הזקןבתורת חסידות חב\"ד, באופן דיתפרנסון<sup data-n=\"1133\">87</sup>. וע\"י העסק בתורה, ובפרט בפנימיות התורה, נעשה עילוי גם בהעבודה דסור מרע ודועשה טוב.\nי) <b>והנה</b> כמו שהתשובה דשובה גו' כי כשלת בעוניך אינה על עוונות כפשוטם ח\"ו, שהרי כל ישראל בחזקת כשרות הם<sup data-n=\"1134\">88</sup>, ובפרט לאחרי התשובה דחודש אלול ודימי הסליחות, ובפרט לאחרי ראש השנה שכל ישראל זוכין בדין, ועד שגם בערב ראש השנה יודעים כבר בבירור שיזכו בדין<sup data-n=\"1135\">89</sup>, כי ועמך כולם צדיקים<sup data-n=\"1136\">90</sup>, ובפרט לאחרי תק\"ש שאז נעשה ענין העשירות [וכידוע דזה שארז\"ל<sup data-n=\"1137\">91</sup> מתעשרת בסופה הוא מיד לאחרי תק\"ש], והתשובה דשבת תשובה (לאחרי ראש השנה) היא רק על הישות דיש מי שאוהב (ובזה גופא – בתכלית הדקות), כנ\"ל (סעיף ז), עד\"ז הוא גם בהתשובה דועשה טוב ודבקש שלום, דהגם שעשו גם ענינים אלו גם מקודם, התשובה דשבת תשובה היא שקיום המצוות תהי' בהידור עוד יותר, ועד\"ז בעסק התורה ובפרט בפנימיות התורה כמו שנתגלתה בתורת החסידות ובפרט בתורת חסידות חב\"ד, כולל גם הענין דיפוצו מעינותיך חוצה<sup data-n=\"1138\">92</sup>, ועד שיהי' מלאה הארץ דעה את הוי' כמים לים מכסים<sup data-n=\"1139\">93</sup>, שתהי' שנת תורה שנת תשובה ושנת תפלה, וכן גם כל הברכות שבכל האותיות, שנת אורה שנת ברכה שנת גאולה וכו', ובפרט – הברכה העיקרית, גאולה שלימה ע\"י משיח צדקנו בקרוב ממש.\n**********",[["1046","*","יצא לאור ב<b>קונטרס שבת תשובה-ו' תשרי – תשמ\"ט</b>, \"לקראת שבת תשובה, ו' תשרי, יום היאָרצייט של הרבנית הצדקנית מרת חנה תנצב\"ה (אמו של – יבלח\"ט – כ\"ק אדמו\"ר שליט\"א), נסתלקה שבת תשובה בעת עלות המנחה שנת תשכ\"ה . . <i>עש\"ק וילך</i>,<i> תשמ\"ט</i>\"."],["1047","1","הושע יד, ב. – התחלת וראשית ההפטרה דשבת שובה."],["1048","2","לקו\"ת דרושים לשבת שובה ד\"ה שובה ישראל הא' (סה, א)."],["1049","3","כמו שמדייק בלקו\"ת שם רד\"ה שובה הב' (סו, ריש ע\"ב). ועוד."],["1050","4","כ\"ה הלשון ברד\"ה שובה ישראל ה'תש\"ד (סה\"מ ה'תש\"ד ע' 15). וכ\"ה גם ברד\"ה זה תרח\"צ (סה\"מ תרח\"צ ע' לד)."],["1051","5","וישלח לב, כט."],["1052","6","ראה פרש\"י עה\"פ שם: בשררה; שם לה, י: לשון שר ונגיד."],["1053","7","ראה לקו\"ת שם ד\"ה שובה הא' (סד, ג), \"אנשים הם הכחות המתפשטות משם אלקים\"."],["1054","8","ראה גם ד\"ה תקעו תרח\"צ ס\"ב (סה\"מ תרח\"צ ריש ע' יג), ובהנסמן שם בהערה 15."],["1055","9","קהלת יב, ז. וראה לקו\"ת ריש פרשתנו (האזינו). לקמן סעיף ד."],["1056","10","לקו\"ת ד\"ה שובה הב' (סו, ג)."],["1057","11","ע\"פ מ\"ש בפנים יומתק שלאחרי אומרו שובה ישראל מוסיף כי כשלת בעוניך, אף שלכאורה מובן מעצמו ד\"שובה\" הוא על חטא ועון (וכמו שמדייק בד\"ה זה תרצ\"ה ותרח\"צ בתחלתו) – כי מכיון שמדבר כאן בדרגת \"ישראל\", הי' אפ\"ל שהתשובה שלהם היא רק התשובה ד\"והרוח תשוב גו'\" – ולכן מוסיף <i>ומחדש</i> שגם ב\"ישראל\" ישנו הענין ד\"כשלת בעוניך\", וצריכים לתשובה כפשוטה (כ\"מ בסה\"מ ה'תש\"ד שם)."],["1058","12","הושע שם, ג."],["1059","13","כמו שמדייק ברד\"ה זה תרע\"ג (המשך תער\"ב ח\"א ע' קמב)."],["1060","14","ראה ספר המצוות להצ\"צ מצות וידוי ותשובה בתחלתה (דרמ\"צ לח, א) \"שעיקר מצות התשובה מן התורה היא עזיבת החטא והוידוי <i>ובקשת מחילה</i>\". וצ\"ע, דברמב\"ם הל' תשובה לא נזכר בקשת מחילה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171194\" data-slug=\"likkutei-sichot\" data-id=\"1300171194\">לקו\"ש חי\"ז ע' 194</a>. <i>ואכ\"מ</i>."],["1061","15","בלק ד\"ה מה טובו (עג, ב ואילך)."],["1062","16","סנהדרין צט, ב."],["1063","17","רמב\"ם סוף הל' חנוכה."],["1064","18","כדלקמן סעיף ז, ע\"פ סד\"ה שובה תרע\"ג הנ\"ל (המשך תער\"ב שם ע' קמט)."],["1065","19","בשיחת ליל ש\"פ וילך שבת תשובה ה'תש\"ה ס\"ה ואילך (ספר השיחות ה'תש\"ה ע' 14 ואילך)."],["1066","20","ד\"ה שובה הנ\"ל שם. ומה שנזכר ענין העון בתשובה השלישית (אמרו גו' תשא עון) – אף שהיא למעלה גם מהתשובה דועשה טוב – ראה לקמן סעיף ט."],["1067","21","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380610\" data-slug=\"likkutei-torah\" data-id=\"4001380610\">לקו\"ת בלק שם עג, סע\"א</a> ואילך."],["1068","22","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380613\" data-slug=\"likkutei-torah\" data-id=\"4001380613\">לקו\"ת שם עג, ד</a>."],["1069","23","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380614\" data-slug=\"likkutei-torah\" data-id=\"4001380614\">לקו\"ת שם עד, א</a>. בלקו\"ת שם, דעל תשובה זו (ליכלל בעצמות אוא\"ס) כתיב (מלאכי ג, ז) \"שובו אלי – אלי ממש\". ועפ\"ז יובן מה שבתשובה זו כתיב \"אמרו <i>אליו</i>\" (ד\"אליו\" הוא כמו \"אלי\"). ולהעיר ממארז\"ל (ספרי הובא בפרדס שער לב (שער הכוונה) פ\"ב. אלימה רבתי מעין א תמר א. וראה בחיי עה\"פ ואתחנן ד, ז. עקב יא, ג) אליו ולא למדותיו, דלפירוש אדמו\"ר הזקן (הובא באגרות-קודש אדמו\"ר מוהריי\"צ ח\"ג ע' קמד-ה. \"היום יום\" יא תשרי) קאי על עצמות א\"ס."],["1070","24","ישעי' נט, ב. וראה אגרת התשובה פ\"ה."],["1071","25","ראה עמה\"מ שער שעשועי המלך רפ\"א. שעהיוה\"א פ\"ד (עט, א)."],["1072","26","ראה לקו\"ת שם (עג, ד) שהעבודה ד\"ועשה טוב\" היא \"שמייגע את עצמו בועשה טוב להלחם עם הטבע\". ויש לומר, שלכן גם ההמשכה מלמעלה שעי\"ז היא למעלה מהטבע (דטבע הטוב להטיב) דלמעלה."],["1073","27","ראה גם ד\"ה זה היום דיום ב' דר\"ה שנה זו (ה'תשמ\"א) ס\"ג (לעיל ע' לא)."],["1074","28","רות ד, יח."],["1075","29","ב\"ר פי\"ב, ו. שמו\"ר פ\"ל, ג."],["1076","30","בראשית ב, ד."],["1077","31","ראה ב\"ר פי\"ד, ז. פי\"ג, ג."],["1078","32","מדרשים שבהערה 29."],["1079","33","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["1080","34","ראה מיכה ב, יג. ב\"ר פפ\"ה, יד (ובפרש\"י שם). אגדת בראשית ס\"פ סג."],["1081","35","<a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a>. לקו\"ת שם עד, א."],["1082","36","לקו\"ת שם עג, סע\"ג ואילך."],["1083","37","לקו\"ת שם עד, א."],["1084","38","וכמובן גם מהלשון \"כשלת בעוניך\" – ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, א</a>; <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380923\" data-slug=\"likkutei-torah\" data-id=\"4001380923\">נצבים נא, א</a>, דחטא הוא לשון חסרון משא\"כ עון."],["1085","39","פ\"א (צא, רע\"א). וראה ס' \"שיעורים בספר התניא\" לאגרת התשובה שם (ע' 1054 ואילך)."],["1086","40","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381011\" data-slug=\"likkutei-torah\" data-id=\"4001381011\">לקו\"ת</a> פרשתנו (האזינו) עב, א. דרושים לשמע\"צ פה, ריש ע\"ב."],["1087","41","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380190\" data-slug=\"likkutei-torah\" data-id=\"4001380190\">לקו\"ת אחרי כו, ג</a>."],["1088","42","ראה בארוכה ד\"ה ואברהם זקן תרס\"ו (המשך תרס\"ו ע' פ ואילך). ובכ\"מ. ד\"ה זה היום דיום ב' דר\"ה שנה זו (ה'תשמ\"א) ס\"ה (לעיל ע' לג)."],["1089","43","ראה ב\"ב נג, א. וש\"נ. רמב\"ם הל' מכירה פכ\"ה ה\"ד. הל' זכי' ומתנה פי\"א הכ\"ב."],["1090","44","לקו\"ת פרשתנו שם, ב."],["1091","45","לקו\"ת פרשתנו שם, רע\"א."],["1092","46","תהלים ה, ה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380322\" data-slug=\"likkutei-torah\" data-id=\"4001380322\">לקו\"ת במדבר ג, ג</a>. מאמרי אדהאמ\"צ דברים ח\"ד ע' א'תצג. וש\"נ."],["1093","47","לקו\"ת פרשתנו שם, א. וראה אוה\"ת פרשתנו ע' א'תרלח."],["1094","48","בלק עג, ד. עד, ב. וראה גם ד\"ה שובה תרע\"ג פע\"ח (המשך תער\"ב ח\"א ע' קמז). וראה גם ד\"ה זה תרח\"צ (סה\"מ תרח\"צ ע' לד)."],["1095","49","ראה שבת קיד, א: של בנאין (ת\"ח) מצד אחד. ובד\"ה שובה תרע\"ג שם: שהכתם על בגד חשוב גרוע יותר."],["1096","50","ראה חגיגה ה, ב."],["1097","51","ראה סהמ\"צ להצ\"צ ח, א. וראה בארוכה לקו\"ש ח\"ד ע' 1050 ובהערות שם."],["1098","52","ראה סה\"מ תרנ\"ט ע' סד: שלפי עוצם גדולתו ורוממותו גם העבודה האמיתית . . לחטא יחשב. ועד\"ז בסה\"מ תרנ\"א ע' עה ואילך. שם ע' ריב. שם ע' ריד ואילך."],["1099","53","ראה סה\"מ תרס\"ג ע' נו."],["1100","54","פל\"ה (מד, סע\"א ואילך)."],["1101","55","בראשית א, א."],["1102","56","תהלים קמח, ה. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370432\" data-slug=\"torah-or\" data-id=\"3901370432\">תו\"א מג\"א צו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380798\" data-slug=\"likkutei-torah\" data-id=\"4001380798\">לקו\"ת ראה כ, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381236\" data-slug=\"likkutei-torah\" data-id=\"4001381236\">שם כו, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">שה\"ש יד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381295\" data-slug=\"likkutei-torah\" data-id=\"4001381295\">שם מא, ד</a>. <i>ובכ\"מ</i>."],["1103","57","המשך תרס\"ו ע' רכד. סה\"מ תרע\"ח ס\"ע שפ ואילך."],["1104","58","דרושים לשבת שובה סה, א. שם סו, א."],["1105","59","מלכים-א יח, לט."],["1106","60","לקו\"ת שם (ביאור לד\"ה שובה הא') ס\"ה, ריש ע\"ד (ממ\"ח סוף מס' יומא)."],["1107","61","ראה המשך תרס\"ו שבהערה 57."],["1108","62","שעהיוה\"א רפ\"ד. וראה גם זח\"ג רנז, סע\"ב (ברע\"מ). פרדס שער א (שער עשר ולא תשע) פ\"ט."],["1109","63","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380965\" data-slug=\"likkutei-torah\" data-id=\"4001380965\">לקו\"ת</a> דרושים לר\"ה סא, ג. סהמ\"צ להצ\"צ מצות וידוי ותשובה (דרמ\"צ לט, א)."],["1110","64","תצא כא, יג."],["1111","65","ל\"ת להאריז\"ל עה\"פ. וראה גם ז\"ח תצא עה\"פ (נח, סע\"ד). ובאוה\"ת נ\"ך כרך ב ס\"ע א'נ מציין: וע' עוד [לקו\"ת] סד\"ה כי תצא דרוש השני בענין ובכתה את אבי' ואת אמה ירח ימים דקאי על [חודש] אלול כו'. – עיי\"ש בלקו\"ת. וצע\"ק."],["1112","66","לקו\"ת ראה ד\"ה אני לדודי הא' ס\"א (לב, ריש ע\"ב)."],["1113","67","ראה שיחת ח\"י אלול ה'תש\"ה (לקו\"ד כרך ג ע' 946. ספר השיחות ה'תש\"ה ע' 122). – נת' ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191263\" data-slug=\"likkutei-sichot\" data-id=\"1300191263\">לקו\"ש חי\"ט</a> שיחה לח\"י אלול (ע' 250 ואילך). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291176\" data-slug=\"likkutei-sichot\" data-id=\"1300291176\">לקו\"ש חכ\"ט</a> שיחה לח\"י אלול (ע' 161 ואילך). וראה גם לקו\"ד כרך א לד, א."],["1114","68","דניאל ט, ז."],["1115","69","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310048\" data-slug=\"tanya\" data-id=\"3401310048\">תניא</a> פמ\"ג. סידור (עם דא\"ח) הערה לתיקון חצות (קנא, סע\"ג ואילך)."],["1116","70","ר\"ה טז, א. לד, ב."],["1117","71","בכל הבא לקמן ראה ד\"ה שובה תרע\"ג (המשך תער\"ב ח\"א ע' קמו ואילך)."],["1118","72","בלק עד, ב."],["1119","73","יחזקאל יח, ד."],["1120","74","כ\"ה בד\"ה שובה שם. וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380091\" data-slug=\"likkutei-torah\" data-id=\"4001380091\">לקו\"ת שם</a> מובא הפסוק (ויקרא ד, ב. ועוד) נפש כי תחטא."],["1121","75","אגה\"ת פ\"א (צא, רע\"א). וראה בארוכה ס' \"שיעורים בס' התניא\" שם ע' 1069 ואילך."],["1122","76","<a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>), <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">מתקו\"ז ת\"י (כה, ב</a>)."],["1123","77","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a> \"כי המקיימן באמת הוא האוהב כו'\". וראה קונטרס העבודה פ\"ב (ע' 15)."],["1124","78","איוב לב, ח."],["1125","79","דענין זה [שקול הדיבור יוצא מהבל הלב] ברוחניות הוא, שהדיבור נמשך מהמדות שבלב – ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380946\" data-slug=\"likkutei-torah\" data-id=\"4001380946\">לקו\"ת ר\"ה נו, ד</a>. ובכ\"מ."],["1126","80","תרגום אונקלוס עה\"פ בראשית ב, ז."],["1127","81","זח\"א רלד, ב. לקו\"ת חוקת נז, ד. <i>וש\"נ</i>."],["1128","82","ראה סה\"מ ה'תש\"ב ע' 103 ובכ\"מ, שהדיבור הוא (בעיקר) לבוש להמדות (רוח) והמחשבה לשכל (נשמה)."],["1129","83","ח\"ג ע, ב."],["1130","84","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380096\" data-slug=\"likkutei-torah\" data-id=\"4001380096\">לקו\"ת ויקרא ה, ג</a>. ע\"פ זח\"ג עג, א."],["1131","85","ח\"ב פשס\"ד (ע' תשמו ואילך)."],["1132","86","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380918\" data-slug=\"likkutei-torah\" data-id=\"4001380918\">לקו\"ת נצבים מט, ד</a>. וש\"נ. וראה בהוספות ל\"הערות וציונים\" ללקו\"ת שם (בהוצאת קה\"ת ה'תשד\"מ ואילך – קכט, א)."],["1133","87","ל' התקו\"ז ת\"ו בסופו. וראה הקדמת מק\"מ לזהר; כס\"מ לתקו\"ז שם – נעתקו ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241136\" data-slug=\"likkutei-sichot\" data-id=\"1300241136\">לקו\"ש חכ\"ד ע' 136</a> הערה 35."],["1134","88","רמב\"ם הל' קדה\"ח פ\"ב ה\"ב."],["1135","89","טור או\"ח הל' ר\"ה סתקפ\"א, מירושלמי ר\"ה פ\"א ה\"ג."],["1136","90","ישעי' ס, כא."],["1137","91","ר\"ה טז, ב."],["1138","92","ראה אגה\"ק דהבעש\"ט, נדפסה גם בכתר שם טוב (הוצאת קה\"ת) בתחלתו."],["1139","93","ישעי' יא, ט."]]],[1500360017,"<h3>בס\"ד. ש\"פ האזינו, שבת שובה ה'תשמ\"ח<sup data-n=\"1140\">*</sup></h3><h3>– התוועדות ב' – המשך להתוועדות יום ב' דראש השנה –</h3>\n<b>שיר</b> המעלות ממעמקים קראתיך הוי'<sup data-n=\"1141\">1</sup>, הנה מזמור זה נתקן לאומרו בכל יום מעשרת ימי תשובה, מתחיל מראש השנה<sup data-n=\"1142\">2</sup> (שהוא היום הראשון דעשי\"ת), וכמה דרושי ראש השנה מתחילים בפסוק זה. ומובא ע\"ז בהדרושים<sup data-n=\"1143\">3</sup>, דבפירוש ממעמקים יש שתי דיעות בזהר<sup data-n=\"1144\">4</sup> ר' יצחק ור' אבא, דר\"י מפרש ממעמקים של האדם, שהתפלה הנ\"ל היא ממעמקי נפשו של האדם<sup data-n=\"1145\">5</sup>, ממעמקי הנפש של דוד המלך<sup data-n=\"1145\">5</sup> וכן של כאו\"א מישראל האומר מזמור זה, ור\"א מפרש ממעמקים של למעלה אתר גנוז הוא לעילא כו'. וממשיך בהמאמרים<sup data-n=\"1146\">6</sup>, והנה פירוש ממעמקים הוא ב' עומקים, דזהו לפי שתי הדיעות הנ\"ל, וע\"פ זה מבאר דלדעת ר\"י הנה העומק לפנים מעומק הוא עומקא דליבא<sup data-n=\"1145\">5</sup> ולדעת ר\"א הרי זה עמיקא דעמיקתא בהמדריגות שלמעלה. וממשיך דעיקר הפירוש הוא דקאי על המדריגות שלמעלה, דהיינו שע\"י קראתיך מגיעים בבחי' עומק לפנים מעומק, עד שעולים לבחי' עומק כזה שהוא למעלה מהתחלקות של דרגות, ומשם קראתיך – נמשך – הוי'. והקשר דב' הפירושים (דמר אמר חדא ומר אמר חדא ולא פליגי) הוא, כי היכולת להמשיך מבחי' עומק זה שהוא למעלה מכל גדר התחלקות הוא ע\"י בחי' עומקא דליבא, שבא ע\"י עבודת התשובה, כמבואר בהמאמרים, וכמובן בפשטות שזהו תוכן מזמור זה (שיר המעלות ממעמקים), תפלת התשובה.\n<b>ולהבין</b> זה, איך על ידי עבודת התשובה ממשיכים מבחינת העומק לפנים מעומק שלמעלה, יש להקדים תחילה מה שמבואר בהמשך ראש השנה תרח\"ץ<sup data-n=\"1147\">7</sup> (לפני חמישים שנה), שיש שתי מדריגות בתשובה, ענין התשובה ומהות התשובה. דענין התשובה היא התשובה על ענינים פרטיים או אפילו על ענינים כלליים, אבל אף שהתשובה אינה על חטא ועון<sup data-n=\"1148\">8</sup> ופשע מ\"מ ענינה הוא שעולה בעבודתו בטובעצמו<sup data-n=\"1149\">9</sup>, שהולך ומוסיף בשלימות עבודתו עד שעבודה פרטית זו היא כדבעי וכדרוש, ועד שע\"י שמשלים כל הענינים הפרטיים הרי כללות עבודתו היא כדרוש. אמנם מהות התשובה הוא שממקום שהוא עומד בו במעמדו ומצבו הרוחני הוא עולה (ער שטעלט זיך איבער) למקום נעלה יותר, שהוא מעמד ומצב חדש ועד שאינו בערך כלל למצבו לפנ\"ז. והיינו שעולה למצב עליון שלא בערך כלל עד שאין לומר עליו לשון וגדר עליון ותחתון, דלשון עליון מורה שישנו תחתון והוא העליון בערכו, משא\"כ מהות התשובה היא בדרגא כזו שאינה בגדר וערך דעליון ותחתון, שאינו שייך כלל להמצב שלפנ\"ז (למעליותא)<sup data-n=\"1150\">10</sup>, עד שנעשה מציאות חדשה שנעשית מאין ואפס ממש. וע\"י שעומד במעמד ומצב שאינו בערך כלל, ה\"ז פועל על כל פרטי העבודות וכל הפרטי פרטים, שהכל יהי' נתקן כדבעי. היינו שמכיון שהוא במעמד ומצב חדש באופן שכל המעשים שעושה הם טובים, וכלשון רז\"ל<sup data-n=\"1151\">11</sup> ודיוק הסדר בזה: תשובה ומעשים טובים, שע\"י התשובה תהי' תכלית השלימות בהמעשים<sup data-n=\"1152\">12</sup> ותכלית השלימות בהטוב ותכלית השלימות בישראל עושי המעשים טובים.\n<b>וזהו</b><sup data-n=\"1153\">13</sup> שיר המעלות ממעמקים קראתיך הוי', דע\"י תשובה מעומקא דליבא, עומק לפנים מעומק, שהיא מהות התשובה, עי\"ז קוראים וממשיכים מלמעלה מבחי' עמיקא דעמיקתא, ועד לעומק כזה שאינו בגדר דרגות כלל. ועי\"ז מתקיימים בפשטות כל התפלות שבמזמור זה, שנמשך בחי' העומק העליון שלמעלה, בחי' העומק שלמעלה ממעמקים לשון רבים, עד שהוא למעלה מכל גדר עומק, ויורד עד למטה מטה ובגלוי ממש, ממש גם בזמן, תיכף ומיד, ויהי' ביטול כל ההגבלות וגילוי א\"ס האמיתי למטה, ויתירה מזו, שהרי לא שייך בו ית' גדר מעלה ומטה אלא הכל אחד, וזה מיוסד ונעשה ע\"י שהעומק דישראל והעומק שלמעלה נעשים דבר אחד, ממעמקים קראתיך<sup data-n=\"1154\">14</sup> שיהי' ישראל וקוב\"ה כולא חד<sup data-n=\"1155\">15</sup>.\n**********",[["1140","*","יצא לאור בשעתו, \"<i>וא\"ו תשרי שנת תשמ\"ח</i>\"."],["1141","1","תהלים קל, א."],["1142","2","שער הכוונות דרושי ראש השנה (לפני דרוש א') קרוב לתחלתו. פע\"ח שער תפלות ר\"ה פ\"ז. סידור אריז\"ל במקומו. מג\"א או\"ח סנ\"ד סק\"ב בשם כתבים. עט\"ז או\"ח ר\"ס תקפב. סידור אדמו\"ר הזקן במקומו. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380968\" data-slug=\"likkutei-torah\" data-id=\"4001380968\">לקו\"ת</a> דרושים לר\"ה רד\"ה שיר המעלות ממעמקים (סב, ב)."],["1143","3","ד\"ה שיר המעלות תש\"ג (סה\"מ תש\"ג ע' 18 ואילך). וראה גם ד\"ה הנ\"ל תשל\"ט."],["1144","4","ח\"ג סט, סע\"ב ואילך."],["1145","5","ראה זח\"ב סג, ריש ע\"ב. ריש וסוף ד\"ה שיר המעלות ממעמקים תרס\"ח."],["1146","6","סה\"מ תש\"ג שם ע' 19."],["1147","7","ד\"ה: תקעו פ\"ב. שובה פ\"א. פ\"ו. בורא ניב שפתים דש\"פ האזינו פ\"א. וראה גם ד\"ה תקעו דש\"פ נצבים תרצ\"ז פ\"ד."],["1148","8","ראה הנסמן בהערה הבאה. ד\"ה כבוד מלכותך תרח\"ץ פ\"ב. וראה גם ד\"ה שובה שנאמר בהתוועדות א."],["1149","9","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380614\" data-slug=\"likkutei-torah\" data-id=\"4001380614\">לקו\"ת בלק עד, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380962\" data-slug=\"likkutei-torah\" data-id=\"4001380962\">דרושים לר\"ה ס, ד</a>. ר\"פ האזינו."],["1150","10","כידוע בענין \"כל ימיו בתשובה\" (שבת קנג, א) שהוא אפילו אם \"כבר עשה תשובה נכונה\" (תניא פכ\"ט) – ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251015\" data-slug=\"likkutei-sichot\" data-id=\"1300251015\">לקו\"ש חכ\"ה ע' 15</a> ואילך. וש\"נ."],["1151","11","אבות פ\"ד מי\"ז."],["1152","12","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת (מטות פב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381199\" data-slug=\"likkutei-torah\" data-id=\"4001381199\">שמע\"צ פה, א</a>. שה\"ש יז, ג) דע\"י קדימת התשובה המעשים נעשים טובים ומאירים."],["1153","13","ראה ד\"ה תקעו תרח\"ץ (הנ\"ל) פ\"ב-ג."],["1154","14","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380972\" data-slug=\"likkutei-torah\" data-id=\"4001380972\">לקו\"ת</a> דרושים לר\"ה סד\"ה שיר המעלות ממעמקים (סג, ב): וזהו קראתיך ה' כאדם הקורא לחבירו שיבוא אצלו כך הוא קורא להשי\"ת שיתגלה אלקותו בעולם התחתון שיהי' נגלה כבוד ה' וראו כל בשר יחדו."],["1155","15","ראה זח\"ג עג, א. להעיר מתניא בהקדמת המלקט (ג, ב)."]]],[1500360018,"(הנחה)\n<b>כנשר</b> יעיר קנו גו' ישאהו על אברתו<sup data-n=\"1156\">1</sup>, וידוע הפירוש של בעל ההילולא<sup data-n=\"1157\">2</sup>, שנשר הוא בחינת רחמים, וכנשר יעיר גו' הוא בחינת רחמים רבים. ומ\"ש ישאהו על אברתו, אף שאין לו גוף ואין לו דמות הגוף<sup data-n=\"1158\">3</sup>, הוא כי זאת התורה אדם<sup data-n=\"1159\">4</sup>, והו\"ע רמ\"ח אברים דמלכא הנעשים ע\"י רמ\"ח פקודין<sup data-n=\"1160\">5</sup>, שע\"י קיום המצוות מעלה אני עליכם כאילו עשאוני<sup data-n=\"1161\">6</sup>. וזהו\"ע ישאהו על אברתו, שמצד הרחמים רבים דבחי' נשר הנה ע\"י התשובה נעשה העילוי למעלה מבחינת רמ\"ח אברים דמלכא שע\"י המצוות (ישאהו <i>על</i> אברתו). וזה מתאים עם המבואר בקבלה<sup data-n=\"1162\">7</sup> דחיות המרכבה בהם מאיר מי\"ג תיקוני דיקנא, ולמעלה יותר נשר הוא בחי' עתיק שנעתק ונבדל מכל סדר ההשתלשלות, שלכן מצד בחי' זו אין שום מדידות והגבלות, גם לא המדידות שבמדריגות הכי עליונות שבסדר השתלשלות, עד גם להמדידות דתורה ומצוות. ולכן מצד בחינה זו ישאהו על אברתו. וי\"ל בדא\"פ שזהו ג\"כ הטעם מה שקוראין פרשת האזינו בעשי\"ת או תיכף אחרי יום הכפורים, כי אז הוא זמן התשובה, אשר גם מי שחטא, בין חטא כפשוטו ובין חטא מלשון חסרון כמ\"ש<sup data-n=\"1163\">8</sup> אני ובני שלמה חטאים, והיינו שחסר לו בשלימות עבודתו, הנה מצד הגילוי דבחי' נשר, נעשה ע\"י התשובה העלי' למעלה מבחי' אברתו.\n<b>וצריך</b> להבין מ\"ש כנשר דוקא, והרי כל ד' חיות המרכבה, פני ארי' פני שור פני נשר וכו' בי\"ג תיקוני דיקנא, ולמה אומר כנשר דוקא. ואף שבחי' נשר כאן קאי על בחי' עתיק כנ\"ל, שבחינת עתיק הוא נעתק ונבדל מכל סדר ההשתלשלות ומכ\"ש שהוא נעתק ונבדל מעולם הבריאה ששם (בעולם הבריאה) הוא ד' חיות המרכבה, מ\"מ, ממ\"ש כנשר גו', שמדמה את בחי' עתיק ובחי' רחמים רבים שלמעלה לנשר, הרי מובן שמדמה אותו לבחי' נשר שבהשתלשלות, בחי' נשר שבמרכה, ועד לנשר הגשמי שלמטה. וכידוע שנשר הגשמי שלמטה הוא רחמני<sup data-n=\"1164\">9</sup>, היפך העורב<sup data-n=\"1165\">10</sup>,ולנשר זה שלמטה שהוא רחמני הוא מדמה את בחי' הרחמים רבים שלמעלה. והענין הוא, דהנה בד' חיות המרכבה פני ארי' אל הימין ופני שור מהשמאל ופני נשר הוא באמצע. שמזה מובן שפני נשר בענין האבות הן הן המרכבה<sup data-n=\"1166\">11</sup> הוא מדתו של יעקב, קו האמצעי. וכידוע שאברהם הוא בקו הימין, יצחק בקו השמאל ויעקב בקו האמצעי. וזהו ג\"כ המשך הכתובים<sup data-n=\"1167\">12</sup> כי חלק הוי' עמו יעקב חבל נחלתו גו' כנשר יעיר קנו גו', דענין כנשר יעיר קנו בא בהמשך ליעקב גו'. ולכן אומר כנשר דוקא, שהוא מדתו של יעקב, כי יעקב הוא שלימו דאבהן<sup data-n=\"1168\">13</sup>.\n<b>וביאור</b> ענין מעלת קו האמצעי<sup data-n=\"1169\">14</sup>, הנה ידוע<sup data-n=\"1170\">15</sup> שקו האמצעי הוא בריח התיכון המבריח מן הקצה אל הקצה. ויש בזה ב' ענינים. ענין א' הוא שמבריח מן קצה היותר עליון עד קצה היותר תחתון. וכמו בריח התיכון שבמשכן שהי' מבריח מן קצה האחד של המשכן ועד לקצהו השני<sup data-n=\"1171\">16</sup>, שלכן הי' ארכו ע\"ב אמה<sup data-n=\"1172\">17</sup>, דכמו\"כ הוא בקו האמצעי שהוא מבריח מן קצה היותר עליון עד קצה היותר תחתון. ושני ענינים אלו (מה שמבריח מן קצה היותר עליון ונמשך עד לקצה היותר תחתון) תלויים זה בזה, דלהיות אַז ער נעמט פון למעלה מעלה, לכן הוא נמשך עד למטה מטה, וכידוע שעומק רום ועומק תחת שייכים זל\"ז. דכמו\"כ הוא גם בעבודה, כידוע בענין ממעמקים קראתיך הוי', אשר העבודה שמבחינת עומק לפנים מעומק [שזהו ענין מעמקים לשון רבים כדאיתא בזהר<sup data-n=\"1173\">18</sup>] שלמטה, הנה עבודה זו מגעת לבחינת עומק שלמעלה, עד לשלימות המחילה סליחה וכפרה דיום הכפורים שהיא לפני הוי'<sup data-n=\"1174\">19</sup> ועד לבחינת והרוח תשוב אל האלקים אשר נתנה<sup data-n=\"1175\">20</sup>, שבלקו\"ת פ' זו<sup data-n=\"1176\">21</sup>. וענין הב' בקו האמצעי אשר מראשו ועד סופו הוא בשוה בלי שינויים. והסיבה להעדר השינויים שבו הוא להיותו מבריח מן קצה היותר עליון, שמטעם זה הוא נמשך עד למטה מטה כנ\"ל, ובכל מקום הוא בשוה. דקו הימין וקו השמאל, להיות שהם רק הארות כו', הנה הסדר בהארת אור הוא שכל מה שנמשך למטה יותר הוא מתמעט (ומשתנה), משא\"כ קו האמצעי וואָס ער נעמט פון למעלה מעלה כנ\"ל, וכידוע אשר הגם שכל הקוין מגיעים בהכתר הוא רק בבחי' חיצוניות הכתר משא\"כ קו האמצעי מגיע לבחינת פנימיות הכתר<sup data-n=\"1177\">22</sup>, לכן הוא בסופו כמו בראשו, בלי שום שינוי. והנהכמו\"כ הוא גם בציור גוף האדם שנעשה בצלם שלמעלה כמ\"ש<sup data-n=\"1178\">23</sup> נעשה אדם בצלמנו כדמותנו, וכתיב נעשה אדם נעשה לשון רבים כמו שנתבאר במאמרים הקודמים<sup data-n=\"1179\">24</sup>, גם בו ישנם ג' קוין, יד ימין ורגל ימין שהוא בדוגמת קו הימין שלמעלה, יד שמאל ורגל שמאל שהוא דוגמת קו השמאל שלמעלה, ראש גוף ויסוד שהוא דוגמת קו האמצעי שלמעלה. הנה בקו הימין וקו השמאל ישנם שינויים, שאינו דומה ידים לרגלים ובפרט לצפרנים שהם רק טפלים להאדם, משא\"כ בקו האמצעי הרי ידוע בענין אין קישוי אלא לדעת<sup data-n=\"1180\">25</sup> אשר מיד שמתעורר בדעתו שבמוחו הנה באותו הרגע מתעורר היסוד כו' כמבואר בהוספות לתו\"א<sup data-n=\"1181\">26</sup>. דכמו\"כ הוא גם בג' הקוין שלמעלה, אשר ב' הקוין ימין ושמאל, חד אריך וחד קציר<sup data-n=\"1182\">27</sup>, הם מתמעטים ומשתנים כו', משא\"כ קו האמצעי, חד בינוני<sup data-n=\"1182\">27</sup>, שהוא מראשו ועד סופו בשוה. וזהו מעלת יעקב קו האמצעי שלימו שבאבהן&lt;13&gt;, שהיתה מטתו שלימה<sup data-n=\"1183\">28</sup>. דאברהם יצא ממנו ישמעאל ויצחק יצא ממנו עשו<sup data-n=\"1184\">29</sup>, ואף שהוא רק בדרך יצא<sup data-n=\"1185\">30</sup> מ\"מ הרי יצא ממנו. והוא דלהיות שאברהם ויצחק הם בקו הימין והשמאל, אשר ב' קוין אלו כל מה שהם נמשכים למטה הם מתמעטים כו' כנ\"ל, הנה מצד המיעוט אחרי מיעוט שנעשה בסיום ההמשכה, הי' אפשר להיות יצא ממנו כו'. משא\"כ יעקב להיותו בקו האמצעי שאין בו שינויים היתה מטתו שלימה, אשר גם כמו שהוא נמשך למטה בבחי' מטתו הוא בתכלית השלימות.\n<b>ובזה</b> יובן מ\"ש בכתבי האריז\"ל<sup data-n=\"1186\">31</sup> על הפסוק<sup data-n=\"1187\">32</sup> שלשה המה נפלאו ממני וארבעה לא ידעתים דרך הנשר בשמים, שהי' שלמה מתמה איך הנשר שהוא עוף טמא נמצא בשמים בבחינת המרכבה שלמעלה. וידוע<sup data-n=\"1188\">33</sup> הקושיא בזה למה הי' שלמה מתמה על ג' – רק הנשר והרי גם ארי' הוא חי' טמאה ומ\"מ פני ארי' הוא אחד מד' חיות שבמרכבה. אך הענין הוא, דנשר מלשון נשר ונפל. וזהו החידוש שבנשר על ארי' אשר גם מה שנשר ונפל הנה גם זה הוא בשמים. ולכן הי' מתמה על נשר דוקא ולא על ארי', דמה שארי' הוא בשמים הוא רק השרש דארי' ולא כמו שנפל למטה בבחי' חי' טמאה. ואף שזה גופא מה שנפל למטה כ\"כ מורה על מעלת שרשו, כידוע מ\"ש באוה\"ח<sup data-n=\"1189\">34</sup> שמצד תוקף האור דקדושה שבבחינת פני ארי' שבמרכבה לכןנפל למטה כל כך בחינת טמאה דוקא, מ\"מ הרי לאחרי הנפילה כו' אינו בשמים, שעל ידי המסכים והפרסאות וההפסקים שמבדילים הוא נפל ונעשה נפרד משרשו. משא\"כ דרך הנשר בשמים הוא שגם מה שנשר ונפל הוא ג\"כ בשמים. דזהו מעלת קו האמצעי על קו הימין וקו השמאל, ימין מקרבת ושמאל דוחה<sup data-n=\"1190\">35</sup>, דמה שימין מקרבת הוא מה שהוא מברר מזכך ומעלה את דברים המותרים, משא\"כ דברים האסורים וקשורים בידי החיצונים הנה בהם שמאל דוחה. משא\"כ מצד קו האמצעי, בחינת רחמים דנשר, הנה גם מה שנשר ונפל, גם זה הוא בשמים דזהו מעלת התשובה, אשר התשובה מהפכת גם את הזדונות לקדושה. שבתחילת עבודת התשובה, נעשים הזדונות רק לשגגות, אבל תכלית התשובה הוא שהזדונות נהפכים לזכיות<sup data-n=\"1191\">36</sup>. וזוהי מעלת התשובה, בחינת בקש שלום<sup data-n=\"1192\">37</sup>, על העבודה דסור<sup data-n=\"1192\">37</sup> מרע ועשה טוב<sup data-n=\"1193\">38</sup>.\n<b>וזהו</b> כנשר יעיר קנו גו', שקאי אדלעיל מיני' כי חלק הוי' עמו יעקב חבל נחלתו ימצאהו בארץ מדבר גו' יצרנהו כאישון עינו<sup data-n=\"1194\">39</sup>. יעקב הוא בחי' קו האמצעי כנ\"ל, שלכן הוא בשוה מראשיתו ועד סופו. דזהו יעקב חבל נחלתו שהוא דוגמת החבל שראשו אחד למעלה וראשו השני למטה, הנה כשמנענעים בקצהו התחתון מתנענע גם קצהו העליון כמבואר באגרת התשובה<sup data-n=\"1195\">40</sup>, דלהיות שיעקב הוא קו האמצעי לכן הוא חבל נחלתו כו'. ימצאהו בארץ מדבר, מדבר הוא אשר לא ישב אדם שם<sup data-n=\"1196\">41</sup>, שבחי' אדם העליון שנמשך ע\"י התומ\"צ לא ישב שם<sup data-n=\"1197\">42</sup>. ואעפ\"כ הנה מצד התשובה (קו האמצעי) ימצאהו בארץ מדבר ובתהו יליל ישימון, שגם בזה ימצאהו, כמבואר בלקו\"ת<sup data-n=\"1198\">43</sup> בענין ובקשתם משם<sup data-n=\"1199\">44</sup>. יצרנהו כאישון עינו<sup data-n=\"1200\">45</sup> הוא השחור שבעין שהמאור יוצא הימנו כדפירש\"י, והו\"ע<sup data-n=\"1201\">46</sup> אתהפכא חשוכא לנהורא<sup data-n=\"1202\">47</sup>, דכאשר מהפכים את החשוכא לנהורא הנה אז הוא יתרון האור, כידוע<sup data-n=\"1203\">48</sup> בענין יתרון האור מן החשך<sup data-n=\"1204\">49</sup>. וע\"ז ממשיך אח\"כ כנשר יעיר קנו גו' ישאהו על אברתו שמצד בחי' כנשר הוא בחי' עתיק כנ\"ל (שלשם מגיע קו האמצעי?) ישאהו על אברתו, למעלה מתורה ומצוות, סליחה וכפרה, ועד שנמשך לו מבחי' שלמעלה מתורה ומצוות, על אברתו, ומסייםהוי' בדד ינחנו ואין עמו א-ל נכר<sup data-n=\"1205\">50</sup>, שאין לזרים אתך ויהיו לך לבדך<sup data-n=\"1206\">51</sup>, ישראל ומלכא בלחודוהי<sup data-n=\"1207\">52</sup>.\n**********",[["1156","1","האזינו לב, יא."],["1157","2","תרמ\"א (המשך יונתי תר\"מ – תורת שמואל שער שמיני ע' מד)."],["1158","3","ע\"פ פיוט יגדל."],["1159","4","חוקת יט, יד. וראה זח\"ב קיז, ריש ע\"ב."],["1160","5","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא רפכ\"ג</a>."],["1161","6","זח\"ג קיג, א. וראה ויק\"ר פל\"ה, ז."],["1162","7","ראה זח\"א יח, סע\"ב. רמ\"ז לזח\"ג ס\"פ עקב. הובא באוה\"ת האזינו ע' א'תרפה. רד\"ה כנשר יעיר קנו תרע\"ח (סה\"מ תרע\"ח ס\"ע כג ואילך). רד\"ה הנ\"ל תרפ\"ב (קונטרס מאמרים תרפ\"ב – קה\"ת, תשנ\"ב – ע' 36)."],["1163","8","מלכים-א א, כא. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380923\" data-slug=\"likkutei-torah\" data-id=\"4001380923\">נצבים נא, א</a>. ובכ\"מ."],["1164","9","תנחומא עקב ב. פרש\"י האזינו שם."],["1165","10","תנחומא שם."],["1166","11","ב\"ר פמ\"ז, ו. פפ\"ב, ו."],["1167","12","האזינו שם, ט."],["1168","13","זח\"א קמז, ב (בס\"ת). שם קמט, ריש ע\"ב. ועוד."],["1169","14","בהבא לקמן – ראה ד\"ה כנשר הנ\"ל (סה\"מ תרע\"ח ע' כד ואילך. קונטרס מאמרים הנ\"ל ס\"ע 36 ואילך)."],["1170","15","ראה זח\"ב קעה, ב."],["1171","16","ראה תרומה כו, כח."],["1172","17","ראה רבנו בחיי תרומה שם. ספרים שהובאו בתורה שלימה תרומה שם (אות פו)."],["1173","18","ראה זח\"ב סג, ב. זח\"ג ע, רע\"א."],["1174","19","אחרי טז, ל."],["1175","20","קהלת יב, ז."],["1176","21","האזינו עא, ג."],["1177","22","ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670142\" data-slug=\"torat-chaim\" data-id=\"2300670142\">תו\"ח נח סה, ב</a>. המשך תער\"ב ח\"א ע' רכ ואילך. ח\"ב ע' תשמב ואילך. סה\"מ תרפ\"ג ע' קז ואילך. תש\"ז ע' 152 ואילך. ועוד."],["1178","23","בראשית א, כו."],["1179","24","ד\"ה כי המצוה דש\"פ נצבים תשכ\"ח. ד\"ה תקעו דיום ב' דר\"ה שנה זו (תשכ\"ט) פ\"ד (סה\"מ תשכ\"ט ע' ו ואילך)."],["1180","25","יבמות נג, סע\"ב."],["1181","26","קה, סע\"ג ואילך."],["1182","27","תקו\"ז בהקדמה (יז, א)."],["1183","28","תו\"כ בחוקותי כו, מב. ויק\"ר פל\"ו, ה."],["1184","29","ויק\"ר שם. פסחים נו, א. ספרי ואתחנן ו, ד. ועוד."],["1185","30","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381168\" data-slug=\"likkutei-torah\" data-id=\"4001381168\">לקו\"ת שה\"ש ט, ד</a>."],["1186","31","לקו\"ת עה\"פ."],["1187","32","משלי ל, יח."],["1188","33","אוה\"ת האזינו ע' א'תרפט ואילך. ד\"ה הנ\"ל תרע\"ח (סה\"מ תרע\"ח ע' ל)."],["1189","34","אחרי יז, יד."],["1190","35","סוטה מז, א. וש\"נ."],["1191","36","יומא פו, ב."],["1192","37","תהלים לד, טו."],["1193","38","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380614\" data-slug=\"likkutei-torah\" data-id=\"4001380614\">לקו\"ת בלק עד, א</a> ואילך. סה\"מ תרל\"ד ע' קנו ואילך. תרע\"ח ע' קלט ואילך."],["1194","39","האזינו שם, יו\"ד."],["1195","40","פ\"ה-ו."],["1196","41","ירמי' ב, ו."],["1197","42","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380390\" data-slug=\"likkutei-torah\" data-id=\"4001380390\">לקו\"ת נשא כ, ג</a>."],["1198","43","ראה לב, ב."],["1199","44","ואתחנן ד, כט."],["1200","45","ראה ד\"ה כנשר הנ\"ל (סה\"מ תרע\"ח ע' כט. קונטרס מאמרים הנ\"ל ע' 46)."],["1201","46","ראה ד\"ה יסובבנהו במאמרי אדמו\"ר הזקן תקס\"ו ס\"ע שסג. ע' שצו."],["1202","47","ראה זח\"א ד, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310015\" data-slug=\"tanya\" data-id=\"3401310015\">תניא פ\"י</a>."],["1203","48","ראה בארוכה המשך תער\"ב ח\"ג ע' א'שטו ואילך."],["1204","49","ע\"פ קהלת ב, יג."],["1205","50","האזינו שם, יב."],["1206","51","משלי ה, יז."],["1207","52","ראה זח\"ג לב, א."]]],[1500360019,"<h3>אור לערב חג הסוכות, ה'תשל\"ו<sup data-n=\"1208\">*</sup></h3>\n<b>בסוכות</b> תשבו שבעת ימים (ומוסיף עוד ציווי) כל האזרח בישראל ישבו בסוכות (והטעם על זה) למען ידעו דורותיכם כי בסוכות הושבתי את בנ\"י בהוציאי אותם מארץ מצרים גו'<sup data-n=\"1209\">1</sup>. וידועים הדיוקים בזה במאמרי רבותינו נשיאינו, ובהקדים מ\"ש בעל ההילולא<sup data-n=\"1210\">2</sup> שסוכה הו\"ע השלום כמ\"ש<sup data-n=\"1211\">3</sup> ופרושׂ עלינו סוכת שלומך, וצריך להבין מהי השייכות דסוכה לשלום. והנה בז' ימי הסוכות ישנם כמה ענינים, השייכים לבסוכות תשבו שבעת ימים. וכמו מצות נטילת ד' מינים (ולקחתם<sup data-n=\"1212\">4</sup> לכם ביום הראשון גו') שיש לה שייכות לענין הסוכה. וכידוע<sup data-n=\"1213\">5</sup> שמצוה מן המובחר שנטילת ד' מינים תהי' בסוכה. וגם יש בז' ימי הסוכות הענין דהקרבת ע' פרים שהם כנגד שבעים אומות כדאיתא במדרש<sup data-n=\"1214\">6</sup>. וענין זה יש גם עכשיו כמ\"ש ונשלמה פרים שפתינו<sup data-n=\"1215\">7</sup>, ובפרט ע\"פ המבואר<sup data-n=\"1216\">8</sup> דונשלמה הוא לא רק הענין דתשלומין אלא גם מלשון שלימות, היינו שגם בזמן הגלות, ע\"י אמירת פסוקי הקרבנות דע' פרים הענין הוא בשלימותו, ואף שבזמן הגלות, מכיון שהפעולה היא רק ע\"י \"שפתינו\", אי\"ז ניכר בגלוי בגשמיות ועאכו\"כ בחומריות העולם, מ\"מ, מכיון שעקימת שפתיו הוי מעשה<sup data-n=\"1217\">9</sup>, וכמבואר בארוכה בתניא<sup data-n=\"1218\">10</sup>, הרי גם עכשיו הפעולה בשלימותה ברוחניות (ובמעשה זוטא עכ\"פ). וצריך להבין, מהי השייכות דענינים אלו (נטילת ד' מינים והקרבת ע' פרים) לענין הסוכה. והנה כאשר יו\"ט ראשון של חג חל להיות בשבת [כקביעות שנה זו] יש חילוק בין זמן הבית לזמן הגלות [ובדוגמת<sup data-n=\"1219\">11</sup> תקיעת שופר ביו\"ט של ראש השנה שחל להיות בשבת, שבמקדש היו תוקעין אבל לא במדינה],שבזמן הבית ביו\"ט ראשון של חג לולב דוחה שבת אף בגבולין, ומשחרב בית המקדש אין לולב דוחה שבת גם ביו\"ט ראשון, כמבואר במשנה וגמרא<sup data-n=\"1220\">12</sup>.\nב) <b>ונקודת</b> הביאור בכל ענינים אלו, דסוכה הוא ענין המקיף<sup data-n=\"1221\">13</sup>. ולא כהמקיף דלבוש, שעם היותו בחי' מקיף מ\"מ יש בו התחלקות, לבושי הראש לבושי הגוף ולבושי הרגל (ובכאו\"א לפי מדת המלובש בו). משא\"כ המקיף דסוכה שאין בו התחלקות, שהרי הוא מקיף את ראשו ורובו<sup data-n=\"1222\">14</sup> [שהכוונה בזה – כמו ראשו וכולו, כי רובו ככולו], הראש הגוף והרגל כאחד<sup data-n=\"1223\">15</sup>. ועפ\"ז צריך להבין מ\"ש בסוכות תשבו [כהדיוק בכ\"מ בדרושי רבותינו נשיאינו, וגם בהמשך תרס\"ו<sup data-n=\"1224\">16</sup>], הרי מקיף (ובפרט כהנ\"ל) אינו בבחינת התיישבות, וא\"כ מהו\"ע בסוכות תשבו [וגם אומר בסוכות (בבי\"ת<sup data-n=\"1225\">17</sup>)]. וענין זה (התיישבות בסוכה) אומרו ג' פעמים, בסוכות תשבו גו' ישבו בסוכות גו' בסוכות הושבתי. גם צריך להבין מ\"ש למען ידעו דורותיכם כי בסוכות הושבתי גו' (שהטעם לבסוכות תשבו גו' הוא בכדי שהדורות הבאים<sup data-n=\"1226\">18</sup> ידעו כי בסוכות הושבתי גו'), דמכיון שמצות סוכה אינה ממצות התלויות בארץ ולא ממצות התלויות בזמן הבית, יהי' קיומה במשך כל הדורות<sup data-n=\"1227\">19</sup>, כי התורה הזאת לא תהי' מוחלפת ח\"ו. וא\"כ הרי הידיעה (כי בסוכות הושבתי גו') של דורות הבאים תהי' עי\"ז שהם עצמם ישבו בסוכות, ומהו בסוכות תשבו גו' למען ידעו דורותיכם, שהידיעה של דורות הבאים תהי' ע\"י בסוכות תשבו דדורות הקודמים.\nג) <b>והביאור</b> בזה הוא (כאמור לעיל) שסוכה הו\"ע מקיף. דהנה כתיב<sup data-n=\"1228\">20</sup> בכסה ליום חגינו, דכל הענינים שהם בכסה (כיסוי והעלם) בהימים שלפני יום חגנו מתגלים הם בסוכות<sup data-n=\"1229\">21</sup>. וכמו ענין השופר דר\"ה, שמצות היום בשופר<sup data-n=\"1230\">22</sup>, הוא בא בגילוי ליום חגנו, בהסכך דסוכה. דזהו מה שסכך [דכל סוכות הכתוב סכך משמע דדופן לא איקרי סוכה<sup data-n=\"1231\">23</sup>] בגימטריא מאה<sup data-n=\"1232\">24</sup>, כנגד מאה קולות דשופר שנהגו<sup data-n=\"1233\">25</sup> ישראל (שמנהג ישראל תורה היא) לתקוע בר\"ה. וגם פרטי הקולות מרומזיםבהאותיות דסכך, ס' קולות דתקיעה, כ' קולות דשברים וכ' דתרועה<sup data-n=\"1234\">26</sup>. ועד\"ז הוא גם בנוגע לענין הקטורת דיוהכ\"פ שבא בגילוי ליום חגנו, כידוע<sup data-n=\"1235\">27</sup> שסכך הסוכה הוא נעשה מענן הקטורת דיום הכפורים. ואף שביום הכפורים כבר ישנו ענין הגילוי, דעיקר ענין בכסה (החדש מתכסה) הוא בתחילת החודש, בראש השנה, מ\"מ הגילוי דיום הכפורים (עיקרו) הוא למעלה<sup data-n=\"1236\">28</sup>, משא\"כ בסוכות נמשך הגילוי למטה ועד אשר (סכך הסוכה, הבא מענן הקטורת דיום הכפורים) נראה גם לעיני בשר [וי\"ל דהתחלת גילוי זה היא בהימים שבין יום הכפורים לסוכות, שאז היא ההכנה למצות סוכה ואז עשיית הסוכה<sup data-n=\"1237\">29</sup>. היינו שבימים אלו היא ההכנה והתחלת המשכת הגילוי (דיום הכפורים) שעיקרו למעלה – גם למטה]. וזהו מה שסוכה היא בחי' מקיף. דהנה ההפרש בין קטורת לקרבנות הוא<sup data-n=\"1238\">30</sup>, שבקרבנות כתיב<sup data-n=\"1239\">31</sup> לחמי לאשי, דלחם הוא ענין פנימי (ויש קרבנות שהם נאכלים גם לכהנים, וקרבנות הנאכלים גם לבעלים ולכל אדם), משא\"כ קטורת (ובפרט דיום הכפורים) הוא מקיף. ולכן גם הגילוי שלו ליום חגנו הוא בענין של מקיף, המקיף דסכך. ומכיון שהוא שייך לקודש קדשים שהוא אמיתית הענין דמקיף, לכן גם המקיף דסוכה הנמשך מענן הקטורת דיום הכפורים הוא למעלה מהמקיף דלבוש ואין בו התחלקות, ועד שמקיף גם את הלבושים דראש גוף ורגל כאחד.\nד) <b>וזוהי</b> השייכות דסוכה לענין השלום כמ\"ש ופרושׂ עלינו סוכת שלומך, דמאחר שסוכה הו\"ע המקיף (שלמעלה מהתחלקות), נמשך מהמקיף דסוכה ענין השלום, נעשה שלום בין נפה\"א לנפה\"ב, וגם שלום בכל הבחינות דנפה\"א עצמה, דמכיון שהסוכה מקיפה את כל עניני האדם, מראשו ועד רגלו, לכן על ידה נעשה שלום בכל הבחינות שבאדם. ועד שע\"י הסוכה נעשה שלום גם בעולם, וכידוע<sup data-n=\"1240\">32</sup> שסוכה היא בדוגמת תיבת נח, שבה הי' ענין השלום (דאף שהיו בתיבה כל החיות יחד, מ\"מ לא הריעו ולא השחיתו זל\"ז), ומעין השלום שיהי' לע\"ל אשר לא ירעו ולא ישחיתו גו'<sup data-n=\"1241\">33</sup>. ואף שהמקיף דסוכה הוא בחי' חיצוניות בינה ותיבת נח היא בחי' פנימיות בינה, ולע\"ל יהי' למעלה גם מבחי' פנימיות בינה כמו שהיא במקומה, אעפ\"כ השלום דבחי' המקיף דסוכה הוא בדוגמת השלום דלע\"ל. כי הטעם דלא ירעו ולא ישחיתו (דלע\"ל) הוא ע\"י הדעת (וכמו שמסיים בכתוב) כי מלאה הארץדעה את הוי', ולכן גם המקיף דסוכה שענינו הוא למען ידעו גו'<sup data-n=\"1242\">34</sup> (ענין הדעת), הוא פועל ענין השלום בדוגמת השלום דלע\"ל. ובפרט לפי הביאור<sup data-n=\"1243\">35</sup> בהשייכות דסכך הסוכה לענן הקטורת דיום הכפורים שענינו הוא בחי' עתיק [ובדוגמת כללות הענין דיום הכפורים, יום שנתחייב בחמשה תפלות<sup data-n=\"1244\">36</sup>, לפי שהוא בחי' עתיק], כי בבחי' בינה (גם בחיצוניות בינה<sup data-n=\"1245\">37</sup>) הוא גילוי עתיק, דהתגלות עתיק הוא בבינה, הנה בחי' עתיק המתגלה בסכך הסוכה, פועל ענין השלום, שלכן נקראת הסוכה בשם סוכת שלומך.\nה) <b>והנה</b> הכוונה בהמשכת המקיפים דסוכה היא שיומשכו ויפעלו גם בפנימיות. וזהו\"ע נטילת ד' מינים הבאה בהמשך לבסוכות תשבו [דמצות ישיבה בסוכה היא מהתחלת שבעת ימי הסוכות, ולאחרי זה בבוקר (בעלות השחר או מנץ החמה<sup data-n=\"1246\">38</sup>) מתחילה מצות נטילת ד' מינים], דהנה ענין נטילת ד' מינים הוא להמשיך המקיף (דסוכה) בפנימיות, וכמבואר בקבלה (מ\"ח) ובחסידות<sup data-n=\"1247\">39</sup> שענין הנענועים הוא להמשיך בחי' הדעת בנוקבא דז\"א העומדת בחזה דז\"א [שלכן צריך שהלולב ומיניו יגעו בחזה], דענין ההמשכה בנוקבא הוא שההמשכה תהי' גם בעניני העולם, עד לעניני עוה\"ז התחתון שאין תחתון למטה ממנו. ולכן גם פעולת השלום שע\"י המשכת הדעת היא גם למטה בעוה\"ז התחתון, בדוגמת לע\"ל שלא ירעו ולא ישחיתו גו' כי מלאה <i>הארץ</i> דעה את הוי'. והשייכות דמלאה הארץ דעה גו' ללא ירעו ולא ישחיתו הוא<sup data-n=\"1248\">40</sup> לפי שהקטטות והמריבות הם מצד קטנות הדעת. וידוע המשל על זה, שהקטן שאין לו דעת, כאשר אין ממלאים רצונו, מיד הוא מתרגז כו' (וכמבואר בספר תניא קדישא<sup data-n=\"1249\">41</sup> שהקטן מתכעס כו' מדברים קטנים), משא\"כ הגדול שיש לו דעת, יכול הוא לסבול גם היפוכו. ועד\"ז הוא גם בענין השלום דסוכה, דמכיון שענין הסוכה הוא כמ\"ש למען ידעו, לכן ע\"י הדעת הנמשך ע\"י הסוכה, נעשה השלום, סוכת שלומך.\nו) <b>אמנם</b> בכדי להמשיך המקיף דסוכה בבחי' פנימיות, ועד שיהי' בבחי' התיישבות כמ\"ש בסוכות תשבו [ועד שע\"י נטילת ד' מינים יומשך זה גם בבחי' נוקבא דז\"א], דהגם שהמקיף דסוכה הוא נעלה ביותר [וכנ\"ל שהמקיףדסוכה הוא למעלה אפילו מהתחלקות של לבושי הראש לבושי הגוף ולבושי הרגל, ועאכו\"כ שאין בו ההתחלקות דראש גוף ורגל], מ\"מ יהי' בזה ענין ההתיישבות, בא הביאור כי בסוכות הושבתי את בנ\"י בהוציאי אותם מארץ מצרים, ההתחלה הי' מהקב\"ה, אני המתחיל<sup data-n=\"1250\">42</sup>. וע\"י זה שבסוכות הושבתי, נמשכה נתינת הכח שיהי' בסוכות תשבו. ואומר על זה למען ידעו, שענין הישיבה בסוכה צ\"ל לא באופן דחוקה חקקתי גזירה גזרתי, כ\"א שיומשך ויבוא בדעת, בפנימיות, ויומשך גם בבחי' הזמן, דזהו בסוכות תשבו שבעת ימים, דשבעת ימים כוללים כל משך הזמן וכל השינויים שבהם. וכמבואר בכ\"מ<sup data-n=\"1251\">43</sup> עה\"פ<sup data-n=\"1252\">44</sup> נער הייתי גם זקנתי, שבכל יום ראשון בשבוע מתחיל מחדש הענין דשבעת ימי בראשית. והוא ע\"ד משנת\"ל שע\"י הנענועים ממשיכים בבחי' הנוקבא, (בחי' מלכות) שהיא התחלת<sup data-n=\"1253\">45</sup> ענין הזמן.\nז) <b>וממשיך</b> בכתוב כל האזרח בישראל ישבו בסוכות. וצריך להבין, הרי הציווי בסוכות תשבו גו' הוא לכל ישראל, ומה מוסיף בכל האזרח בישראל גו'. והענין בזה, דאזרח קאי על הבחינה שתזרח לעתיד, ולכן תיבת אזרח מתחלת באל\"ף, שהיא מהאותיות המשמשות על עתיד<sup data-n=\"1254\">46</sup>. וזהו כל האזרח בישראל ישבו בסוכות, שיש בזה ב' פי', שמצד בחי' האזרח בישראל שתהי' לעתיד, יש כח גם עכשיו שיהי' בסוכות תשבו, שגם בבחי' האזרח בישראל, וגם כמו שתהי' לע\"ל, גם בבחי' זו מיתוסף ע\"י הישיבה בסוכה. וי\"ל דזהו הטעם שמצות סוכה תהי' לע\"ל ביתר שאת ויתר עז, כמבואר בנבואת זכרי'<sup data-n=\"1255\">47</sup> (שמפטירין בימי הסוכות).\nח) <b>והנה</b> בהמשך<sup data-n=\"1256\">48</sup> למצות ישיבה בסוכה ונטילת ד' מינים באה המצוה דהקרבת ע' פרים כנגד שבעים אומות, היינו שע\"י הקרבת ע' פרים מגינים על הע' אומות<sup data-n=\"1257\">49</sup> ומגלים את תכלית הבריאה שלהם, דכל העולם לא נברא אלא לצוות לזה<sup data-n=\"1258\">50</sup> ואני נבראתי לשמש את קוני<sup data-n=\"1259\">51</sup>. דאמיתית ענינם (של אוה\"ע) הוא כמו שיהי' לע\"ל לצוות לישראל כו', וכמ\"ש<sup data-n=\"1260\">52</sup> והיו מלכים אומניך ושרותיהם מיניקותיך, ועאכו\"כ אלו שלמטה ממלכים ושרותיהם. ומכיון שכל הענינים והגילויים דלעתיד תלויים במעשינו ועבודתנו במשך שיתא אלפי שנין (כולל משך זמן הגלות, ואדרבההם תלויים בעיקר בהעבודה שבזמן הגלות<sup data-n=\"1261\">53</sup>), הנה הענין דוהיו מלכים אומניך וגו' שיהי' לע\"ל הוא נעשה ע\"י הקרבת ע' פרים בזמן הבית<sup data-n=\"1262\">54</sup> וע\"י ונשלמה פרים שפתינו משחרב ביהמ\"ק כו' בזמן הגלות. דהנה ידוע שעבודת הקרבנות (ועד\"ז העבודה דונשלמה פרים שפתינו) היא פועלת בכל העולם, דע\"י הקרבת בהמה אחת נעשית עלי' בכל מין החי וכו'<sup data-n=\"1263\">55</sup>, (שע\"י העלאת הדם והחלב שהם החיות והתענוג של בהמה הנקרבת נעשית עלי' בכל מין החי), וע\"י ההמשכה שעי\"ז מלמעלה למטה נעשה המשכה בכל מין החי וכו'. ועד\"ז הוא בהקרבת הע' פרים שהם כנגד הע' אומות, שהעלי' וההמשכה שע\"י קרבנות אלו פועלות בכל ע' האומות, וכמו\"כ הוא באמירת הפסוקים שעקימת שפתיו הוי מעשה, שע\"י אמירת פסוקי הקרבנות דע' פרים שכנגד ע' אומות נעשית בהם המשכה והכנעה, ומתגלית בהם תכלית בריאתם, שלא נבראו אלא לצוות לזה כו', ונתגלה שאתה בחרתנו מכל העמים. וזהו מ\"ש<sup data-n=\"1264\">56</sup> הללו את הוי' כל גוים שבחוהו כל האומים כי גבר עלינו חסדו גו', דלכאורה מהי השייכות דגבר <i>עלינו</i> חסדו שלכן יהללוהו וישבחוהו גוים ואומים<sup data-n=\"1265\">57</sup>. וידוע הביאור בזה<sup data-n=\"1266\">58</sup>, שע\"י שגבר עלינו חסדו נעשה בירור זיכוך ועלי' גם בגוים ואומים, ועד שזה ניכר בהם בגילוי<sup data-n=\"1267\">59</sup>, ולכן הם מהללים ומשבחים את הוי'. וענין זה נעשה ע\"י הקרבת ע' פרים<sup data-n=\"1268\">60</sup>, ועד\"ז ע\"י העבודה דונשלמה פרים שפתינו, דמכיון שעקימת שפתיו הוי מעשה לכן הפעולה שע\"י שפתינו הוא גם בעולם העשי'.\nט) <b>וזהו</b><sup data-n=\"1269\">61</sup> השייכות והקשר של הקרבת ע' פרים לבסוכות תשבו, כי בכדי לפעול בגוים ואומים צריכה להיות תחילה המשכת המקיף שע\"י סוכה, דאור מקיף מסמא עיני החיצונים. ואף שבירור הגוים והאומים הוא ע\"י עבודה פנימית דוקא [שלכן הבירור דע' אומות נעשה ע\"י הקרבת הקרבנות דע' פרים, דקרבנות הו\"ע פנימיות, לחמי לאשי], ובדוגמת כללות ענין הבירורים שהוא ע\"י עבודה פנימית כמאמר<sup data-n=\"1270\">62</sup> נהמא אפום חרבא ליכול [דאכילה הו\"ע בירור פנימי], אעפ\"כ בתחילה צריכה להיות המשכת המקיף דסוכה, שעי\"ז נעשה בהם ביטול והכנעה כללית, וביטול זה הוא הקדמה והכנה והכשרה להבירור שלהם אח\"כ ע\"י הקרבת הע' פרים, ועד\"ז ע\"י ונשלמה פרים שפתינו בזמן הגלות, והיא ג\"כ הכנה קרובה להקרבת שבעים פרים כפשוטה.י) <b>וזהו</b> בסוכות תשבו גו' למען ידעו דורותיכם גו'. שע\"י בסוכות תשבו, מה שהמקיף דסוכה הוא באופן דתשבו, ואדרבה, כל הענין דמצות סוכה הוא <i>תשבו</i> [תשבו כעין תדורו, שהאכילה ושתי' וכל עניניו שעושה בביתו יהיו בסוכה<sup data-n=\"1271\">63</sup>], הנה זה פועל שהמקיפים יומשכו גם בדורותיכם, היינו בכחות הגלויים (חב\"ד וז' מדות), ועד אשר <i>ידעו</i> דורותיכם, דעת מלשון התקשרות<sup data-n=\"1272\">64</sup>, שפעולת המקיפים בכחות הגלויים היא באופן של דעת והתקשרות. והטעם (והנתינת כח) לזה הוא, כי בסוכות הושבתי את בנ\"י בהוציאי אותם מארץ מצרים. דמכיון שאני (הקב\"ה) המתחיל, בסוכות הושבתי, זה נותן כח לכאו\"א מישראל, אתם קרויין אדם<sup data-n=\"1273\">65</sup> על שם אדמה לעליון<sup data-n=\"1274\">66</sup>, שגם הוא יפעול דוגמת הפעולה של הקב\"ה, שימשיך השלום דסוכת שלומך בכל עניני עבודתו ובכל הציור שלו (עד שידעו דורותיכם כחות הגלויים שלו), ועד שהמשכת המקיף דסוכה תורגש אצלו גם בהתפלה שלו, כולל גם תפלת מוסף ואמירת פסוקי הקרבנות דע' פרים, שעי\"ז פועל גם בע' אומות כפשוטם, וכמו שאומרים בהלל [שבכל ז' ימי הסוכות אומרים הלל שלם] הללו את הוי' כל גוים שבחוהו כל האומים, שקאי על גוים ואומים כפשוטם. וזה גם נעשה הכנה קרובה לכל האזרח בישראל, שיזרח לע\"ל, ישבו. דהנה ידוע מ\"ש הרמב\"ם<sup data-n=\"1275\">67</sup> בפירוש עולם הבא, שעוה\"ב הוא מצוי ועומד (גם עכשיו) ומה שנקרא עולם הבא הוא לפי שבא לאחרי (ובהמשך ל)העבודה בעוה\"ז. דכמו\"כ הוא גם בנוגע להענינים דלע\"ל, שהענינים (נעשים ו)ישנם גם עכשיו, ומה שנק' לעתיד לבוא הוא לפי שהמשכתם והתגלותם היא לאחרי וע\"י קדימת העבודה בעוה\"ז. וזהו בסוכות תשבו גו' כל האזרח בישראל גו', שע\"י קיום מצות בסוכות תשבו ממשיכים גם עכשיו בחי' כל האזרח בישראל, וזה נעשה הכנה קרובה לגילוי בחינה זו לע\"ל, שאז תתגלה בכל התוקף שלה.\nיא) <b>וזהו</b>&lt;61&gt; מה שיו\"ט ראשון של חג שחל להיות בשבת אין לולב דוחה שבת, כי נטילת לולב הוא בכדי להמשיך בחי' המקיף (דסוכה) בפנימיות לכן בשבת שאז מאיר המקיף בבחי' פנימיות (מצד ענין השבת), אין צריך (כ\"כ) לנטילת לולב, ולכן מספיקה הגזירה דרבה לדחות נטילת לולב. ומה שבזמן ביהמ\"ק היו נוטלין גם בשבת, הוא לפי שיש כמה מדריגות במקיפים, וע\"י נטילת לולב בזמן הבית המשיכו בחי' מקיף עליון יותר מבחי' המקיף שנמשך בשבת מצד עצמו (מה ששבת מיקדשא וקיימא<sup data-n=\"1276\">68</sup>) וגם בחוץ לארץ (בזמן הבית). משא\"כ בזמן הגלות, גם ע\"י נטילת לולב א\"א להמשיך בחי' מקיף העליון, ומה שממשיכים עכשיו הוא רק בחי' המקיף שנמשך ע\"י השבת.<b>והנה</b> כאמור לעיל, בסוכות תשבו, המשכת המקיף דסוכה, היא הכנה קרובה לכל האזרח בישראל שיזרח לע\"ל, גילוי בחי' אמיתית המקיף, בחי' פנימיות עתיק. שזהו החידוש בהגילוי דלע\"ל, שעכשיו כל הגילויים הם רק מבחי' חיצוניות עתיק ולע\"ל יהי' גילוי בחי' פנימיות עתיק<sup data-n=\"1277\">69</sup>. וזהו מ\"ש<sup data-n=\"1278\">70</sup> ישקני מנשיקות פיהו שילמדו תורתו של משיח מפיו של משיח, שענינו הוא בחי' פנימיות עתיק [דזהו מה שמשיח הוא למעלה גם מאדה\"ר, וכמ\"ש<sup data-n=\"1279\">71</sup> ירום ונשא וגבה מאד, מאד אותיות אדם אבל בצירוף המורה על בל\"ג, שלמעלה גם מאדה\"ר<sup data-n=\"1280\">72</sup>]. וזהו בסוכות תשבו גו' כל האזרח גו', שהמשכת המקיף דסוכה היא הכנה קרובה להגילויים דגאולה העתידה ע\"י משיח צדקנו יבוא ויגאלנו ויוליכנו קוממיות לארצנו, ושם נעשה לפניך את קרבנות חובותינו כמצות רצונך, בקרוב ממש.\n**********",[["1208","*","יצא לאור בשעתו, \"<i>ערחה\"ס ה'תשל\"ו</i>\"."],["1209","1","אמור כג, מב-מג."],["1210","2","וככה תרל\"ז פצ\"ו."],["1211","3","בתפלת ערבית."],["1212","4","אמור כג, מ."],["1213","5","סידור אדה\"ז (לפני הלל). וראה מ\"ח מס' ימי מצוה וסוכה רפ\"ה: והדין נותן כו'."],["1214","6","סוכה נה, ב. במדב\"ר פכ\"א, כד – הובא ברש\"י עה\"ת (פינחס כט, לה), שמזה מוכח שזה שייך גם לפשוטו של מקרא [היינו, שהפעולה בהע' אומות היא גם בעולם <i>העשי'</i>]."],["1215","7","הושע יד, ג. וראה שו\"ע אדה\"ז חאו\"ח מהד\"ת ס\"א, ס\"ט: <i>לקיים</i> מ\"ש ונשלמה כו'. דפשטות הל' משמע שזהו ציווי מדברי קבלה (ותקנת חז\"ל – ברכות כו, ב – הוא בנוגע לקביעות הזמן (ולקרבנות ציבור)), אבל מדכתב לפני זה רק \"טוב מאד לומר\" ותו לא, וגם לא ראיתי מקפידין באמירת פסוקי קרבנות היחיד – משמע דקרא אסמכתא הוא. ואכ\"מ."],["1216","8","ראה ד\"ה שובה ישראל שנה זו (לעיל ע' פג ואילך)."],["1217","9","ב\"מ צ, סע\"ב. סנה' סה, א."],["1218","10","פל\"ז (מז, א). וראה ג\"כ קו\"א ס\"ב (קנד, א)."],["1219","11","אבל לא בכל הפרטים – כי בר\"ה שחל בשבת, לא היו תוקעין בגבולין גם בזה\"ב, משא\"כ לולב הי' ניטל בזה\"ב גם בגבולין (ראה תוס' רפ\"ד דר\"ה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380950\" data-slug=\"likkutei-torah\" data-id=\"4001380950\">לקו\"ת ר\"ה נז, ד</a>)."],["1220","12","סוכה רפ\"ד."],["1221","13","ראה לקמן בהמאמר, שענין זה – מה שסוכה הוא מקיף – הוא הביאור לכל הדיוקים דלעיל: השייכות דסוכה לשלום; השייכות דד' מינים והקרבת ע' פרים לסוכות; הטעם מה שלולב (בזה\"ג) אינו דוחה שבת."],["1222","14","טושו\"ע או\"ח סתרל\"ד."],["1223","15","לכאורה זהו החילוק דמקיף דלבוש ובית (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381122\" data-slug=\"likkutei-torah\" data-id=\"4001381122\">לקו\"ת</a> ד\"ה מזמור שיר חנוכת הבית (צח, ד). ובכ\"מ). וי\"ל דיתרה במקיף דסוכה דעליו אמרז\"ל (סוכה כז, ב) <i>דכל ישראל</i> ראוים לישב בסוכה <i>אחת</i>."],["1224","16","ד\"ה לולב וערבה בתחילתו."],["1225","17","משא\"כ (עקב ח, יב): ובתים טובים תבנה וישבת."],["1226","18","דאם הכוונה להיושבים עצמם (ראה מפרשים עה\"פ) – הול\"ל \"למען תדעו\"."],["1227","19","להעיר מע\"ז ג, א."],["1228","20","תהלים פא, ד."],["1229","21","סידור [עם דא\"ח] רלה, ב. ובכ\"מ. וראה גם לקו\"ת ר\"ה נד, ריש ע\"ד."],["1230","22","ר\"ה כו, ב."],["1231","23","רש\"י ד\"ה כשרין (סוכה יב, א. וראה רש\"י שם ב, א ד\"ה ושחמתה)."],["1232","24","מ\"ח ופע\"ח שער הסוכות בסופו. המשך וככה תרל\"ז ספצ\"ג."],["1233","25","שו\"ע אדה\"ז או\"ח סתקצ\"ו ס\"א."],["1234","26","תורת לוי\"צ ע' שג."],["1235","27","עט\"ר שער יו\"כ לו, סע\"א ואילך. אוה\"ת סוכות ע' א'תשכב ואילך. וככה שם פפ\"ד. ד\"ה והוא כחתן תרנ\"ז פי\"א ואילך. ועוד."],["1236","28","ראה סד\"ה לולב וערבה, תרס\"ו."],["1237","29","ראה ויק\"ר פ\"ל, ז. ולהירוש' (ברכות פ\"ט, ה\"ג) מברך על עשייתה. ובשו\"ע אדה\"ז רסתרמ\"א – בטעם הפס\"ד שאין מברכין מפני שעשייתה אינה <i>גמר</i> המצוה, וברכת שהחיינו קאי גם על העשי'."],["1238","30","המעלה דקטורת על קרבנות – ראה עט\"ר שם. שערי אורה ד\"ה בכ\"ה בכסלו פי\"ג ופכ\"ה. ד\"ה והוא כחתן שם. ועוד."],["1239","31","פינחס כח, ב."],["1240","32","ד\"ה כי פדה לאדה\"ז (סה\"מ אתהלך-לאזניא ע' נז. עם הגהות – <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560405\" data-slug=\"or-hatorah-hb\" data-id=\"8316560405\">אוה\"ת נח (כרך ג) תרסט, א</a> ואילך. לקו\"ת לג\"פ סה, א). וככה תרל\"ז פצ\"ה."],["1241","33","ישעי' יא, ט."],["1242","34","ובפרט ע\"פ הידוע דלמען ידעו גו' הוא חלק <i>מקיום</i> המצוה כתיקונה (ב\"ח או\"ח רסתרכ\"ה. וראה שו\"ע אדה\"ז שם)."],["1243","35","וככה שם."],["1244","36","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381228\" data-slug=\"likkutei-torah\" data-id=\"4001381228\">לקו\"ת</a> ס\"פ פנחס שה' תפלות ביו\"כ הו\"ע ארבע הידות גו' והחמישית לפרעה. ומציין שם לע\"ח של\"א פ\"ז ולביאור ע\"פ צאו\"ר בסופו (לקו\"ת שה\"ש כד, רע\"ד), ושם, שהחמישית הוא בחי' עתיק."],["1245","37","כמובן גם מהביאור – דכשמבין השכל מתענג (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380947\" data-slug=\"likkutei-torah\" data-id=\"4001380947\">לקו\"ת ר\"ה נז, א</a>. סידור רמב, ג. רנט, סע\"א ואילך. ובכ\"מ)."],["1246","38","ב\"י לטור או\"ח הל' סוכה ר\"ס תרנב. שו\"ע שם."],["1247","39","סידור רסג, סע\"ג ואילך. וככה שם פפ\"ד. פפ\"ז. תרס\"ו ע' לב. ובכ\"מ.\nובוככה שם פצ\"ו: והיינו שמבחי' סוכת שלומך יומשך בפנימיות (וראה גם סידור רסד, סע\"א ותרס\"ו שם, שהטעם מה שנטילת לולב צ\"ל בסוכה הוא לפי שע\"י הלולב נמשך האו\"מ בפנימיות)."],["1248","40","וככה פצ\"ד."],["1249","41","רפ\"ו."],["1250","42","לשון המדרש שמו\"ר פי\"ב, ג (לענין מ\"ת)."],["1251","43","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381229\" data-slug=\"likkutei-torah\" data-id=\"4001381229\">לקו\"ת שה\"ש כה, א</a>."],["1252","44","תהלים לז, כה."],["1253","45","שעהיוה\"א פ\"ז. ובכ\"מ."],["1254","46","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת ראה יח, א</a>. שמע\"צ פח, ג. בסוכות תשבו תרצ\"ד (תשי\"א) ותש\"ו בסופו. וראה גם יהל אור לתהלים פט, א."],["1255","47","סי' יד."],["1256","48","דהקרבת מוספין היא לאחרי כו\"כ עבודות היום."],["1257","49","ראה סוכה ובמדב\"ר שבהערה 6. וברש\"י סוכה שם: לכפר עליהם שירדו גשמים בכל העולם. ולהעיר מבמדב\"ר פ\"א, ג."],["1258","50","ברכות ו, סע\"ב. שבת ל, ב."],["1259","51","קדושין בסופה."],["1260","52","ישעי' מט, כג."],["1261","53","וב<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a> נזכר רק \"כל זמן משך הגלות\"."],["1262","54","וע\"פ מחז\"ל (סנה' צח, סע\"א) דמשיח קאתי <i>היום</i> – אם בקולו תשמעו, הרי תומ\"י הי' מתקיים היעוד דוהיו מלכים גו'."],["1263","55","<a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">תניא ספל\"ד</a>. וראה אגה\"ת בסופה ע\"ד עליות עולמות העליונים. אגה\"ק סו\"ס ך."],["1264","56","תהלים קיז."],["1265","57","וכקושיית הגמרא (פסחים קיח, ב) אומות העולם מאי עבידתייהו."],["1266","58","ראה אוה\"ת סוכות ד\"ה הללו את הוי' (ע' א'תשסז). ד\"ה הללו את הוי' תשל\"א (לקמן ע' קפו ואילך)."],["1267","59","להעיר מרש\"י פסחים שם (ד\"ה אגבורות) <i>דחזיתו</i> שעשה לי."],["1268","60","ועפ\"ז מובנת השייכות דפסוק זה לחגה\"ס (ראה סידור רנט, ג. רס, ד. אוה\"ת סוכות שם – אלא שהביאור שם הוא באו\"א)."],["1269","61","ראה בכ\"ז סד\"ה לולב וערבה וסד\"ה ביום השמע\"צ תרס\"ו. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380950\" data-slug=\"likkutei-torah\" data-id=\"4001380950\">לקו\"ת ר\"ה נז, ד</a>."],["1270","62","זח\"ג קפח, ב."],["1271","63","סוכה כח, ב. שו\"ע או\"ח סתרל\"ט."],["1272","64","<a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא ספ\"ג</a>."],["1273","65","יבמות סא, רע\"א."],["1274","66","ראה של\"ה ג, רע\"א. ועוד."],["1275","67","הל' תשובה ספ\"ח. ואף שהרמב\"ם שם מדבר בעולם הנשמות – כ\"ה גם בנוגע ל\"לעתיד לבוא\" (\"עולם הבא\" לפי שיטת הרמב\"ן), ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071226\" data-slug=\"likkutei-sichot\" data-id=\"1300071226\">לקו\"ש ח\"ז ע' 214</a> הערה 7."],["1276","68","ביצה יז, א."],["1277","69","פע\"ח שער הק\"ש פט\"ו. וראה גם לקו\"ת שה\"ש בסופו."],["1278","70","שה\"ש א, ב. ורש\"י שם."],["1279","71","ישעי' נב, יג."],["1280","72","וככה הנ\"ל פ\"כ."]]],[1500360020,"<h3>אור לערב חג הסוכות, ה'תשל\"ח<sup data-n=\"1281\">*</sup>.</h3>\nהנחה\n<b>בסוכות</b> תשבו שבעת ימים כל האזרח בישראל ישבו בסוכות<sup data-n=\"1282\">1</sup>, וידועים דיוקי רבותינו נשיאינו בזה<sup data-n=\"1283\">2</sup>, דצריך להבין מהו כפל הדברים, שלאחר שכבר מצוה בסוכות תשבו שבעת ימים [שזהו ציווי לכללות ישראל ולכל א' מישראל] מה מוסיף עוד באמרו כל האזרח בישראל ישבו בסוכות. גם צריך להבין בעצם ענין מצות סוכה, שלכאורה יש בה דבר והיפוכו. דהישיבה בסוכה צ\"ל תשבו כעין תדורו, דכל שבעת הימים אדם עושה סוכתו קבע וביתו עראי<sup data-n=\"1284\">3</sup>. שכמו שבכל השנה הוא דר בדירתו באופן של קביעות, שעושה בה כל עניניו, הנה כן צ\"ל אופן ישיבתו בסוכה, שיעשה כל עניניו בסוכה, ויראה שהסוכה היא דירתו ומקום קביעותו במשך שבעת ימים אלו. אמנם ביחד ע\"ז, הנה עצם בנין הסוכה הוא בנין של עראי. דענין זה שהסוכה צ\"ל בנין עראי הוא מעיקר תנאי המצוה, ולכן סוכה שהיא גבוהה למעלה מעשרים אמה פסולה<sup data-n=\"1285\">4</sup>, שאחד מהטעמים שבזה הוא לפי שעד עשרים אמה כו' דירתו דירת עראי, למעלה מעשרים אמה אין כו' דירתו דירת עראי אלא דירת קבע<sup data-n=\"1286\">5</sup>, והסוכה צ\"ל דירת עראי דוקא. ומ\"מ השבעת ימים צ\"ל הישיבה בה קבע, שהוא לכאו' דבר והיפוכו. והנה במצות סוכה ישנו עוד ענין מיוחד הצריך ביאור, שמצות סוכה היא מ\"ע שהזמ\"ג, ונוסף ע\"ז שמצות סוכה מוגבלת בהגבלת הזמן, היא מוגבלת גם בהגבלת המקום, שצריך להיות מקום מוכשר לעשיית הסוכה. דהעושה סוכתו תחת האילן כאילו עשאה בתוך הבית<sup data-n=\"1287\">6</sup>, דאין זה מקום מוכשר למצוה זו. משא\"כ בשאר יו\"ט הנה מצינו הגבלה רק בנוגע לזמן אבל לא מצינו שיהי' גם הגבלה בנוגע למקום.\nב) <b>והנה</b> בהמשך למצות ישיבה בסוכה (בסוכות תשבו) באה מצות נטילת ד' מינים, כמ\"ש<sup data-n=\"1288\">7</sup> ולקחתם לכם ביום הראשון פרי עץ הדר כפות תמרים וענף עץ עבות וערבי נחל גו' [דמצות ישיבה בסוכה היא מרגע הראשון שבהתחלת שבעת ימי הסוכות, ולאחרי זה (ובהמשך לה), בבוקר (בעלות השחר, ולכתחלה מנץ החמה<sup data-n=\"1289\">8</sup>)מתחיל זמן החיוב דמצות נטילת ד\"מ, שמצותה ביום דוקא]. שמזה מובן שמצות נטילת ד\"מ יש לה שייכות לענין הסוכה. ובפרט ע\"פ הידוע<sup data-n=\"1290\">9</sup> שמצוה מן המובחר שנטילת ד\"מ תהי' בסוכה דוקא, שבזה מודגש עוד יותר שישנו קשר בין מצות נטילת ד\"מ (ולקחתם לכם) למצות סוכה (בסוכות תשבו). וצלה\"ב<sup data-n=\"1291\">10</sup> מהו הקשר שבין ב' מצוות אלו. ובפרט שלכאו' הם מצוות חלוקות, דמצות סוכה היא שבעת ימים, משא\"כ מצות נטילת ד\"מ עיקר המצוה ומה\"ת היא רק ביום הראשון<sup data-n=\"1292\">11</sup>. [ועוד ידוע החילוק שבזה בין מקדש לגבולין, וכמבואר בגמ'<sup data-n=\"1293\">12</sup> תקנת ריב\"ז. שמזה מסתעפים כמה דינים ופרטי דינים השייכים גם בזמה\"ז בהחילוק שבין יום הראשון לששת הימים שלאח\"ז]. והנה בהד' מינים עצמם צריך להבין, למה נבחרו ד' מינים אלו דוקא<sup data-n=\"1294\">13</sup>. שאע\"פ שכולם הם ממין הצומח מ\"מ מיד בתחלת הציווי מודגש שצריכים להיות מינים מיוחדים דוקא. והמינים צריכים להיות כולם באופן של הדר, וכמ\"ש ולקחתם לכם גו' פרי עץ הדר גו', ודרשו בגמרא<sup data-n=\"1295\">14</sup> שזה קאי גם על הג' מינים שלאח\"ז [אף שבהכתוב נזכר הדר בפירוש רק בנוגע להאתרוג, המין הראשון].\nג) <b>והנה</b><b>,</b> נוסף על דיוקים הנ\"ל ידוע משארז\"ל<sup data-n=\"1296\">15</sup> שלא ניתנו המצוות לישראל אלא לצרף בהן את הבריות (וכמבואר בכ\"מ). דנוסף על עיקר המצוה, שענינה הוא אשר קדשנו במצותיו וצונו וצריך לקיימה כדי למלאות ציווי ורצון המצַווה, הנה נוסף לזה יש בהמצוה עבודה מיוחדת ופעולה בנוגע לעבודת האדם בכלל. וכמו\"כ הוא בעבודת ישראל בחג הסוכות, הן בהמצוה דבסוכות תשבו שבעת ימים, והן בנוגע להמצוה דולקחתם לכם ביום הראשון גו', והן בשמחת בית השואבה שלאח\"ז, שבכולם יש ענינם ופעולתם בעבודה, לצרף בהם את הבריות. וכן הוא גם בנוגע ליום השמיני עצרת. ואע\"פ ששמיני הוא רגל בפ\"ע<sup data-n=\"1297\">16</sup>, מ\"מ הרי נקרא יום השמיני, שזה גופא מורה על שייכותו לשבעת ימי הסוכות שלפנ\"ז<sup data-n=\"1298\">17</sup>. ויתירה מזו (לא רק ששמיני עצרת שייך לסוכות אלא עוד זאת) דכמו שבפשטות בכדי להגיע להשמיני צ\"ל שבעה לפנ\"ז, כמו\"כ הוא בענינם הרוחני של סוכות ושמיני עצרת, שאף שהעבודה דשמיני עצרת ושמחת תורה באה לאחרי [דהיינו שהיא למעלה מ]עבודת ימי הסוכות שלפנ\"ז, מ\"מ הסיבה והגורם להגיע לעבודת שמיני עצרת היא עבודת השבעת ימים שלפנ\"ז דוקא. ומזה מובן העילוי שבהעבודה דסוכות, שהיא דוקא הסיבה והגורם<sup data-n=\"1299\">18</sup> שע\"י באים להעבודה וההמשכות והמעלות שבענין שמיני עצרת.ד) <b>וביאור</b> הענין הוא, דהנה כתיב<sup data-n=\"1300\">19</sup> בכסה ליום חגינו, דיום חגינו קאי על חג הסוכות כמבואר בכ\"מ<sup data-n=\"1301\">20</sup>. וזהו בכסה ליום חגינו, שכל הענינים שהיו בכסה (בכיסוי והעלם) בהימים שלפני יום חגינו, ובפרט הענינים שהיו בכיסוי והעלם בראש השנה [שעליו נאמר בכסה מלשון ליום הכסה יבוא ביתו<sup data-n=\"1302\">21</sup>, וע\"ז קאי מש\"כ תקעו בחדש שופר (בהקדמה לבכסה ליום חגינו)], מתגלים הם בסוכות. וכדאיתא במדרש<sup data-n=\"1303\">22</sup> דבראש השנה לית אנן ידעין מאן הוא נוצח, וכשישראל יוצאין כו' ולולביהון ואתרוגיהון בידן אנן ידעין דישראל אינון ניצוחיא. והיינו, שבסוכות נתגלה דאנן ניצוחיא, ובאופן גלוי לכל יושבי תבל, עד שכל מציאות העולם רואה שאנן ניצוחיא. ואע\"פ שהנצחון דישראל כבר הי' בראש השנה, וכמאמר המדרש<sup data-n=\"1304\">23</sup> איזו אומה כאומה זו שיודעת אופי' של אלקי', שישראל יודעים שהקב\"ה יעשה להם נס ויזכו בדין, וא\"כ דבר פשוט הוא שביום ראש השנה הי' להם כתיבה וחתימה טובה, מ\"מ תכלית הכוונה והשלימות הוא שנצחון זה יהי' בגילוי. וזה נעשה בחג הסוכות, בכסה ליום חגינו, שהנצחון שהי' בכסה (בהעלם) בראש השנה נמשך בגלוי ביום חגינו, ועי\"ז באים לתכלית השלימות.\nה) <b>והנה</b> יום הכפורים נקרא ראש השנה בקרא<sup data-n=\"1305\">24</sup> כמובא בלקו\"ת<sup data-n=\"1306\">25</sup>. ובסדר הימים הנה יום הכפורים הוא בעשור לחדש השביעי, ובתחלת החדש, באחד לחדש השביעי הוא ראש השנה. ויתירה מזו, הנה אמרז\"ל<sup data-n=\"1307\">26</sup> אלו עשרה ימים שבין ראש השנה ליום הכפורים, היינו שראש השנה ויום הכפורים נכללים באותן עשרת הימים<sup data-n=\"1308\">27</sup> (וענינם ענין אחד). ומזה מובן שביום הכפורים נמשך ענין מיוחד השייך לההמשכה דראש השנה. והענין הוא, כמבואר בלקו\"ת<sup data-n=\"1306\">25</sup> שביום הכפורים הוא ההמשכה דבחי' נשמה ופנימיות, וכיון שההמשכה בבחי' פנימיות היא בענין עיקרי, מובן שגם בכל שאר הענינים ההמשכה דיום הכפורים היא בבחי' פנימיות. אמנם גם המשכה זו שביום הכפורים עדיין היא באופן דבכסה. וההמשכה באופן דאנן ניצוחיא ובגלוי [עד שהוא גילוי באופן כזה שנעשה על ידה זמן שמחתנו, ששמחה היא על דבר שבגלוי דוקא, כידוע<sup data-n=\"1309\">28</sup>] היא ביום חגינו (חג הסוכות) דוקא, בחמשה עשר לחדש, כשקיימא סיהרא באשלמותא, כמבואר בכ\"מ.ו) <b>ובזה</b> יובן מה שמצינו קשר בין תקיעת שופר לסוכות, וכידוע<sup data-n=\"1310\">29</sup> שסכך [דכל סוכות הכתוב סכך משמע<sup data-n=\"1311\">30</sup>, וכמו שמבאר כ\"ק אדמו\"ר הזקן בשו\"ע הל' סוכה<sup data-n=\"1312\">31</sup> דאין נקרא סוכה אלא הסכך בלבד. דהיינו, שלא רק שהסכך הוא עיקר הסוכה אלא עוד זאת שבענין הסכך מתבטא (גיט זיך ארויס) כל ענין הסוכה] בגימט' מאה, כנגד מאה קולות דשופר שנהגו ישראל<sup data-n=\"1313\">32</sup> לתקוע בראש השנה. וטעם הדבר הוא כנ\"ל היות שענין הסוכה נמשך ע\"י התקיעת שופר דראש השנה. שבראש השנה ההמשכה (שממשיכים בתקיעת שופר ע\"י המאה קולות) היא באופן דבכסה (בהעלם) ואח\"כ באה לידי גילוי בחג הסוכות (ליום חגינו) בסכך הסוכה. ועד\"ז הוא גם בנוגע ליום הכפורים, כידוע שסכך הסוכה הוא דוגמת ענני הכבוד [כהדעה בגמרא<sup data-n=\"1314\">33</sup> ענני כבוד היו, וכן הובא לפסק הלכה בשו\"ע אדה\"ז בהל' סוכות בתחלתם], והוא נמשך מענן הקטרת דיוה\"כ. וביאור הענין הוא, כנ\"ל דתחלה באה ההמשכה דראש השנה בבחי' פנימיות ביום הכפורים. והמשכה זו שביום הכפורים היא ע\"י ענין הקטרת שממנו הי' צ\"ל וכסה ענן הקטרת את הכפרת<sup data-n=\"1315\">34</sup>, ובכללות יותר זהו ע\"י כללות עבודת כהן גדול ביום הכפורים בקדש הקדשים. ומענן הקטרת שביום הכפורים נמשך אח\"כ סכך הסוכה (שהסוכה היא ע\"ש ענני הכבוד).\nז) <b>וע\"פ</b> הנ\"ל יובן הביאור והנקודה שבכל הענינים האמורים. והענין הוא, דהנה עבודת יום הכפורים בקה\"ק היא בהזמן הנק' בכתוב<sup data-n=\"1316\">35</sup> אחת בשנה. וכמו שבזמן הוא בחי' אחת שבזמן, כן הוא גם בנפש ובעולם (במקום) שהיא בבחי' אחת בנפש ובמקום. שהעבודה נעשית ע\"י הכהן גדול שהוא המקודש ובחי' אחת שבעם ישראל, וכמ\"ש<sup data-n=\"1317\">36</sup> ויבדל אהרן להקדישו קדש קדשים, והעבודה היא בקה\"ק, המקום המקודש מכל העולם כולו, גם ממקום הקדש שבביהמ\"ק (ההיכל). והנה על ג' הענינים דעש\"ן מיוסד כל סדר ההשתלשלות כמו שנמשך משרשו ומקורו [ולכן מיוסד ספר יצירה על ג' בחי' אלו], עד לכמו שהבריאה היא מעצומ\"ה ית'. וכדאיתא באגה\"ק<sup data-n=\"1318\">37</sup> שמהותו ועצמותו של המאציל ב\"ה שמציאותו מעצמותו ואינו עלול מאיזה עילה שקדמה לו ח\"ו כו' הוא לבדו בכחו ויכלתו לברוא יש מאין ואפס המוחלט ממש. וזהו\"ע בחי' אחת בשנה, בעולם (מקום), ובנפש, שמתאחדות יחד בעבודת כהן גדול ביום הכפורים בקה\"ק, בחי' עצומ\"ה ית' שנמשך בבחי' עש\"ן. ובחי' אחת נמשכת בגלוי אח\"כ בסוכות. דהנה מבואר במשנה<sup data-n=\"1319\">38</sup> בסדר עבודת יוםהכפורים שהכהן גדול הי' ממתין בקה\"ק עד שהי' הבית מתמלא עשן, ומעשן זה (שמהעבודה דבחי' אחת) נמשך סכך הסוכה בחג הסוכות<sup data-n=\"1320\">39</sup>.\nח) <b>והנה</b><b>,</b> התחלת ההמשכה דבחי' אחת היא בראש השנה, שאז היא העבודה דתמליכוני עליכם, שממשיכים המלוכה מבחי' התנשאות עצמי, דהיינו דכמו שהוא בבחי' עצמי יומשך בגלוי עד שיהי' תמליכוני עליכם, וע\"י שממשיכים להיות מלך ישראל (שתמליכוני עליכם) נמשך אח\"כ להיות מלוך על כל העולם כולו בכבודך. ואופן המלוכה היא ברצון, ולא רק שומלכותו בכל משלה. דממשלה אפשר להיות גם בהכרח בלא רצון, אבל ישראל ע\"י עבודתם דומלכותו ברצון קבלו עליהם, ממשיכים בכל המציאות כולה, בכל סדר ההשתלשלות, להיות בואו נשתחוה ונכרעה נברכה לפני הוי' עושינו<sup data-n=\"1321\">40</sup>. ואח\"כ בעשור לחודש השביעי באה ההמשכה בבחי' פנימיות. ואח\"כ בחג הסוכות באה ההמשכה בגלוי. שהנצחון שהי' בראש השנה, החל מהנצחון שממלך ישראל נמשך להיות ומלכותו בכל משלה, ולמעלה יותר, גם מלכותו ברצון קבלו עליהם, הנה נמשך בגלוי עד שנמשך בגלוי גם בעולם וגם בהשבעים אומות, דלכן מקריבים בחג הסוכות ע' פרים כנגד הע' אומות<sup data-n=\"1322\">41</sup>. והנה המשכה זו נמשכת בגלוי (בהד' ימים שבין יום הכפורים לסוכות) תחלה בתורה ומצוותי' ע\"י לימוד הלכות סוכה וע\"י לימוד הלכות נטילת ד\"מ, כי ע\"י הלימוד בזה אף שהוא בגלות, ואפי' שאין שייך קיום כל הפרטים כולם, הנה נעשה כמארז\"ל<sup data-n=\"1323\">42</sup> מעלה אני עליהם כאילו הם עסוקים כו'. וע\"י שפועל תחלה ההמשכה בגלוי בתורה, ואח\"כ ממשיך זה גם במעשה ע\"י קיום המצוות [אלא שזהו עדיין בחי' המעשה שבמצוות עצמן], הנה נמשך אח\"כ בפועל גם בכל העולם כולו, שכל העולם רואה איך שיהודי מקיים המצוה. ועד שנמשך באופן כזה, שאיתא במדרש<sup data-n=\"1324\">43</sup> דאילו הי' אומות העולם יודעים מה הי' המקדש יפה להם קסטריות היו מקיפים אותו כדי לשמרו כו'. ופעולה זו דהמקדש על האומות היא בחג הסוכות באופן גלוי ע\"י הקרבת ע' פרים כנגד שבעים אומות, כמבואר בארוכה במדרשי רז\"ל<sup data-n=\"1325\">44</sup>.\nט) <b>והנה</b><b>,</b> ע\"פ הנ\"ל שענין הסוכה שייך לבחי' אחת בשנה, ובעולם (במקום) ובנפש, מובן ג\"כ מה שבנוגע לסוכות (דוקא) נאמר כל האזרח בישראל גו' ועד\"ז דרשו רז\"ל<sup data-n=\"1326\">45</sup> ראוים כל ישראל לישב בסוכה אחת, כי המשכת בחי' אחת בגלוי היא בחג הסוכות. וביאור הענין יובן בהקדם מה שצלה\"ב בזה [וכמבואר דיוק זה גם במאמרי רבותינו נשיאינו&lt;2&gt;], מפני מה הלימוד הזה דכל ישראל ראוים לישב בסוכה אחת הוא דוקא מכל האזרח בישראל גו', הלא גם מבסוכות תשבו יש ג\"כ ללמודלימוד זה דתשבו כולכם יחד. וכללות הביאור בזה (בל' הקבלה), דהנה בתחלה [היינו קודם הצמצום] הי' אוא\"ס ממלא כל מקום החלל ולא הי' מקום לעמידת העולמות [והיינו שלא הי' אפשריות ומציאות לעולמות], ואח\"כ סילק אורו הגדול על הצד כו' ונמשך (עיגול הגדול ו)הקו, וכל אריכות סדר ההשתלשלות, כמבואר בע\"ח בתחלתו ובמבוא שערים בתחלתו (כמובא בכ\"מ ונתבאר בחסידות). והנה בחי' זו (שהי' ממלא מקום החלל כו' לפני הצמצום) נקראת כבר בשם אוא\"ס, ועד שאפשר להיות שם איזה שייכות למציאות דעולמות, אלא שכיון שהי' אוא\"ס ממלא כל מקום החלל משו\"ז לא הי' אפשרות למציאות העולמות. אבל גם שם הרי ישנו חלל, וגם ישנה האפשריות שצריך לשלול ולומר שאאפ\"ל מציאות לעולמות. ולמעלה מזה הוא מה שארז\"ל<sup data-n=\"1327\">46</sup> עד שלא נבה\"ע הי' הוא ושמו בלבד. אמנם, גם במדרגה זו (כבר) ישנם פרטים, הוא, ושמו, ובלבד, וגם אומרים שהחידוש שבמדרגה זו היא שהיא באופן דהי\"ה, כמבואר בהמאמר שלפנ\"ז<sup data-n=\"1328\">47</sup>. אמנם מהותו ועצמותו ית' הוא למעלה גם מזה, ועד שאא\"פ לומר עליו שהוא בבחי' סובב (לעולמות) ואפי' גם לא בבחי' מקיף הרחוק וכיו\"ב. כי מהותו ועצמותו ית' אינו בגדר כל הענינים כלל, עד שהוא בבחי' אין עוד מלבדו, ולמעלה יותר, דאין עוד. דהרי אין עוד מלבדו שייך לומר כשישנו גדר של לבדו, אמנם למעלה מזה הו\"ע אין עוד, כמבואר במקום אחר דיוק זה. והנה כיון שישראל מושרשים בעצומ\"ה ית', מובן שיש להם שייכות ואפשר להם להגיע ולפעול בעצומ\"ה ית', גם כמו שהוא למעלה בבחי' אי\"ע אפי' מבחי' הי' הוא ושמו בלבד. וזהו משארז\"ל<sup data-n=\"1329\">48</sup> במי נמלך בנשמותיהן של צדיקים, שענין ההמלכה שייך לומר למעלה מעלה, וגם בהבחי' שלמעלה מגדר מקום. כי מכיון שלמעלה כל הענינים הם ברצון ולא בהכרח ח\"ו, מובן שגם במדרגה זו שייך ענין ההמלכה. ומזה מובן שענין ההמלכה היא כביכול גם בעצומ\"ה ית'. וע\"ז אומרים במי נמלך בנשמותיהן של צדיקים, שזה קאי על נשמות ישראל, ועמך כולם צדיקים<sup data-n=\"1330\">49</sup>, שמושרשים בעצומ\"ה ית' ולכן גם מגיעים לעצומ\"ה ית'. וענין ההמלכה היא גם בהנשמות הקטנות במדרגה לכאו', כמובן ממשל הה\"מ נ\"ע<sup data-n=\"1331\">50</sup> שמדמה ענין זה לאב ובן קטן, ומכיון שממשיל את הקב\"ה לאב, כביכול, מובן שגדול וקטן שוים לגבי'. שכל הענינים הם שלא בערך כלל לעצומ\"ה ית', אלא שכך עלה ברצונו שנשמות ישראל, ועמך כולם צדיקים, יהיו מושרשים בעצומ\"ה אַליין, ומשו\"ז מושרשים נשמות ישראל בעצומ\"ה ית'.\nי) <b>והנה</b><b>,</b> כיון שהיא התחלת השנה וצריכים להמשיך את כל סדר ההשתלשלות מחדש וגם באופן גלוי, לכן צריך להמשיך מבחי' אחת. והמשכה זו (בבחי' גילוי) נעשית ביום חגינו (בחג הסוכות) כנ\"ל, ולכן גם התחלת העבודה דסוכות צ\"ל בהענין דסוכה אחת (שהסוכה אחת שייכת לעבודת יום הכפורים בג'בחינות אחת שבעש\"ן, כנ\"ל), כי ע\"י העבודה דסוכה אחת הנה מגיעים לבחי' אחת שלמעלה לגמרי אפי' מכל גדר ענין המספר (אלא שכיון שאין לנו שם אחר לקרותו משו\"ז קורין אותו אחת), לעצומ\"ה ית'. דאחת פי' יחידה כדאיתא בתוס'<sup data-n=\"1332\">51</sup>, והשם יחידה הוא ע\"ש שמקבלת מיחיד. וכמו\"כ הוא בבחי' סוכה אחת שענינה הו\"ע היחידה, כנ\"ל. וכיון שענין הסוכה שרשה מבחי' אחת, לכן נמשך למטה שראוים כל ישראל לישב בסוכה אחת, שהסוכה היא למעלה מכל התחלקות היות ששרשה הוא בבחי' שלמעלה מהתחלקות. ומצד טעם זה גופא נמשך בחי' הסוכה אחת גם בעוה\"ז התחתון שאין תחתון למטה ממנו, כיון שבערך עצומ\"ה ית' אין שייך לחלק בין עליון לתחתון.\nיא) <b>והנה</b><b>,</b> המשכת העצמות בגלוי (בחי' סוכה אחת) יהי' רק לע\"ל, שהרי אז יהי' ונגלה כבוד הוי' וראו כל בשר יחדיו<sup data-n=\"1333\">52</sup>, ולמעלה מזה יהי' גם ולא יכנף עוד מוריך והיו עיניך רואות את מוריך<sup data-n=\"1334\">53</sup>, כדאיתא בתניא<sup data-n=\"1335\">54</sup>. אמנם למעלה מזה הוא בחי' אחת, שענינה הוא המשכת העצמות למטה בגלוי, ומזה מובן שגם הגילוי דסוכה אחת יהי' רק לע\"ל. ועפי\"ז מובן למה דרשו רז\"ל שראוים כל ישראל לישב בסוכה אחת ממ\"ש בסיום הכתוב כל האזרח בישראל גו' דוקא, ולא דרשו כן מההתחלה דבסוכות תשבו שבעת ימים, כי בסוכות תשבו שבעת ימים קאי על העבודה בזמן הזה בהשיתא אלפי שני דהוה עלמא, ובזמן הזה הרי עדיין לא נמשך בחי' אחת בגלוי. וגילוי זה יהי' רק לע\"ל ומשו\"ז דרשו זה ממ\"ש כל האזרח בישראל גו', כי אזרח הוא ל' עתיד, דהיינו מה שיזרח לע\"ל, כמבואר בכמה דרושים<sup data-n=\"1336\">55</sup>. וכן הוא גם ע\"פ כללי הדקדוק שאותיות איתן מורים על העתיד<sup data-n=\"1337\">56</sup>. וזהו כל האזרח בישראל גו', שלע\"ל תהי' זריחה דבחי' אחת, ולכן ישבו אז כל ישראל בסוכה אחת. אמנם, אעפ\"כ גם עכשיו, בהשית אלפי שני דהוה עלמא, מאירה הארה וזריחה מבחי' אחת שתהי' בגילוי לע\"ל. ועוד זאת, גילוי בחי' אחת שלעתיד נמשך (כשאר הגילויים דלעתיד<sup data-n=\"1338\">57</sup>) ע\"י מעשינו ועבודתינו דעתה דוקא. ומזה מובן שגם עתה ישנו מעין והארה מבחי' אחת<sup data-n=\"1339\">58</sup>. וזהו משארז\"ל שראוים כל ישראל לישב בסוכה אחת, שקאי על זמן הזה, שגם בזמן הזה ישנו הענין שראוים כל ישראל לישב בסוכה אחת (מעין דהישיבה בפועל לע\"ל). אלא שזה גופא שבזמן הזה ראוים כו' לישב נלמד ממ\"שכל האזרח גו' (ל' עתיד), היינו שלוקח הכח ונמשך מהזריחה שתהי' לע\"ל, שיהי' גילוי העצמות, כמ\"ש לא יכנף עוד מוריך.\nיב) <b>והנה</b> ע\"פ הנ\"ל יובן גם הסדר בהעבודות דראש השנה יום הכפורים וסוכות. והענין הוא, ע\"ד הסדר בתומ\"צ דכללות ופרטות נאמרו, דתחלה הענינים הם באופן של כלל ואח\"כ נמשכים לפרטים, הנה כמו\"כ הוא בסדר העבודה דראש השנה יום הכפורים וסוכות. דהנה התורה בשלימותה היא בריבוי פרטים, כמ\"ש<sup data-n=\"1340\">59</sup> ששים המה מלכות ושמנים פלגשים ועלמות אין מספר, ודרז\"ל<sup data-n=\"1341\">60</sup> דששים המה מלכות אלו המשניות, ושמנים פלגשים אלו הברייתות ועלמות אין מספר אלו דרשות חז\"ל ומימרות ה(תנאים ו)אמוראים. ולפנ\"ז ישנה התורה כמו שהיא בתושב\"כ, כל' הרגיל בש\"ס מנא הני מילי דאמר קרא. דכ\"ז הו\"ע התורה כמו שהיא באופן של פרטים ופרטי פרטים. אמנם ישנו גם כמו שהתורה היא באופן של כלל, דכללותי' ודקדוקי' כולם נאמרו מסיני<sup data-n=\"1342\">61</sup>. ובאמירת הכללים והפרטים עצמם, הנה תחלה נאמרו הכללים, ואח\"כ הפרטים. דתחלה נאמרו עשה\"ד שבהם נכללו כל פרטי התורה. ועשה\"ד עצמן כלולים בהדברות אנכי ולא יהי' לך, כדאיתא בתניא<sup data-n=\"1343\">62</sup>. וב' דברות אלו כלולות<sup data-n=\"1344\">63</sup> באנכי שהיא תיבה הראשונה שבדיבור הראשון. ובאנכי גופא אות אל\"ף הוא הר\"ת שלה. ובאל\"ף זו כלולים כל כללי התורה. דאות אל\"ף מורה על ענין של כלל, דהנה איתא בירושלמי<sup data-n=\"1345\">64</sup> שהדיבור דאנכי נרמז במ\"ש<sup data-n=\"1346\">65</sup> שמע ישראל ה' אלקינו, וידוע בביאור תיבת אחד שהח' מרמזת לז' רקיעים וארץ והד' לד' רוחות העולם, והא' שלפניהם היא כנגד הקב\"ה אלופו של עולם, כמובא בב\"י<sup data-n=\"1347\">66</sup> מהסמ\"ק, כמובא ומבואר בכ\"מ<sup data-n=\"1348\">67</sup>. ומזה מובן שהאל\"ף דאנכי (השייך לאחד דשמע ישראל) הוא כלל הכולל את כל התורה כולה.\nיג) <b>ועד\"ז</b> הו\"ע סדר העבודות דראש השנה יום הכפורים וסוכות (שתחלת ההמשכה היא באופן של כלל ואח\"כ נמשכת בפרטים). דהנה על ראש השנה (שאז הוא בבחי' כללות ביותר) ארז\"ל<sup data-n=\"1349\">68</sup> דמצות היום בשופר. דאע\"פ שיום זה הוא נורא ואיום וקדוש, מ\"מ מצותו רק מצוה אחת, ובהמצוה עצמה הנה כל הקולות כשרים בשופר<sup data-n=\"1350\">69</sup>. כי מצות ראש השנה הוא אך ורק ענין אחד. ואפי' בשכל וסברת המצוה הנה היא למעלה מפרטים, וכל' הרמב\"ם<sup data-n=\"1351\">70</sup> שתקיעת שופר בראשהשנה גזירת הכתוב היא היינו למעלה מתפיסת והשגת השכל. דבתפיסה והשגה צ\"ל מדידה וקצוות, כמובן ופשוט, אמנם תקיעת שופר שהיא למעלה מתפיסה והשגה (גזירת הכתוב) היא למעלה ממדידה וקצוות. ועד\"ז הוא ג\"כ בענין עבודת יום הכפורים, דאע\"פ שיש בו ריבוי עבודות, מ\"מ העבודה המיוחדת שבו היא העבודה דוכסה ענן הקטורת, כנ\"ל. דעבודה זו היא בקה\"ק, בחי' אחת במקום, ובהזמן דאחת בשנה, וע\"י הכהן גדול בחי' אחת בנפש. ועוד זאת, שהקטורת צ\"ל אז באופן דדקה מן הדקה<sup data-n=\"1352\">71</sup>. ואע\"פ שעבודת הקטורת בכלל היתה צ\"ל מן הדקה, מ\"מ אי\"ז כמעלת הקטורת ביום הקדוש, אחת בשנה, שאז הקטורת היא באופן של דקה מן הדקה, שזה מראה שמגיעים אל נקודת המציאות. ואח\"ז באה ההמשכה בפרטיות, ובהפרטים עצמם אופן ההמשכה היא מדרגה לדרגה. דתחלת ההמשכה היא בהסוכה (דסוכה ע\"ש סככה נקראת). דהמשכה זו היא למעלה מהתחלקות עדיין, שהרי בהסכך אינו שייך לחלק, משא\"כ בהדפנות וכיו\"ב. ואופן ההמשכה שבהסכך היא כשמה, סכך ע\"ש שסוכך על האדם מלמעלה, עד שזה גופא (שסוכך מלמעלה) הוא באופן של צל דוקא ולא של אור נגלה. ודוקא אז, כשצלתה מרובה כו'<sup data-n=\"1353\">72</sup> מקיים מצות סוכה. אמנם אח\"כ צריך להמשיך המשכה זו גם בפרטים. וזהו ענין המצוה דתשבו כעין תדורו, שצריך להכניס תחת צל הסוכה כל עניני חייו בכל פרטיהם ופרטי פרטיהם, ועי\"ז עושים מכל פרט ענין של מצוה. והיינו, דהגם שבמשך כל השנה כולה צריכים לעבודה גדולה עד שיהי' בכל דרכיך דעהו<sup data-n=\"1354\">73</sup>, והחכם<sup data-n=\"1355\">74</sup> יהי' ניכר באכילתו ובשתייתו ובמשאו ומתנו כו'<sup data-n=\"1356\">75</sup>, אמנם בחג הסוכות, מצד עצם קיום המצוה (גם בלא העבודה דבכל דרכיך דעהו), כשעושה דברים אלו בסוכה ה\"ה מקיים המצוה דבסוכות תשבו (אף שהם ענינים של אכילה ושתי' ומשא ומתן כו', כנזכר ברמב\"ם הנ\"ל). ולאח\"ז צריך להמשיך המשכה זו (בחי' אחת שבהסוכה אחת שיאיר בגלוי לע\"ל, כנ\"ל במ\"ש כל האזרח בישראל ישבו בסוכות) בעומק יותר, שיהי' נמשך בפנימיות הנפש (גם עתה). וזהו\"ע המצוה דולקחתם לכם גו' (מצות ד' מינים), שצ\"ל ענין של לקיחה, והלקיחה צ\"ל לכם, להגיע אל החזה, ועי\"ז נמשכת ההמשכה בלבו פנימה, או כלשון הידוע<sup data-n=\"1357\">76</sup> שממשיך בנוקבא דז\"א העומדת בחזה דז\"א כמבואר בארוכה בהדרושים<sup data-n=\"1358\">77</sup> ובפרט בדרושי בעל ההילולא&lt;39&gt;.\nיד) <b>והנה</b><b>,</b> ע\"פ הנ\"ל שע\"י נטילת הד\"מ נמשך בפנימיות בחי' אחת (שנמשכה תחלה ביום הכפורים ע\"י העבודה בהג' בחי' אחת בעש\"ן, ואח\"כ בהסוכה אחת), מובן שגם כשההמשכה באה בפרטים (במצות ד\"מ), ה\"ז פרטים שבהם ניכר ונגלה ומודגש הענין דאחת. והענין הוא, כמבואר בארוכה בהמשך וככהדבעל ההילולא<sup data-n=\"1359\">78</sup> שבד\"מ אלו ניכר ענין האחדות. דבהלולב כפות תמרים חסר כתיב ודרז\"ל<sup data-n=\"1360\">79</sup> שצ\"ל כפות. דאע\"פ שבהלולב צ\"ל כו\"כ עלים מ\"מ בכדי לקיים המצוה צריך לכפותם זל\"ז. וגם כל עלה כפול מב' שג\"ז מורה על היותם באחדות כו', וגם מורה על השלימות. וזהו שבהלולב נראה בגלוי ענין האחדות. וכן הוא בההדסים שנק' ענף עץ עבות, עבות דוקא, להיות שצ\"ל תלתא בחד קינא<sup data-n=\"1361\">80</sup>, דהיינו שצ\"ל ג' לכה\"פ אבל בחד קינא דוקא. שזה מורה ג\"כ על האחדות. ולכן נק' ענף ל' יחיד, וגם עבות, שמורה על אחדות. וכן הערבה (ערבי נחל) נק' ג\"כ אחוינא בגמרא<sup data-n=\"1362\">81</sup> ע\"ש שגדלים באחוה אגודות אגודות. דאע\"פ שהם ערבי (נחל), ל' רבים, מ\"מ גם כמו שכל ערבה צומחת בפני עצמה, היא מתאחדת עם האחרות באחוינא, מל' איחוי. שזה מורה על ענין האחדות. ויתירה מזו ועולה על כולנה היא האחדות שבאתרוג, ומשו\"ז נזכר ראשון בקרא, ולקחתם גו' פרי עץ הדר. והענין הוא, דהנה בגמרא<sup data-n=\"1363\">82</sup> דרשו דמ\"ש פרי עץ הדר קאי על אתרוג משום שדר באילנו משנה לשנה. דבשנה שלימה יש חילוף הזמנים מן הקצה אל הקצה, והאתרוג סובל את כולם. ומוסיף ע\"ז בעל ההילולא דיוק נוסף<sup data-n=\"1364\">83</sup>, שלא רק שהאתרוג סובל שינויי הזמנים<sup data-n=\"1365\">84</sup> כ\"א עוד זאת שהוא גדל מהם. ומביא כהוכחה ע\"ז דבר נפלא, כי היותו דר בלתי גידול זה אי אפשר, שהי' מתקלקל ח\"ו [היות שהאתרוג הוא צומח]. ומזה הוכחה שאדרבה, האתרוג גדל מזה גופא שעוברים עליו ד' זמני השנה. וזהו\"ע האחדות שבהאתרוג, שבו מתאחדים כל שינויי זמני השנה באופן כזה עד שדוקא ע\"י כולם הוא גדל עד שנעשה פרי עץ הדר [ועד שמההדר שנאמר באתרוג למדים ההידור בשאר הג' מינים]. ועד\"ז ישנה האחדות בהד\"מ בענינם בעבודה רוחנית בנפש. דהנה ידוע מה דאיתא במדרש<sup data-n=\"1366\">85</sup> שהד\"מ שבלולב הם כנגד הד' סוגים שבישראל, החל מהסוג שכנגד האתרוג שיש בו טעם וריח (תורה ומע\"ט) עד להסוג שכנגד הערבה שאין בו לא טעם ולא ריח. וצריך לאחד את כל הסוגים, ודוקא עי\"ז שויעשו כולם אגודה אחת אז נעשה לעשות רצונך בלבב שלם, וכמו שהוא בפשטות שדוקא ע\"י התאחדות כל המינים אפשר לקיים מצות ד\"מ, ועי\"ז הוא התחלת יום חגינו באופן דושמחתם לפני ה\"א&lt;7&gt;, ומזה ממשיך האדם אח\"כ בעבודתו בכל השנה כולה.\nטו) <b>והנה</b> ע\"פ הנ\"ל מובנים פרטים הנ\"ל, ושייכות מצות לקיחת ד\"מ למצות ישיבה בסוכה, וגם הסדר שבמצות אלו. שלאחר שקיים המצוה דבסוכות תשבו, דהיינו שנמשכה אצלו באופן של התיישבות בחי' הסוכה אחת כמו שמאירה ונותנת כח עד שנמשכת גם בזה\"ז עוד לפני שיהי' המשכת העצמות לעת\"ל (שעז\"נכל האזרח גו', ל' עתיד), הנה לאח\"ז ע\"י לקיחת הד\"מ ממשיכים המשכה זו בבחי' פנימיות. וע\"י ההמשכה בפנימיות שע\"י הד\"מ הנה בא לענין שמחת בית השואבה. וכמבואר בארוכה ע\"י בעל ההילולא<sup data-n=\"1367\">86</sup> שע\"י הד\"מ הנה פועלים שמחה באופן דושאבתם מים בששון<sup data-n=\"1368\">87</sup>, שגם במים יש שמחה. דאע\"פ שאין שמחה אלא ביין<sup data-n=\"1369\">88</sup>, מ\"מ יהודי על ידי עבודתו בלקיחת הד\"מ פועל בהמים שיהי' ענין ניסוך המים ועי\"ז נעשה ענין השמחה, ושאבתם מים בששון, ועד שמי שלא ראה שמחת בית השואבה לא ראה שמחה מימיו<sup data-n=\"1370\">89</sup>. ואדרבה, בכדי שיראה שמחה בימיו צריך לראות ולקחת כח והסברה, וגם הסברה בשכל, משמחת בית השואבה.\nטז) <b>וזהו</b> מ\"ש בסוכות תשבו שבעת ימים כל האזרח בישראל ישבו בסוכות, שלאחרי העבודה דתקעו בחודש שופר בראש השנה, שאז ההמשכה היא עדיין באופן דבכסה, הנה אח\"ז באים העשרה ימים שבין ראש השנה ליום הכפורים שעליהם נאמר<sup data-n=\"1371\">90</sup> דרשו הוי' בהמצאו קראוהו בהיותו קרוב, ואמירתו של הקב\"ה חשיב מעשה<sup data-n=\"1372\">91</sup>, ונעשה מעשה בפועל, שנעשה דרשו וקראוהו בפועל. וזה פועל אח\"ז הד' ימים שבין יום הכפורים לסוכות, שאז תורת אמת מעידה שכל ישראל וכל א' מישראל עסוקים במצוות<sup data-n=\"1373\">92</sup>, ולאחרי ההכנה (בד' ימים אלו) דחג הסוכות תעשה לך וגו'<sup data-n=\"1374\">93</sup> (עם כל הפירושים שבזה) [שגם עשיית הסוכה הוא בכלל המצוה, כמ\"ש אדמו\"ר הזקן בשו\"ע שלו<sup data-n=\"1375\">94</sup> לפסק הלכה בטעם הפס\"ד שאין מברכין על עשייתה מפני שאינה <i>גמר</i> המצוה, וברכת שהחיינו קאי גם על העשי'] הנה באים אח\"כ בחג הסוכות לקיום המצוה עצמה, בסוכות תשבו שבעת ימים. ומיד למחרת בבקר (בעלות השחר ובנץ החמה) באה מצות ד\"מ, ולקחתם לכם ביום הראשון פרי עץ הדר כפות תמרים וענף עץ אבות וערבי נחל ושמחתם לפני הוי' אלקיכם. עד שבאים לשמחת בית השואבה, שנעשה גודל השמחה דושמחתם באופן דמי שלא ראה שמחת בית השואבה לא ראה שמחה מימיו. ואז זוכים שבקרוב ממש יהי' כל האזרח בישראל ישבו בסוכות בפועל (ולא רק ראוים לישב), כי באה הגאולה האמיתית והשלימה ע\"י משיח צדקנו. ואז יהי' קיום המצוה דושמחתם לפני ה\"א בשלימות ומה\"ת, שיהי' קיומה בביהמ\"ק, ביהמ\"ק השלישי, מקדש אדנ\"י כוננו ידיך<sup data-n=\"1376\">95</sup>, בקרוב ממש. יבא ויגאלנו ויוליכנו קוממיות לארצנו, ויבנה ביהמ\"ק במקומו, ויקבץ נדחי ישראל והיתהלה' המלוכה<sup data-n=\"1377\">96</sup>. ובהקדמה לזה יהי' כמ\"ש<sup data-n=\"1378\">97</sup> אז אהפוך אל עמים שפה ברורה גו' ולעבדו שכם אחד<sup data-n=\"1379\">98</sup>, שזה נמשך בגלוי ע\"י הקרבת השבעים פרים בחג הסוכות. כן תהי' לנו, ובקרוב ממש.\n**********",[["1281","*","יצא לאור בשעתו, \"<i>שלהי תשרי</i>,<i> ה'תשל\"ח</i>\"."],["1282","1","אמור כג, מב."],["1283","2","בד\"ה זה דשנת תרצ\"ד (סה\"מ תיש\"א ע' 50)."],["1284","3","סוכה כח, ב. שו\"ע (ואדה\"ז) או\"ח רסתרל\"ט."],["1285","4","משנה ריש סוכה. שו\"ע או\"ח רסתרל\"ג."],["1286","5","גמרא שם."],["1287","6","שם ט, רע\"ב."],["1288","7","אמור שם, מ."],["1289","8","ב\"י לטור או\"ח רסתרנ\"ב. שו\"ע שם."],["1290","9","סידור אדה\"ז (לפני הלל)."],["1291","10","ראה ד\"ה ולקחתם לכם תרצ\"ו (סה\"מ קונטרסים ח\"ג ע' קפב)."],["1292","11","שו\"ע שם."],["1293","12","סוכה מא, א."],["1294","13","ד\"ה הנ\"ל. וככה תרל\"ז פפ\"ד. ועוד."],["1295","14","ראה ר\"ה לא, א. וראה שו\"ע אדה\"ז או\"ח סתרמ\"ה ס\"ב."],["1296","15","ויק\"ר פי\"ג, ג. ועוד."],["1297","16","סוכה מח, רע\"א."],["1298","17","ראה ט\"ז או\"ח סתרס\"ח סק\"א, שרק לענין פז\"ר קש\"ב הוא חלוק מסוכות, אבל \"בלא\"ה חד חג הוא\"."],["1299","18","וראה ד\"ה וככה פט\"ו. ספכ\"א."],["1300","19","תהלים פא, ד."],["1301","20","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380938\" data-slug=\"likkutei-torah\" data-id=\"4001380938\">לקו\"ת ר\"ה נד, רע\"ד</a>. סד\"ה לולב וערבה תרס\"ו. ועוד."],["1302","21","משלי ז, כ."],["1303","22","ויק\"ר פ\"ל, ב."],["1304","23","ירושלמי ר\"ה פ\"א ה\"ג. הובא בטואו\"ח סתקפ\"א."],["1305","24","יחזקאל מ, א."],["1306","25","שם נח, א. סד, א."],["1307","26","ר\"ה יח, א."],["1308","27","ראה לקו\"ש ח\"ד ע' 1144."],["1309","28","כ\"ה בכ\"מ, ובהמשך ד\"ה שמח תשמח (תרנ\"ז) בתחלתו בארוכה. ובתו\"א (ח, ג): וענין ומהות השמחה שיכול להיות על הטוב אף כשהוא נעלם ומכוסה מעיניו (משא\"כ תענוג). ואכ\"מ."],["1310","29","מ\"ח ופע\"ח שער הסוכות בסופו. וככה תרל\"ז ספצ\"ג. וראה תולוי\"צ ע' שג."],["1311","30","רש\"י סוכה יב, א ד\"ה כשרין. וראה רש\"י שם ב, א ד\"ה ושחמתה."],["1312","31","סתרל\"ח ס\"א."],["1313","32","שם סתקצ\"ו ס\"א."],["1314","33","סוכה יא, ב."],["1315","34","אחרי טז, יג."],["1316","35","ס\"פ תצוה. אחרי טז, לד."],["1317","36","דברי הימים-א כג, יג."],["1318","37","ס\"כ."],["1319","38","יומא נב, ב."],["1320","39","וככה פפ\"ד."],["1321","40","תהלים צה, ו. וראה זח\"א רכא, ב. ח\"ג קז, ב. פרדר\"א פי\"א."],["1322","41","סוכה נה, ב. במדב\"ר פכ\"א, כד. הובא בפרש\"י עה\"ת פינחס כט, לה. וראה בארוכה ד\"ה בסוכות תשבו תשל\"ו ס\"ח (לעיל ס\"ע קל ואילך)."],["1323","42","תנחומא צו יד."],["1324","43","במדב\"ר פ\"א, ג."],["1325","44","ראה בהנסמן בהערה 41. ובפרש\"י לסוכה שם ד\"ה שבעים פרים."],["1326","45","סוכה כז, ב."],["1327","46","פרדר\"א פ\"ג."],["1328","47","ד\"ה מן המיצר דיום ב' דר\"ה."],["1329","48","רות רבה רפ\"ב."],["1330","49","ישעי' ס, כא."],["1331","50","לקו\"א ואו\"ת בתחלתו."],["1332","51","מנחות יח, א ד\"ה עד אחת."],["1333","52","ישעי' מ, ה."],["1334","53","שם ל, כ."],["1335","54","פל\"ו."],["1336","55","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת ראה יח, א</a>. שמע\"צ פח, ג. ובכ\"מ."],["1337","56","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380253\" data-slug=\"likkutei-torah\" data-id=\"4001380253\">קו\"א קסא, א</a>. לקו\"ת ראה שם. ולהעיר שאות א' היא מאותיות אהו\"י – שנכללות בנקודות והן אותיות שבמחשבה (ראה לקו\"ת בהר מא, ב)."],["1338","57","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז</a>."],["1339","58","ראה ד\"ה בסוכות תשבו תשל\"ו ס\"י (לעיל ע' קלב) שי\"ל שמה שהזריחה דבחי' סוכה אחת דלעתיד מאירה גם עתה הוא ע\"ד מש\"כ הרמב\"ם (הל' תשובה ספ\"ח) בפירוש עולם הבא, שעוה\"ב הוא מצוי ועומד ומה שנקרא עולם הבא הוא לפי שבא לאחרי העבודה בעוה\"ז, ועיי\"ש."],["1340","59","שה\"ש ו, ח."],["1341","60","שהש\"ר עה\"פ. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370222\" data-slug=\"torah-or\" data-id=\"3901370222\">תו\"א שמות מט, ב</a> ואילך."],["1342","61","פרש\"י ר\"פ בהר. תו\"כ שם."],["1343","62","פ\"כ."],["1344","63","ראה בן פורת יוסף (כג, ד) בשם הבעש\"ט."],["1345","64","ברכות פ\"א ה\"ה."],["1346","65","ואתחנן ו, ד."],["1347","66","טור או\"ח סס\"א."],["1348","67","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>."],["1349","68","ר\"ה כו, ב."],["1350","69","שם כז, ב. שו\"ע אדה\"ז סתקפ\"ו ס\"ט. ועוד."],["1351","70","הל' תשובה פ\"ג ה\"ד."],["1352","71","יומא מה, א."],["1353","72","שו\"ע אדה\"ז או\"ח סתרכ\"ו ס\"ג."],["1354","73","משלי ג, ו."],["1355","74","י\"ל ע\"ש לב חכם לימינו (<a class=\"ft-cite\" href=\"#/read/tanya/3401310014\" data-slug=\"tanya\" data-id=\"3401310014\">תניא פ\"ט</a>)."],["1356","75","רמב\"ם הל' דעות רפ\"ה."],["1357","76","משנת חסידים."],["1358","77","סידור רסג, ג."],["1359","78","שם פפ\"ז."],["1360","79","סוכה לב, א."],["1361","80","שם לב, ב."],["1362","81","ראה רש\"י ד\"ה אחווינא שבת כ, ב."],["1363","82","סוכה לה, א."],["1364","83","וככה פצ\"ד."],["1365","84","ראה אוה\"ת (סוכות ע' א'תשלט): מקבל קור וחום כו'. ובסדור (רסה, א): אינו מתפעל (מהם)."],["1366","85","ויק\"ר פ\"ל, יב."],["1367","86","וככה פצ\"ח."],["1368","87","ישעי' יב, ג."],["1369","88","פסחים קט, א."],["1370","89","סוכה נא, א-ב."],["1371","90","ישעי' נה, ו. וראה ר\"ה יח, א."],["1372","91","אוה\"ת שמות ס\"ע ב'תשב ואילך. וראה ב\"ר פמ\"ד, כב."],["1373","92","ויק\"ר פ\"ל, ז."],["1374","93","ראה טז, יג."],["1375","94","או\"ח רסתרמ\"א."],["1376","95","בשלח טו, יז."],["1377","96","עובדי' א, כא."],["1378","97","צפני' ג, ט."],["1379","98","ראה רמב\"ם הל' מלכים ספי\"א."]]],[1500360021,"<h3>אור לערב חג הסוכות ה'תשל\"ט<sup data-n=\"1380\">*</sup></h3>\n<b>ולקחתם</b> לכם ביום הראשון וגו'<sup data-n=\"1381\">1</sup>, ואיתא במדרש<sup data-n=\"1382\">2</sup> וכי ראשון הוא והלא ט\"ו [יום<sup data-n=\"1383\">3</sup>] הוא, אלא ראשון [הוא<sup data-n=\"1383\">3</sup>] לחשבון עונות. דביום הכיפורים הקב\"ה מוותר לישראל את הכל<sup data-n=\"1384\">4</sup>, ומיום הכיפורים<sup data-n=\"1385\">5</sup> עד החג כל ישראל עסוקין במצוות, זה עוסק בסוכתו וזה בלולבו, וביום הראשון של חג אומר להם הקב\"ה מאן דאזל אזל ומן הכא ולהלאה<sup data-n=\"1386\">6</sup> חושבנא. ומזה מובן<sup data-n=\"1387\">7</sup>, דמצות נטילת ד' מינים בט\"ו תשרי הוא מפני שהוא ראשון לחשבון. וצריך להבין השייכות דראשון לחשבון לנטילת ד' מינים. וביותר צריך ביאור ע\"פ מה דאיתא במדרש<sup data-n=\"1388\">8</sup>, ישראל ואוה\"ע באין לפני הקב\"ה בראש השנה ולית אנן ידעין מאן נצח, אלא במה שישראל יוצאין מלפני הקב\"ה ולולביהן ואתרוגיהן בידן אנו יודעים דישראל אינון ניצוחייא, לפיכך משה מזהיר להם לישראל ואומר להם ולקחתם לכם כו'. היינו, דמצות נטילת ד' מינים בחג הסוכות באה בהמשך להדין דר\"ה, ולמה אומר ולקחתם לכם ביום הראשון, שמצות נטילת ד' מינים ביום זה הוא (לא מפני שהוא יום הט\"ו לר\"ה, אלא) מפני שבו מתחיל ענין חדש, ראשון לחשבון.\nב) <b>ויובן</b> זה בהקדים החילוק שבין סוכה לד' מינים. דעם היות ששניהם מורים על ענין האחדות (כדלקמן), אעפ\"כ חילוק ביניהם. שהאחדות דסוכה היא אחדות בעצם, שאין בה (מלכתחילה) התחלקות פרטים<sup data-n=\"1389\">9</sup>. שלכן כל ישראל ראויים לישב בסוכה אחת<sup data-n=\"1390\">10</sup>, לפי שסוכה היא למעלה מהתחלקות, משא\"כ ענין מצות נטילתד' מינים הוא שמריבוי נעשה אחדות. דהגם שהם ד' מינים שונים ומן הקצה אל הקצה, כדאיתא במדרש<sup data-n=\"1391\">11</sup> דד' מינים שבלולב הם כנגד ד' סוגים שבישראל, מהסוג שכנגד אתרוג שיש בו טעם וריח (תורה ומעשים טובים) עד להסוג שכנגד ערבה שאין בה לא טעם ולא ריח, והם נעשים כולם אגודה אחת<sup data-n=\"1392\">12</sup>. וגם להפירוש<sup data-n=\"1393\">13</sup> שד' המינים רומזים על הקב\"ה, הנה מזה שהענינים דלמעלה (הקב\"ה) מרומזים בד' מינים, מובן, שהם ד' מדריגות שונות [ועל פי הידוע שכל הפירושים שבאותו הפסוק שייכים זה לזה<sup data-n=\"1394\">14</sup>, יש לומר, שהחילוק בד' המדריגות דלמעלה המרומזים בד' המינים הוא מן הקצה אל הקצה, בדוגמת החילוק שבין ד' סוגים הנ\"ל דישראל], ועל ידי מצות נטילת ד' מינים [שכל ד' המינים הם מצוה אחת<sup data-n=\"1395\">15</sup>] הם מתאחדים.\nג) <b>והנה</b> לאחרי מצות ישיבה בסוכה ומצות נטילת ד' מינים באה המצוה דהקרבת קרבנות החג<sup data-n=\"1396\">16</sup> שעיקרם הם הע' פרים [כיון שפר (שור) הוא המלך שבבהמות<sup data-n=\"1397\">17</sup>] כנגד שבעים אומות<sup data-n=\"1398\">18</sup>. דע\"י הקרבת הע' פרים [ועד\"ז עכשיו ע\"י אמירת פסוקי הקרבנות דע' פרים, ונשלמה פרים שפתינו<sup data-n=\"1399\">19</sup>] נעשה בירור האומות<sup data-n=\"1400\">20</sup>. ויש לומר, שהשייכות דבירור האומות ע\"י הקרבת הע' פרים למצות נטילת ד' מינים היא, כי תכלית שלימות הנצחון דישראל שמתגלה ע\"י נטילת ד' מינים [דעל ידי שישראל לולביהן ואתרוגיהן בידן יודעים דישראל אינון ניצוחייא, כנ\"ל ממדרש] הוא, שגם האומות יסכימו לזה, וע\"י הקרבת הע' פרים כנגד ע' אומות הם מתבררים ומזדככים ועד שהם מסכימים להנצחון דישראל. וזוהי גם השייכות דאמירת הלל בז' ימי הסוכות להקרבת הע' פרים [דזה שגומרין את ההלל בכל ימי החג הוא לפי שהם חלוקים בקרבנותיהם<sup data-n=\"1401\">21</sup>], כי ע\"י הבירור והזיכוך שנעשה בהאומות ע\"י הקרבת הע' פרים, נעשה הללו את הוי' כל גוים שבחוהו כל האומים כי גבר עלינו חסדו גו'<sup data-n=\"1402\">22</sup>, שהגוים והאומים משבחים את הוי' על זה שגבר <i>עלינו</i> חסדו.ד) <b>והנה</b> זה שהגוים והאומים מהללים ומשבחים את ה' על זה שגבר עלינו חסדו הוא ענין נעלה ביותר<sup data-n=\"1403\">23</sup>. ועד אשר (בפרט אחד) הוא נעלה יותר מהענין דגבר עלינו חסדו כמו שהוא מצד עצמו. כי עי\"ז (שהגוים מהללים כו') נשלמת הכוונה דנתאוה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"1404\">24</sup>, בתחתון שאין תחתון למטה ממנו<sup data-n=\"1405\">25</sup>. וכמובן גם מהמאמר ד\"ה ברוך תהי' מכל העמים של בעל ההילולא<sup data-n=\"1406\">26</sup>, דאיתא בירושלמי<sup data-n=\"1407\">27</sup> אם ברכך גוי ענה אחריו אמן שנאמר<sup data-n=\"1408\">28</sup> ברוך תהי' מכל העמים, ומביא בהמאמר דאיתא בכתבי האריז\"ל<sup data-n=\"1409\">29</sup> שאמן הו\"ע יחוד הוי' ואד' [דזהו שאמן בגימטריא הוי' אד'<sup data-n=\"1410\">30</sup>]. והענין הוא<sup data-n=\"1411\">31</sup>, דהוי' הוא שם העצם<sup data-n=\"1412\">32</sup> (עצמות אוא\"ס שלמעלה מעולמות<sup data-n=\"1413\">33</sup>), ושם אד' הוא כמרז\"ל<sup data-n=\"1414\">34</sup> לך נאה לקרות אדנ' שאתה אדון לכל בריותיך. דנוסף לזה ששם אד' הוא בספירת המלכות<sup data-n=\"1415\">35</sup>, דמלכות היא שרש הנבראים, הנה מלשון רז\"ל שאתה אדון לכל בריותיך (בריותיך דוקא) משמע שהשם אד' הוא על נבראים אלו שהם בריות בעלמא<sup data-n=\"1416\">36</sup>. ועל ידי היחוד דהוי' ואד', שבאד' מאיר הוי', נעשה כן גם בהנבראים שנתהוו משם אד' [כולל גם נבראים אלה שהם בריות בעלמא], שמאיר בהם גילוי עצמות אוא\"ס שלמעלה מעולמות, ועד שנעשים דירה לו ית', לו לעצמותו<sup data-n=\"1417\">37</sup>.וזהו אם ברכך גוי ענה אחריו אמן, דישראל הם למעלה מעולמות, וע\"י שגוי מכיר מעלתו של ישראל ועד שמברך אותו, נעשה זה הכנה והקדמה<sup data-n=\"1418\">38</sup> ליחוד הוי' ואד', ולדירה לו ית' בתחתונים.\nה) <b>והנה</b> כיון שתכלית בריאת האדם הוא לעשות לו ית' דירה בתחתונים<sup data-n=\"1419\">39</sup>, שזה נעשה ע\"י שעבודתו את ה' היא באופן כזה שגם גויים וכו' מכירים את מעלתו ועד שמברכים אותו, מובן, שלכאו\"א מישראל נותנים כח מלמעלה על זה. ובפרט בדורות האחרונים שלפני הגאולה, שצריך לגמור ולהשלים עשיית הדירה, שהנתינת כח על זה היא עוד יותר. ויש לומר, דזהו גם מהטעמים על זה שסיפר כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1420\">40</sup>, שאדמו\"ר מהר\"ש (בעל ההילולא) הי' נוסע בכל יום מימי החול לטייל, ופעם (מצד סיבה) נסע בדרך אחרת, וכל האנשים מעמי הארץ שהיו שם, כשראו אותו כרעו והשתחוו לפניו. וכששאלו אח\"כ את אדמו\"ר מהר\"ש עד\"ז, ענה: אויף וועמען דען שטייט ברוך תהי' מכל העמים. דהטעם על זה שכ\"ק מו\"ח אדמו\"ר סיפר מאורע זה וצוה לפרסמו, יש לומר שהוא בכדי להוסיף בהנתינת כח על זה לכאו\"א מישראל. דנוסף על הנתינת כח שע\"י המאורע עצמו, דכיון שמאורע זה הי' אצל נשיא, דהנשיא הוא הכל<sup data-n=\"1421\">41</sup>, הוא נתינת כח לכאו\"א מישראל<sup data-n=\"1422\">42</sup>, הנה עי\"ז שנתגלה ונתפרסם ע\"י נשיא, ניתוסף עי\"ז עוד יותר בהנתינת כח.\nו) <b>ויש</b> לומר, דהנתינת כח מלמעלה על עבודה זו היא (בעיקר) בחג הסוכות. דע\"י שבחג הסוכות יודעים כולם (גם הגוים כו') שישראל אינון ניצוחייא, ונוסף שהם יודעים מזה הם מסכימים לזה ועד שהם מהללים כו' את הוי' על זה שגבר עלינו חסדו (כנ\"ל סעיף ג), הנה מזה נמשכת נתינת כח על העבודה דברוך תהי' מכל העמים במשך כל השנה. ויש להוסיף, דענין נצחון (ישראל אינון ניצוחייא) הוא שמנצחים את המנגד. דמזה מובן, דזה שגילוי הנצחון בחג הסוכות הוא באופן שגם הגוים כו' מהללים כו', הוא, שגם אלה שהיו תחלה מנגדים, גם הם נהפכים לאוהבים, ומהללים כו' את הוי' על זה שגבר עלינו חסדו. ולכן, גם הנתינת כח שנמשכת מחג הסוכות על העבודה דברוך תהי' מכל העמים במשך כל השנה היא גם בנוגע לאלה שהיו מנגדים, ברוך תהי' <i>מכל</i> העמים. ומזה הוראה לכאו\"א מישראל, שגם כשישנם לפעמים כאלה שמונעים ומעכבים אותו מעבודתו, אין זה צריך לגרום חלישות ח\"ו בעבודתו (ומכ\"ש שאין מקום למחשבת יאוש ח\"ו), וכשמחליט למלאות את שליחותו מבלי להתחשב עם שום מניעות ועיכובים, אזי יראה בגילוי בעיני בשר שכל המניעותאין בהם ממש<sup data-n=\"1423\">43</sup>, ואדרבא, הכוונה בזה שיש לו מניעות הוא בכדי להגבי' אותו למדריגה נעלית יותר, שתהי' לו העבודה דבירורים וגם העבודה דנסיונות (שלולי המניעות לא הי' מגיע לעבודה זו, שהרי מבקשים ונצטוינו לבקש אל תביאנו לידי נסיון<sup data-n=\"1424\">44</sup>), שעי\"ז יגיע למדריגה נעלית יותר<sup data-n=\"1425\">45</sup>, ועד שסוף סוף, גם אלו שמנעו וכו' יהפכו למסייעים ומברכים, ברוך תהי' <i>מכל</i> העמים, ועי\"ז תושלם הכוונה דנתאווה הקב\"ה להיות לו ית' דירה בתחתונים, בתחתון שאין תחתון למטה ממנו.\nז) <b>והנה</b> בכדי לפעול הבירור דאוה\"ע, ובפרט דאלו שמנגדים, הוא ע\"י התעוררות וגילוי בחינת יחידה שבנפש. דכיון שהניצוצות שבהם הם בתכלית ההעלם וההסתר, לכן<sup data-n=\"1426\">46</sup>, בירור ניצוצות אלה הוא ע\"י התעוררות נקודת הנפש שלמעלה מהתפשטות וגילוי, יחידה שבנפש. ובפשטות, דע\"י שמעורר בחינת היחידה שבו הוא עומד בתוקף חזק, שבכדי שיהי' לו תוקף חזק לעבוד עבודתו (מבלי להתחשב עם המנגדים) הוא ע\"י התעוררות היחידה שבו<sup data-n=\"1427\">47</sup>, וע\"י תוקף זה פועל סוף סוף גם על המנגדים שנהפכים למסייעים כו' (כנ\"ל סעיף ו). ואף שענין זה (שהמנגדים נהפכים למסייעים כו') הוא תוצאה (לכאורה) מגילוי היחידה שבו, מ\"מ, יש בזה עילוי לגבי הענין דגילוי היחידה. כי בגילוי היחידה לא נעשה דבר חדש, משא\"כ זה שהמנגד נהפך למסייע (היפך הטבע שלו) הוא התחדשות<sup data-n=\"1428\">48</sup>, נוסף שעי\"ז דוקא נשלמת הכוונה דדירה בתחתונים, בתחתון שאין תחתון למטה ממנו.\nח) <b>ועד\"ז</b> הוא גם בהענין דבירור הגוים כו' (הללו את ה' כל גוים גו') שבחג הסוכות, שזה בא לאחרי הגילוי דבחינת יחידה. והענין הוא, דכללות העבודה דעשי\"ת היא מעומק הלב, ממעמקים קראתיך<sup data-n=\"1429\">49</sup>. ואומר ממעמקים לשון רבים, שני עומקים, חי' ויחידה<sup data-n=\"1430\">50</sup>. ובפרט בר\"ה (התחלת עשי\"ת), ומכ\"ש ביוהכ\"פ שבעשי\"ת עצמם הוא זמן תשובה כו' קץ מחילה וסליחה<sup data-n=\"1431\">51</sup>, שהעבודה אז היא בבחינת אחת (יחידה<sup data-n=\"1432\">52</sup>) בכל ג' הענינים דעולם שנה נפש<sup data-n=\"1433\">53</sup>. והגילוי דבחינת אחת (שנמשכהבעשי\"ת ובפרט בר\"ה ויוהכ\"פ) הוא בחג הסוכות [כידוע<sup data-n=\"1434\">54</sup> בפירוש הכתוב<sup data-n=\"1435\">55</sup> בכסה ליום חגינו, שכל הענינים שבעשי\"ת הם בכיסוי והעלם (בכסה), מתגלים הם בחג הסוכות. וזהו שהעבודה דעשי\"ת קשורה עם בכי', ועד שמי<sup data-n=\"1436\">56</sup> שאינו בוכה בעשי\"ת<sup data-n=\"1437\">57</sup> אין נשמתו שלימה, משא\"כ סוכות הוא זמן שמחתינו, כי שמחה היא דוקא מדבר שבגילוי<sup data-n=\"1438\">58</sup>, וע\"י השמחה ניתוסף עוד יותר בהגילוי, דטבע השמחה היא להוציא מן ההעלם אל הגילוי<sup data-n=\"1439\">59</sup>, ועד שהיא פורצת כל גדרים<sup data-n=\"1440\">60</sup>].\n<b>ובהגילוי</b> דבחינת אחת בחג הסוכות שתי דרגות. דתחלת הגילוי הוא ע\"י ישיבה בסוכה, בחינת אחת, כל ישראל ראויים לישב בסוכה אחת<sup data-n=\"1441\">61</sup>. וגילוי זה הוא בבחי' מקיף. וע\"י מצות נטילת ד' מינים נמשך הגילוי בפנימיות, וכמבואר בכ\"מ<sup data-n=\"1442\">62</sup>. ויש לקשר זה עם המבואר לעיל (סעיף ב) שהאחדות דסוכה היא אחדות בעצם שמלכתחילה אין בה התחלקות פרטים משא\"כ האחדות שבמצות נטילת ד' מינים היא דהגם שישנם פרטים מחולקים מ\"מ הם באחדות, כי פנימי הוא בבחי' התחלקות<sup data-n=\"1443\">63</sup>, ולכן, האחדות דסוכה שאין בה התחלקות, היא בבחי' מקיף, וע\"י האחדות בד' המינים, שהם כנגד ד' סוגים שבישראל, ועד\"ז כנגד ד' הדרגות שבכל אחד<sup data-n=\"1444\">64</sup>, היא נמשכת בפנימיות.\nט) <b>וע\"י</b> גילוי האחדות בהפרטים שבישראל (ד' הסוגים שבכלל ישראל, וד' הדרגות שבנשמת כל אחד), נמשך ע\"י מצות נטילת ד' מינים עוד ענין, שעל ידם מתגלה שישראל אינון ניצוחייא, ובאופן שגם אומות העולם מסכימים לזה, ועד שהם מהללים ומשבחים את הוי' על זה שגבר עלינו חסדו. והענין הוא, דענין הריבוי הוא בעיקר באוה\"ע. דנוסף לזה שאתם המעט מכל העמים<sup data-n=\"1445\">65</sup> וישראל אחד בשבעים באומות<sup data-n=\"1446\">66</sup>, הנה כל ישראל הם קומה אחת<sup data-n=\"1447\">67</sup>, וענין הריבוי (דברים נפרדים) הוא בגויםואומות העולם<sup data-n=\"1448\">68</sup>. והנה הטעם על זה שכל ישראל הם באחדות הוא מפני ששרשם הוא בהוי', הוי' אחד<sup data-n=\"1449\">69</sup>. ומזה מובן, דענין האחדות דישראל הוא נוסף ע\"ז שאינם נפרדים זה מזה (כאוה\"ע), אלא שהם נעלים (בשלילה) גם מהתחלקות דמלאכים<sup data-n=\"1450\">70</sup> ודעולמות שנתהוו משם אלקים לשון רבים<sup data-n=\"1451\">71</sup>, ויתירה מזו, שהם למעלה גם מההתחלקות דשם אלקים (לשון רבים), שבכללות הוא אור הממכ\"ע שמחי' כל עולם וכל נברא לפי ערכו. אלא שאעפ\"כ, כיון שגם בישראל יש ענין הריבוי (בחיצוניות), הנה ע\"י המשכת האחדות בהריבוי דישראל, עי\"ז היא נמשכת גם בהריבוי דשם אלקים, ועי\"ז גם בהריבוי דעולמות ונבראים, ועד לריבוי הנבראים שבעוה\"ז הגשמי [דענין מה רבו מעשיך ה'<sup data-n=\"1452\">72</sup> (ההתחלקות לריבוי פרטים) הוא בעיקר בעוה\"ז הגשמי דוקא], כולל גם הריבוי דאומות העולם. ויש לומר, דזהו הקשר דשני הפירושים בענינם של ד' מינים, דלפירוש אחד הם כנגד ד' סוגים שבישראל ולפירוש אחד הם כנגד ד' דרגות דלמעלה (כנ\"ל סעיף ב), דענין ד' הדרגות שלמעלה הוא שאור הממכ\"ע מחי' ומהוה את ד' העולמות אבי\"ע, כל עולם לפי ערכו. וע\"י המשכת האחדות בהריבוי (ד' סוגים וד' דרגות) דישראל, עי\"ז ממשיכים זה גם בבחינת הריבוי שבאור הממלא (ד' דרגות דלמעלה), ועי\"ז – גם בהריבוי דעולמות וכו' ועד בהריבוי דאוה\"ע.\nי) <b>וע\"פ</b> כל הנ\"ל מובן, דזה שע\"י נטילת ד' מינים פועלים שגם הגוים כו' יסכימו לנצחונם של ישראל ועד שיהללו וישבחו את ה' על זה, הוא נעלה יותר (בפרט אחד) מהנצחון עצמו. כי זה שגם הגוים, ובפרט אלה שהיו תחלה מנגדים (והי' צריך לנצחם), מהללים ומשבחים את ה' על זה שגבר <i>עלינו</i> חסדו, הו\"ע של התחדשות (ע\"ד שנת\"ל סעיף ז), נוסף לזה שעי\"ז נשלמת הכוונה דדירה בתחתונים, בתחתון שאין תחתון למטה ממנו. והגם שענין זה (ביטול העמים לישראל) יהי' בעיקר לע\"ל, כדאיתא בנבואת זכרי'<sup data-n=\"1453\">73</sup> דלכל אחד מישראל יהיו ב' אלפים וח' מאות עבדים (מאוה\"ע) שיחזיקו בד' כנפות הטלית שלו, הנה מעין זה הוא גם בזמן הגלות, ובפרט בהזמן שבסמיכות לביאת המשיח (כנ\"ל סעיף ה).\n<b>וזהו</b> ולקחתם לכם ביום הראשון ראשון לחשבון, דהגם שגילוי הנצחון דישראל שע\"י נטילת הד' מינים הוא גילוי הנצחון שהי' בר\"ה וענין זה שבנטילת ד' מינים בחג הסוכות שייך לזה שהוא יום הט\"ו לר\"ה, מ\"מ, זה שע\"י נטילת ד' מינים פועלים שהגוים יסכימו לנצחונם של ישראל ועד שיהללו וישבחו על זה הו\"ע <i>חדש</i>, ולכן אומר ולקחתם לכם ביום <i>הראשון</i>, ראשון לחשבון.<b>ועפ\"ז</b> י\"ל מה שארז\"ל<sup data-n=\"1454\">74</sup> בשכר שלשה ראשון [שביתת הרגל דפסח ושביתת הרגל דחג ונטילת לולב<sup data-n=\"1455\">75</sup>] זכו לשלשה ראשון, להכרית זרעו של עשו לבנין ביהמ\"ק ולשמו של משיח, וידוע<sup data-n=\"1456\">76</sup> דבחי' ראשון דד' מינים הוא נעלה יותר מבחי' ראשון דסוכה<sup data-n=\"1457\">77</sup>, דלכאורה, כיון שענין ד' מינים הוא המשכת המקיף דסוכה (בפנימיות) איך שייך שיהיו נעלים יותר מסוכה, די\"ל הביאור בזה, כי ע\"י העבודה דד' מינים משלימים ישראל הכוונה דנתאוה הקב\"ה להיות לו ית' דירה בתחתונים, ולכן, גם השכר שמגיע להם עי\"ז הוא גילוי העצמות.\n<b>ויהי</b> רצון שמזמן שמחתינו דסוכות (ולקחתם לכם גו' ושמחתם גו'<sup data-n=\"1458\">78</sup>) יבואו בקרוב ממש לשמחה הכי גדולה, שמחת עולם על ראשם<sup data-n=\"1459\">79</sup>, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, יבוא ויגאלנו ויוליכנו קוממיות לארצנו, במהרה בימינו ממש.\n**********",[["1380","*","יצא לאור ב<b>קונטרס חג הסוכות – תש\"נ</b>, \"לקראת חג הסוכות . . <i>יום ד' ערב יג תשרי שנת ה'תש\"נ</i>\"."],["1381","1","אמור כג, מ."],["1382","2","תנחומא אמור כב, הובא בטור או\"ח הל' ר\"ה סתקפ\"א. וראה גם פסיקתא דר\"כ פיסקא ולקחתם לכם (בהוצאת באָבער – קפב, ב ואילך). ויק\"ר פ\"ל, ז. יל\"ש עה\"פ אמור שם (רמז תרנא). וראה גם קה\"ר פ\"ט, ז."],["1383","3","כ\"ה בתנחומא שם. ובטור שם ליתא. ובתנחומא באָבער כאן: והלא יום חמשה עשר הוא, אלא מאי ראשון, ראשון לחשבון עונות."],["1384","4","כ\"ה הלשון בתנחומא שם (ועד\"ז ביל\"ש וקה\"ר שם). וראה דרישה לטור שם סק\"ט דביוהכ\"פ נמחלו כל העוונות (ולא רק רובן)."],["1385","5","פסיקתא דר\"כ, ויק\"ר ויל\"ש שם. ובב\"י שם משמע שכ\"ה גירסתו (גם) בתנחומא שם."],["1386","6","כ\"ה בב\"י שם. ובויק\"ר שם \"מן הכא נחיל חושבנא\". ובקה\"ר שם \"מן הכא ולהלן הוא חושבנא\"."],["1387","7","ובפרט, שמצות סוכה וחגיגה תלאם הכתוב במנין ט\"ו בחודש (ראה ב\"י וב\"ח שם), ובמצות נטילת ד' מינים <i>שינה</i> ותלה ביום ראשון."],["1388","8","ויק\"ר שם, ב. יל\"ש שם. וראה גם פסיקתא שם. תנחומא אמור יח."],["1389","9","ראה בארוכה ד\"ה בסוכות תשבו ה'תשל\"ו ס\"ב ואילך (לעיל ע' קכז ואילך. <i>וש\"נ</i>) בענין המקיף דסוכה שהוא למעלה מהתחלקות."],["1390","10","סוכה כז, ב. ובדוגמת ענני הכבוד (בסוכות הושבתי גו'*) שהקיפו את כל ישראל כולם כאיש אחד.\n*) <i>אמור כג</i>,<i> מג</i>.<i> וראה סוכה יא</i>,<i> ב (לפי דיעה אחת) שענני כבוד היו</i>.<i> וכ\"ה בפשוטו של מקרא – פרש\"י עה\"פ</i>.<i> וכ\"ה גם להלכה – טושו\"ע (ודאדה\"ז) או\"ח הל' סוכה ר\"ס תרכה</i>."],["1391","11","ויק\"ר פ\"ל, יב."],["1392","12","וגם האחדות שבכל מין גופא הוא שמריבוי נעשה אחדות. וכמו באתרוג – ההתאחדות של האוירים דו' תקופות השנה. ועד\"ז בשאר המינים. – ראה בארוכה ד\"ה וחג האסיף ה'תשמ\"ג ס\"ב (לקמן ע' קעג ואילך). וש\"נ."],["1393","13","ויק\"ר שם, ט."],["1394","14","כידוע הראי' לזה מ\"שעטנז\" (נדה סא, ב) – ראה לקו\"ש ח\"ג ע' 782. ובכ\"מ."],["1395","15","ראה סהמ\"צ להרמב\"ם (שורש יא) שהם לא <i>ד</i>' מצוות כ\"א מצוה <i>אחת</i> דוקא."],["1396","16","ישיבה בסוכה מתחילה משקידש החג; נטילת ד\"מ – מתחיל בבוקר; והקרבת מוספין הם לאחרי כו\"כ עבודות היום. ויש לומר, כי בתחלה צריך להמשיך בחינת האחדות שלמעלה מהתחלקות (סוכה); ולאח\"ז ממשיכים זה גם בפרטים, שגם הפרטים יתאחדו כאחד (ד' מינים); ולאח\"ז ממשיכים בע' אומות (פרי החג)."],["1397","17","חגיגה יג, ב."],["1398","18","סוכה נה, ב. במדב\"ר פכ\"א, כד. פרש\"י עה\"פ פינחס כט, יח. שם, לה."],["1399","19","הושע יד, ג."],["1400","20","מאמרי אדמו\"ר האמצעי דברים ח\"ד ע' א'תפט ואילך. המשך תרס\"ו ע' מ. וראה בארוכה ד\"ה בסוכות תשבו ה'תשל\"ו ס\"א וס\"ח (לעיל ע' קכו. ס\"ע קל ואילך)."],["1401","21","ערכין י, סע\"א ואילך. טור ושו\"ע אדה\"ז או\"ח הל' סוכה סי' תרמד."],["1402","22","תהלים מזמור קיז. וע\"פ מ\"ש בפנים יובן השייכות דפסוק זה לחג הסוכות – ראה סידור (עם דא\"ח) שער הסוכות רנט, ג. שם רס, ד. אוה\"ת דרושים לסוכות ד\"ה הללו את ה' כל גוים (ע' א'תשסז)."],["1403","23","להעיר גם מפרש\"י עה\"ת בתחלתו, \"שאם יאמרו אוה\"ע לישראל לסטים אתם כו' הם אומרים <i>להם</i> כו'\", דזה שנכתבו כו\"כ פרשיות בתורה, יותר מספר שלם, הוא בכדי שיוכלו להסביר <i>לאוה\"ע</i> שכיבוש א\"י אינו גזילה, בכדי שגם הם יסכימו על זה. ולהעיר גם מספר השיחות תורת שלום ע' 70 ואילך, שכל הענין דשבירת הכלים דתוהו הי' בכדי \"<i>שהם</i> יאמרו כפי רצונו\"."],["1404","24","ראה תנחומא נשא טז. בחוקותי ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["1405","25","תניא שם."],["1406","26","סה\"מ תרכ\"ח ע' קעא. וראה ג\"כ ד\"ה זה תרכ\"ט (סה\"מ תרכ\"ט (הוצאת תשנ\"ב) בסופו (ע' תג ואילך))."],["1407","27","ברכות ספ\"ח."],["1408","28","עקב ז, יד."],["1409","29","פע\"ח שער יא (שער כוונת אמן) רפ\"א. שער הכוונות ענין כוונת חזרת העמידה דרוש ה'. הנסמן באוה\"ת בהר כרך ד ע' א'קנו."],["1410","30","ויש לומר, דההתאחדות של הוי' ואד' בהגימטריא דתיבת אמן (תיבת אחת) היא התאחדות גדולה יותר מההתאחדות דשוע טווי ונוז בתיבת שעטנז (ראה לעיל הערה 14) – כיון שבהגימטריא דתיבת אמן אין ניכר כלל שהוא צירוף שני ענינים (משא\"כ שעטנז)."],["1411","31","בהבא לקמן (בענין יחוד הוי' ואד') ראה גם ד\"ה להבין ענין רשב\"י ה'תשמ\"ה ס\"ו (לקמן ח\"ג ע' רפא ואילך)."],["1412","32","כ\"מ הל' עכו\"ם פ\"ה ה\"ז. פרדס שער יט (שער שם בן ד'). מו\"נ ח\"א פס\"א ואילך. עיקרים מאמר ב פכ\"ח."],["1413","33","להעיר, שגם שם הוי' מלשון מהוה (זח\"ג רנז, סע\"ב. פרדס שער א (שער עשר ולא תשע) פ\"ט. שעהיוה\"א רפ\"ד) הוא למעלה מגדר עולם (זמן ומקום), כמבואר בשעהיוה\"א פ\"ז (פב, א) שמדבר שם בענין הוי' מלשון מהוה*. ועאכו\"כ שכ\"ה בשם הוי' כמו שהוא שם העצם שמורה על עצמותו."],["1414","34","ב\"ר פי\"ז, ד."],["1415","35","שעהיוה\"א פ\"ז (פא, ב). ובכ\"מ."],["1416","36","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פל\"ב</a>."],["1417","37","ד\"ה מי יתנך תקס\"ה (סה\"מ תקס\"ה ח\"א ע' תפט. ועם הגהות – ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770311\" data-slug=\"or-hatorah-hb\" data-id=\"8316770311\">אוה\"ת שה\"ש כרך ב ע' תרעט</a>\n*) <i>שהרי זה בא בהמשך להמבואר שם פ\"ד (עט</i>,<i> רע\"א) </i>\"<i>דשם הוי' פירושו שמהוה כו'</i>\".<i> וגם בפ\"ז שם</i>,<i> הטעם על זה שהוא </i>\"<i>למעלה מבחי' מקום</i>\"<i> הוא </i>\"<i>כי הוא </i><b>מהוה</b><i> תמיד את כל בחי' המקום כו'</i>\".ואילך). אוה\"ת בלק ע' תתקצז. סה\"מ תרס\"ב ע' שלח. תרע\"ח ע' קצג. המשך תרס\"ו ס\"ע ג. שם ע' תמה. סה\"מ תרצ\"ט ע' 84. ובכ\"מ."],["1418","38","אבל היחוד גופא נעשה ע\"י עניית אמן <i>דישראל</i>."],["1419","39","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מט, סע\"א</a>). <i>ובכ\"מ</i>."],["1420","40","ראה גם שיחת ש\"פ עקב, כ\"ף מנחם-אב ה'תשט\"ז (תורת מנחם – התוועדויות חי\"ז ע' 145)."],["1421","41","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191165\" data-slug=\"likkutei-sichot\" data-id=\"1300191165\">פרש\"י ע\"פ</a> חוקת כא, כא (מתנחומא חוקת כג). וראה רמב\"ם הל' מלכים פ\"ג ה\"ו: לבו (של מלך) הוא לב כל קהל ישראל. וראה לקו\"ש חי\"ט ע' 165 ואילך."],["1422","42","ויש לומר, שהנתינת כח ומעשה דנשיא הוא עוד יותר מהנתינת כח ע\"י אמירה (אמירת תורה) – ע\"ד הענין ד\"מעשה רב\" (ב\"ב קל, ב)."],["1423","43","ראה בארוכה סה\"מ תרנ\"ז ע' נג. ד\"ה נתת ליראיך ה'תשל\"ו ס\"ה (לקמן ח\"ד ע' נא ואילך). ובכ\"מ."],["1424","44","נוסח ברכות השחר, מברכות ס, ב. וראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רו."],["1425","45","ראה בארוכה ד\"ה נתת ליראיך הנ\"ל ס\"ט וס\"י (לקמן ח\"ד ס\"ע נה ואילך). וראה בהנסמן שם (ע' נ) הערה 35."],["1426","46","ראה בארוכה ד\"ה נתת ליראיך ה'תשי\"א [תורת מנחם – התוועדויות ח\"ג ע' 180] בענין בירור הניצוצות שבנסיונות, דכיון שהניצוצות הם באופן של \"נקודה\" (שהרי הם בתכלית ההסתר, בלי התפשטות), לכן, גם הבירור שלהם הוא ע\"י נקודת הנפש."],["1427","47","ראה בארוכה ד\"ה הנ\"ל ה'תשל\"ו ס\"ב ואילך (לקמן ח\"ד ע' מט ואילך)."],["1428","48","ראה בארוכה ד\"ה והי' עקב גו' ה'תשכ\"ז ס\"ד-ה (לקמן ח\"ד ע' קצ ואילך)."],["1429","49","תהלים קל, א. – המזמור שאומרים בעשי\"ת (סידור אדה\"ז בסוף פסוד\"ז. ע\"פ פע\"ח שער כח (שער תפלות ר\"ה) פ\"ז)."],["1430","50","ראה ד\"ה שיר המעלות ממעמקים ה'תש\"ג בסופו (סה\"מ ה'תש\"ג ע' 26). וראה גם ד\"ה זה תרס\"ח ס\"ע יב ואילך."],["1431","51","רמב\"ם הל' תשובה פ\"ב ה\"ז."],["1432","52","ראה תוד\"ה עד אחת – מנחות יח, א. וראה (בנוגע ליוהכ\"פ): עט\"ר שער יוהכ\"פ פ\"ב ואילך. ועיי\"ש רפ\"ה. ובכ\"מ."],["1433","53","ראה בארוכה ד\"ה בסוכות תשבו ה'תשל\"ח ס\"ז (לעיל ע' קלז)."],["1434","54","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380937\" data-slug=\"likkutei-torah\" data-id=\"4001380937\">ראה ד</a>\"ה תקעו בלקו\"ת דרושים לר\"ה נד, סע\"ג ואילך; סידור (עם דא\"ח) שער ר\"ה רלה, ב; עט\"ר דרוש לעשי\"ת נז, א; מאמרי אדמו\"ר האמצעי דברים ח\"ג ע' א'ה ואילך. ובכ\"מ. וראה בארוכה ד\"ה בסוכות תשבו ה'תשל\"ו ס\"ג; ה'תשל\"ח ס\"ד ואילך (לעיל ע' קכז; ע' קלו)."],["1435","55","תהלים פא, ד. וראה ד\"ה בסוכות תשבו ה'תשמ\"א הערה 6 (לקמן ע' קסג)."],["1436","56","פע\"ח שער כו (שער יוהכ\"פ) פ\"ה. שעה\"כ דרושי ר\"ה (קודם דרוש א'). סידור האריז\"ל סוף סדר הנסירה."],["1437","57","כ\"ה בדרך חיים שער התשובה פ\"י (יג, ריש ע\"ד). שם פט\"ז (כא, רע\"א). מאמרי אדמו\"ר האמצעי דברים ח\"ג ע' תתקנז (<i>וש\"נ</i>). המשך ר\"ה תרצ\"ה ספכ\"ח (סה\"מ קונטרסים ח\"ב שמ, סע\"ב). <i>ובכ\"מ</i>."],["1438","58","ראה בארוכה ד\"ה שמח תשמח תרנ\"ז בתחלתו (סה\"מ תרנ\"ז ע' קעג ואילך)."],["1439","59","ד\"ה הנ\"ל ע' 47 (סה\"מ שם ע' רכא)."],["1440","60","ד\"ה הנ\"ל ע' 49 (סה\"מ שם ע' רכג ואילך)."],["1441","61","וראה בארוכה ד\"ה בסוכות תשבו ה'תשל\"ח ס\"י (לעיל ס\"ע קלט ואילך)."],["1442","62","סידור (עם דא\"ח) שער הלולב רסג, סע\"ג ואילך. המשך וככה תרל\"ז פפ\"ד ואילך. רד\"ה ולקחתם לכם תרס\"א (סה\"מ תרס\"א ע' קצא). המשך תרס\"ו ע' לב. ובכ\"מ."],["1443","63","סהמ\"צ להצ\"צ פה, ריש ע\"ב. המשך תרס\"ו ע' עדר ואילך."],["1444","64","ראה לקו\"ת ר\"פ בלק. וראה בארוכה ד\"ה אלקי נשמה תרצ\"ט (סה\"מ תרצ\"ט ע' 221 ואילך). ובכ\"מ."],["1445","65","ואתחנן ז, ז."],["1446","66","מדרש הובא בחזקוני עה\"פ שם ו, ד. סידור (עם דא\"ח) רלו, ג. סה\"מ תקס\"ב ע' רסט. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קנ. אוה\"ת הוספות לדברים (כרך ד) ע' א'תתקלד. ועוד."],["1447","67","לקו\"ת ר\"פ נצבים."],["1448","68","ראה פרש\"י עה\"פ ויגש מו, כו (מויק\"ר פ\"ד, ו (בסופה))."],["1449","69","<a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פל\"ב</a>."],["1450","70","שהם משם אלקים (אגה\"ת פ\"ד – צד, א). וראה המשך תרס\"ו ע' תנא \"בנשמות אין הריבוי כ\"כ כמו במלאכים\"."],["1451","71","ראה גם רש\"י עה\"פ וירא כ, יג. וישלח לה, ז."],["1452","72","תהלים קד, כז."],["1453","73","זכרי' ח, כג. וראה שבת לב, ב. פרש\"י לזכרי' שם."],["1454","74","פסחים ה, א."],["1455","75","פרש\"י שם ד\"ה בשכר."],["1456","76","ראה בארוכה לקוטי לוי\"צ למחז\"ל ע' קד ואילך, שראשון דפסח הוא ח\"ס, דסוכה – גלגלתא, ודלולב מיניו – אוירא, ועד לדעת דעתיק שבאוירא, רדל\"א."],["1457","77","בפרש\"י שם (נעתק לעיל) <i>שביתת הרגל</i> דחג. אבל ראה חדא\"ג מהרש\"א שם \"וטעם השביתה בחג הסוכות שנאמר בו הראשון . . (הוא) כמ\"ש כי <i>בסוכות הושבתי</i>\", ושלכן שייך \"לבנין ביהמ\"ק\" שנאמר בו (תהלים עו, ג) \"ויהי בשלם <i>סוכו</i>\". וראה גם לקוטי לוי\"צ שם ע' קה-ו."],["1458","78","אמור כג, מ. וראה חדא\"ג מהרש\"א שם \"וטעם מצות לולב . . ע\"ש השמחה כמ\"ש ולקחתם לכם וגו' ושמחתם וגו' יזכו לשמחה לעתיד בבוא משיח\", עיי\"ש. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191375\" data-slug=\"likkutei-sichot\" data-id=\"1300191375\">לקו\"ש חי\"ט ע' 362</a>."],["1459","79","ישעי' לה, יו\"ד. נא, יא."]]],[1500360022,"(הנחה)\n<b>כנשר</b> יעיר קנו על גוזליו ירחף גו'<sup data-n=\"1460\">1</sup>, הנה מה כתיב לעיל מיני'<sup data-n=\"1461\">2</sup> ימצאהו בארץ מדבר, ואח\"ז מסיים<sup data-n=\"1462\">3</sup> הוי' בדד ינחנו. הנה הפירוש הפשוט בזה הוא, שהקב\"ה נוהג עם בני ישראל ברחמים כמו הנשר המרחף על גוזליו (וכפרש\"י), כלומר, שיש רחמי נשר כפשוטם, ויש רחמים שהם כמו נשר ולמעלה הימנו. והנה כל הענינים שבתורה ישנם בכל העולמות עד למעלה מעלה, ומזה מובן, דכשם שיש ב' בחינות אלו בעוה\"ז הגשמי (נשר וכמו נשר), כך הוא בעולמות שלמעלה ממנו, עולמות בי\"ע, עד לעולם האצילות, דאף שיש בו ע\"ס הרי הוא עולם האחדות, ומ\"מ גם בו יש בחי' נשר והיא מדת הרחמים דאצי', ויש בו בחי' כנשר, היינו רחמים שלמעלה <i>ממדת</i> הרחמים<sup data-n=\"1463\">4</sup>. אמנם אעפ\"כ הרי עיקר התורה היא למטה כמאמר<sup data-n=\"1464\">5</sup> תורה לא בשמים היא, וכתורת הרב המגיד<sup data-n=\"1465\">6</sup> על מארז\"ל<sup data-n=\"1466\">7</sup> דע מה למעלה ממך, שכל הענינים שלמעלה תלויים בך, בעבודת האדם הנמצא למטה, ובפרט אחרי מ\"ת שאז ניתנה התורה למטה ולא בשמים היא (כנ\"ל). ועוד זאת, דכל הגבוה יותר יורד למטה יותר<sup data-n=\"1467\">8</sup>, היינו דהענין הכי נעלה (שבתורה) נמצא דוקא למטה, ומזה מובן גם בענין הנשר, שפסוק זה כולל את ב' הקצוות, דהרחמים הכי עליונים נמשכים דוקא למטה במקום שבו רחמי נשר כפשוטו.\n<b>והענין</b> הוא, דהנה כתיב<sup data-n=\"1468\">9</sup> שלשה המה נפלאו ממני גו' דרך הנשר בשמים גו', ומבואר במ\"א<sup data-n=\"1469\">10</sup> דהפלא הוא איך יש פני נשר שהוא עוף טמא במרכבה העליונה. וצריך להבין<sup data-n=\"1470\">11</sup>, שהרי יש במרכבה גם פני ארי' אל הימין<sup data-n=\"1471\">12</sup> שהוא חי' טמאה, ומדוע הפליאה היא על הנשר דוקא. והביאור בזה, ע\"פ המבואר במ\"א<sup data-n=\"1472\">13</sup> שדרך הנשר (פני נשר שבמרכבה) הו\"ע קו האמצעי. וזהו מה שתמה על פני נשר דוקא<sup data-n=\"1473\">14</sup>, כי פניארי' אל הימין, דפני ארי' שבמרכבה הם בקו הימין העולה בחיצוניות הכתר בלבד, ואין זה פלא כ\"כ, משא\"כ פני נשר שהם בקו האמצעי העולה בפנימיות הכתר<sup data-n=\"1474\">15</sup>, יפלא מאד איך יש פני עוף טמא בפנימיות הכתר.\n<b>וביאור</b> הענין, דהנה דוקא להיות מדת הרחמים מושרשת בפנימיות הכתר, לפיכך נפלה למטה מטה, וזהו שנק' נשר מלשון נשירה ונפילה<sup data-n=\"1475\">16</sup>, דנפיל מן דרגי', עד לעוף טמא שמחוץ למקום הקדושה. ובזה יובן המשך הפסוקים, דכתיב לעיל מיני' ימצאהו בארץ מדבר גו', דמדבר הוא מקום אשר לא ישב אדם שם<sup data-n=\"1476\">17</sup>, היינו שהוא מחוץ למושב האדם העליון<sup data-n=\"1477\">18</sup>, ועד\"ז מחוץ למושב בני ישראל הקרויים אדם<sup data-n=\"1478\">19</sup> אדמה לעליון<sup data-n=\"1479\">20</sup>, כי בכל ישראל יש נפש הקדושה שהיא חלק אלוקה ממעל ממש<sup data-n=\"1480\">21</sup>, וכדכתיב לפנ\"ז<sup data-n=\"1481\">22</sup> כי חלק הוי' עמו גו', ולפיכך אין להם שום שייכות למקום המדבר (שמחוץ לקדושה), ולא זו בלבד שלא ישב אדם (היינו ישראל) שם, אלא שלא עבר שם, היינו שאין לישראל כל שייכות למקום זה. וזהו שממשיך כנשר יעיר קנו גו', כי למקום זה נפלה בחי' נשר.\n<b>אמנם</b><sup data-n=\"1482\">23</sup> גם על מקום זה נאמר ימצאהו בארץ מדבר גו', דגם משם יקבצך ה' אלקיך ומשם יקחך<sup data-n=\"1483\">24</sup>. וההעלאה והתשובה ממקום זה היא ע\"י גילוי בחי' כנשר בדרגא הכי עליונה, בחי' פנימיות הכתר, כי מיני' ובי' אבא לשדי' בי' נרגא<sup data-n=\"1484\">25</sup>, ועי\"ז עולים לפנימיות הכתר. דכיון שכל הגבוה יותר יורד למטה ביותר הרי דוקא ע\"י שעולים ממקום רחוק כזה, העלי' היא למעלה ביותר. וע\"ד המבואר בכ\"מ<sup data-n=\"1485\">26</sup> (מל\"ת להאריז\"ל<sup data-n=\"1486\">27</sup>) בפי' הכתוב<sup data-n=\"1487\">28</sup> כי לא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם, שהמדבר צריך למוצא פי הוי' שבדצ\"ח, משום שמזה שנפלו הניצוצות למטה ביותר (בדצ\"ח שלמטה ממדבר) מוכח ששרשם למעלה יותר, ולכן בכחם דוקא להחיות את המוצא פי הוי' שבמדבר. ועד\"ז יובן למטה מזה, בבחי' נשר שענינה הנפילה מחוץ למקום הקדושה, דדוקא ע\"י העלי' ממקום זה עולים עדלפנימיות הכתר. וזהו טעם ירידת הנשמה למטה מאיגרא רמה לבירא עמיקתא<sup data-n=\"1488\">29</sup>, מבחי' נשמה שנתת בי עד לנפחתה בי<sup data-n=\"1489\">30</sup> בעוה\"ז התחתון, כדי שבעולם זה תהי' העלי' מלמטה ביותר, בסולם המוצב ארצה<sup data-n=\"1490\">31</sup> דוקא, ועי\"ז ראשו מגיע השמימה<sup data-n=\"1490\">31</sup>, למעלה ביותר, עד שהרוח תשוב אל האלקים אשר נתנה<sup data-n=\"1491\">32</sup>. וזהו<sup data-n=\"1492\">33</sup> מה שממשיך&lt;2&gt; יצרנו כאישון עינו, דאישון הוא השחור שבעין כמארז\"ל<sup data-n=\"1493\">34</sup> אין אדם רואה מתוך הלבן שבעין אלא מתוך השחור שבעין, דענין השחור שבעין היינו השחרות וההעלם והריחוק וכו'. דע\"י ההתבוננות בזה שנמצא במקום ההעלם, במקום רחוק, ורע ומר עזבך את ה', עי\"ז בא לתשובה מעומקא דליבא עד שזדונות נעשו לו כזכיות וזכיות.\n<b>וזהו</b> כנשר יעיר קנו על גוזליו ירחף גו', דהריחוף על גוזליו מורה על הרחמים של נשר כפשוטו, דע\"י עבודת התשובה מבחי' נשר למטה עולים לבחי' כנשר יעיר קנו שלמעלה מעלה. וע\"ד מ\"ש במ\"א<sup data-n=\"1494\">35</sup> דאית רצון ואית רצון, דהרצון התחתון כלי וממשיך את הרצון העליון. ועד\"ז יראה תתאה היא כלי ליראה עילאה וחכמה תתאה היא כלי לחכמה עילאה. הרי עד\"ז ע\"י בחי' נשר עולים למדת הרחמים שלמעלה עד לרחמים שלמעלה מעלה ממדה. וזהו ימצאהו בארץ מדבר גו', דמציאה שייך בדבר שנאבד, היינו שגם אלה שנאבדו בארץ מדבר הרי משם יקבצך גו', ועד שהיא בחי' מציאה, ענין שלא לפי ערך היגיעה, כי הקב\"ה לא שיער כביכול בעצמו (האָט זיך ניט געריכט) שימצא את החלק אלוקה בשלימותו במדבר, שהרי הכל בידי שמים חוץ מיראת שמים<sup data-n=\"1495\">36</sup>. ומשום זה הקב\"ה הוא בהתפעלות מעבודת ישראל. ועד שזה מביא לידי תענוג גדול, וכפשטות הענין, דאינו דומה התענוג של מי שהרויח לפי ערך עבודתו (כמ\"ש<sup data-n=\"1496\">37</sup> עובד אדמתו ישבע לחם) למי שמוצא מציאה שזהו לא לפי ערך היגיעה. וזהו שממשיך&lt;1&gt; ישאהו על אברתו, לפי שע\"י עבודת התשובה עולים למעלה מעלה, עד למעלה מבחי' אברתו, היינו למעלה מרמ\"ח אברין דמלכא<sup data-n=\"1497\">38</sup>, כי ישראל קדמו לתורה ומצוות כדאיתא בתד\"א<sup data-n=\"1498\">39</sup> ואני אומר ישראל קדמו שנאמר (בתורה) דבר אל בני ישראל אמור אל בני ישראל כו'<sup data-n=\"1499\">40</sup>. ועד שעולים למקום זה שנאמר עליו הוי' בדד ינחנו גו', ישראל ומלכא בלחודוהי<sup data-n=\"1500\">41</sup>, שישראל ועצומ\"ה ית' כולא חד.<b>והנה</b> ע\"י שענינים אלו נלמדים בתושב\"כ ואח\"כ בתושבע\"פ ועד לתורת חב\"ד שענינה הוא ההסברה ועד שיתפרנסון מיני'<sup data-n=\"1501\">42</sup>, הרי התבוננות זו מביאה לידי מעשה, חיפוש ובירור הניצוצות בכל מקום, ובפרט כשפוגש ניצוצות אלו בהשגחה פרטית, ועי\"ז באים לקיום היעוד הוי' בדד ינחנו גו', כמ\"ש<sup data-n=\"1502\">43</sup> וישכון ישראל בטח בדד עין יעקב, בקרוב ממש, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, יבוא ויגאלנו ויוליכנו קוממיות לארצנו, במהרה בימינו ממש.\n**********",[["1460","1","פרשתנו לב, יא."],["1461","2","שם, י."],["1462","3","שם, יב."],["1463","4","ראה אוה\"ת פרשתנו ע' א'תרפג ואילך. וראה לקו\"ת פרשתנו עח, ג."],["1464","5","נצבים ל, יב. ב\"מ נט, ב."],["1465","6","לקוטי אמרים (הוצאת קה\"ת) סקצ\"ח (נ, סע\"ג)."],["1466","7","אבות פ\"ב מ\"א."],["1467","8","הובא ונתבאר בשערי אורה ע' נח ואילך."],["1468","9","משלי ל, יח-יט."],["1469","10","ל\"ת להאריז\"ל עה\"פ משלי שם."],["1470","11","אוה\"ת שם ע' א'תרפט. ד\"ה כנשר יעיר קנו תרע\"ה (המשך תער\"ב ח\"ב ע' עתר). תרע\"ח (סה\"מ תרע\"ח ע' ל). תשכ\"ט (לעיל ע' קכא ואילך)."],["1471","12","יחזקאל א, י."],["1472","13","אוה\"ת שם ע' א'תרפה ואילך. סה\"מ תרע\"ח שם ע' כד ואילך."],["1473","14","ראה אוה\"ת שם ע' א'תרצ. המשך תער\"ב שם. לעיל ע' קכא."],["1474","15","המשך תער\"ב ח\"א ע' רכ ואילך. סה\"מ תרע\"ח שם ע' כה. סה\"מ תש\"ז ע' 152."],["1475","16","לקו\"ת פרשתנו שם, א. סה\"מ תקס\"ד ע' רכא. וראה קהלת יעקב בערכו."],["1476","17","ירמי' ב, ו."],["1477","18","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380390\" data-slug=\"likkutei-torah\" data-id=\"4001380390\">לקו\"ת נשא כ, ג</a>. ראה לב, סע\"ב ואילך. ועוד."],["1478","19","יבמות סא, רע\"א."],["1479","20","של\"ה כ, ב. רסח, ב. שא, ב. עשרה מאמרות מאמר אם כל חי ח\"ב סל\"ג."],["1480","21","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["1481","22","פרשתנו שם, ט."],["1482","23","בהבא לקמן – ראה לקו\"ת פרשתנו שם, א ואילך. סה\"מ תקס\"ד ע' רכ ואילך. וראה גם אוה\"ת פרשתנו ע' א'תרפג ואילך. א'תרפה ואילך. סה\"מ תרע\"ח שם ע' כד ואילך."],["1483","24","נצבים ל, ד."],["1484","25","כ\"ה ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא רפל\"א</a>. וראה סנהדרין לט, ב."],["1485","26","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380129\" data-slug=\"likkutei-torah\" data-id=\"4001380129\">לקו\"ת צו יג, סע\"ב</a> ואילך. ועוד."],["1486","27","עה\"פ עקב ח, ג."],["1487","28","עקב שם."],["1488","29","לשון חז\"ל – חגיגה ה, ב."],["1489","30","נוסח ברכת השחר (ברכות ס, ב)."],["1490","31","ויצא כח, יב."],["1491","32","קהלת יב, ז."],["1492","33","ראה סה\"מ תקס\"ד שם ע' רכו. אוה\"ת פרשתנו שם ע' א'תרפח."],["1493","34","ויק\"ר פל\"א, ח."],["1494","35","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370395\" data-slug=\"torah-or\" data-id=\"3901370395\">תו\"א ויקהל פז, ד</a>. דרמ\"צ פח, א (מזהר)."],["1495","36","ברכות לג, ב."],["1496","37","משלי יב, יא. כח, יט."],["1497","38","וראה ד\"ה כנשר יעיר קנו תרמ\"א (המשך יונתי תר\"מ ע' מד). תשכ\"ט (לעיל ע' קכא)."],["1498","39","רבה – פי\"ד. וראה סה\"מ תרל\"ה ח\"ב ס\"ע שנו ואילך. וש\"נ."],["1499","40","ראה ב\"ר פ\"א, ד."],["1500","41","ראה זח\"ג לב, א."],["1501","42","תקו\"ז ת\"ו בסופו. וראה כסא מלך שם (הועתק ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071217\" data-slug=\"likkutei-sichot\" data-id=\"1300071217\">לקו\"ש ח\"ז ע' 206</a> הערה 3. חט\"ו ע' 42 הערה 9. ועוד). הקדמת מקדש מלך לזהר."],["1502","43","ברכה לג, כח."]]]]});
